// Sektöre özel slogan, özet, süreç ve kapanış. Uydurma sayı, sonuç vaadi yok; sağlıkta fiyat yok.
window.TV=window.TV||{};TV.M={"Sakal tasarımı":{"s":"Yüz hattınıza bakmadan makası eline almayız.","o":"Yüz şeklinize göre sakal şekillendirme yapar, ustura tıraşla çizgiyi netleştirir, sıcak havlu bakımıyla cildi rahatlatırız.","u":[["Yüz hattı","Çene ve elmacık yapınıza göre sakal boyunu belirleriz."],["Çizgi","Yanak ve boyun hattını önce tarak, sonra makasla çizeriz."],["Ustura","Sıcak havlu sonrası kılları ustura ile temizleriz."],["Bakım","Sakal yağını sürer, evde tarama düzenini gösteririz."]],"k":"Sakalınıza yeni hat çizelim."},"Çocuk berberi":{"s":"Çocuğunuz koltukta ağlamasın, makine sesine önce alışsın.","o":"Çocuk tıraşı ve bebek tıraşını sabırla yaparız, ilk tıraş hatırası için saç tutamını saklarız.","u":[["Tanışma","Koltuğa çıkmadan önce makineyi eline verip gösteririz."],["Oturuş","Yükseltili koltukta anne ya da babanın yanında oturturuz."],["Tıraş","Kısa aralarla, başını oynatmasına izin vererek keseriz."],["Hatıra","İsterseniz ilk saç tutamını kese içinde veririz."]],"k":"Minik müşterimizi bekliyoruz."},"Noter":{"s":"Evrakınız eksik çıkmasın diye gelmeden önce listeyi söyleriz.","o":"Vekâletname, araç satış işlemi ve evrak onayı için gereken belgeleri önceden bildirir, randevu ve evrak bilgisi veririz.","u":[["Belge listesi","Yapılacak işlem için gereken kimlik ve evrakı bildiririz."],["Metin","İşlemin metnini taraflara okuyarak içeriği netleştiririz."],["Kimlik","Taraf kimliklerini ve yetki belgelerini kontrol ederiz."],["İmza","Metin okunduktan sonra imza ve onay işlemi yapılır."]],"k":"Evrak için randevu alın."},"Arabulucu":{"s":"İki tarafı da dinler, kararı taraflara bırakırız.","o":"İş, ticari ve kira uyuşmazlıklarında arabuluculuk başvurusunu alır, görüşmeleri yürütür, varılan uzlaşmayı anlaşma tutanağına geçiririz.","u":[["Başvuru","Uyuşmazlığın konusunu ve tarafları forma yazarız."],["Davet","Karşı tarafa görüşme tarihini bildiririz."],["Oturum","Tarafları ortak ya da ayrı odada dinleriz."],["Tutanak","Anlaşma sağlanırsa metin yazılır, taraflarca imzalanır."]],"k":"Görüşme için başvurunuzu yapın."},"Sigorta acentesi":{"s":"Poliçede neyin dışarıda kaldığını imzadan önce okuruz.","o":"Trafik sigortası, kasko ve konut sigortasında teminatları sade dille anlatır, hasar takibinde dosyanızı şirketle birlikte izleriz.","u":[["Teminat","Aracınızın ya da evinizin neyi karşılaması gerektiğini sorarız."],["Poliçe","Şirket tekliflerini teminat ve muafiyet yönüyle yan yana koyarız."],["Hasar","Kaza ya da hasarda tutanak ve fotoğrafları birlikte toplarız."],["Takip","Ekspertiz ve ödeme sürecini şirkete sorup size bildiririz."]],"k":"Poliçenizi birlikte okuyalım."},"Danışmanlık":{"s":"Önce işinizi dinler, sonra neyi değiştireceğinizi yazarız.","o":"İlk görüşmede işletmenizi dinler, durum analizi ile yol haritası çıkarır, aylık takip ve eğitimle uygulamaya eşlik ederiz.","u":[["Dinleme","İlk görüşmede iş akışınızı ve tıkandığınız yeri anlatırsınız."],["Analiz","Rakamlara ve süreçlere bakıp aksayan noktaları işaretleriz."],["Yol haritası","Adımları sırayla ve sorumlusuyla bir sayfaya yazarız."],["Takip","Her ay yapılanı kontrol eder, planı güncelleriz."]],"k":"İlk görüşmeyi planlayalım."},"İnsan kaynakları":{"s":"Doğru kişiyi bulmak için önce pozisyonu net yazarız.","o":"İşe alım sürecini yürütür, ücret ve özlük dosyasını düzenler, performans sistemi ile eğitim planını işletmenize göre kurarız.","u":[["Pozisyon","Görev tanımını ve aranan nitelikleri sizinle yazarız."],["Aday","Başvuruları eler, görüşmeye uygun adayları size sunarız."],["Özlük","İşe giriş evraklarını ve dosyayı eksiksiz tamamlarız."],["Değerlendirme","Çalışanın ilk dönemini hedeflerle birlikte izleriz."]],"k":"Kadronuzu birlikte kuralım."},"Tercüme bürosu":{"s":"Belgenizin hangi kurumda geçeceğini sorar, ona göre çeviririz.","o":"Yeminli, noter onaylı ve teknik tercümeyi yapar, belgeniz yurt dışında kullanılacaksa apostil takibini üstleniriz.","u":[["Belge","Aslını ya da taramasını inceler, kullanılacağı kurumu sorarız."],["Çeviri","Özel adları ve terimleri kaynaktaki yazımıyla çeviririz."],["Onay","Yeminli tercüman imzalar, gerekirse noter onayı alınır."],["Apostil","Yurt dışı için apostil işlemini takip eder, teslim ederiz."]],"k":"Belgenizi çeviriye gönderin."},"Patent ve marka":{"s":"Adınızı tescil ettirmeden önce aynısı var mı diye bakarız.","o":"Marka araştırmasıyla başlar, marka tescili, patent başvurusu ve tasarım tescilini yürütür, izleme hizmetiyle benzer başvuruları takip ederiz.","u":[["Araştırma","Adınızın benzerlerini marka kayıtlarında tararız."],["Sınıf","Ürün ve hizmetinize uygun marka sınıflarını seçeriz."],["Başvuru","Dosyayı hazırlar, kuruma başvuruyu bizim yaparız."],["İzleme","Yayın sürecinde itiraz ve benzer başvuruları izleriz."]],"k":"Adınızı kayda geçirelim."},"Gümrük müşaviri":{"s":"Konteyner limanda beklemesin, evrak önceden hazır olsun.","o":"İthalat ve ihracat beyannamesini hazırlar, belge kontrolü yapar, antrepo takibini yürüterek gümrük danışmanlığı veririz.","u":[["Belgeler","Fatura, çeki listesi ve menşe belgesini önceden kontrol ederiz."],["Tarife","Ürününüzün tarife pozisyonunu ve vergisini belirleriz."],["Beyanname","Beyannameyi sisteme girer, yeşil ya da kırmızı hattı izleriz."],["Çıkış","Muayeneye düşerse gümrükte yanınızda durur, çıkışı izleriz."]],"k":"Gümrük evrakınızı bize bırakın."},"İhracat danışmanı":{"s":"Ürününüze hangi ülkede alıcı çıkacağını önce araştırırız.","o":"Pazar araştırması ve alıcı bulma ile başlar, devlet destekleri, belge süreci ve fuar hazırlığında yanınızda çalışırız.","u":[["Pazar","Ürününüzün satılabileceği ülkeleri talep verisiyle ayırırız."],["Alıcı","İthalatçı ve dağıtıcı listesi çıkarıp ilk teması kurarız."],["Belge","Menşe, fatura ve uygunluk belgelerini sırayla tamamlarız."],["Destek","Fuar ve devlet destekleri için başvuru takvimini tutarız."]],"k":"İlk ihracat planınızı çıkaralım."},"Yatırım danışmanı":{"s":"Hangi riski taşıyabileceğinizi sizinle konuşarak belirleriz.","o":"Yatırım profili görüşmesiyle başlar, portföy değerlendirmesi ve risk raporunu sunar, yetki belgesi bilgisini baştan paylaşırız.","u":[["Profil","Gelirinizi, vadenizi ve riske bakışınızı dinleriz."],["Portföy","Mevcut varlıklarınızın dağılımını yazıya dökeriz."],["Risk","Her aracın taşıdığı riski rapor halinde anlatırız."],["Belge","Yetki belgemizi ve çalışma çerçevemizi önceden gösteririz."]],"k":"Profil görüşmesi için randevu alın."},"Emlak hukuku":{"s":"Tapu ve sözleşme belgelerinizi birlikte okuyup durumu anlatırız.","o":"Ön görüşmede tapu, kira, kat karşılığı sözleşme ya da ortaklığın giderilmesi dosyanızı inceler, hukuki süreci anlatırız.","u":[["Belgeler","Tapu kaydı, sözleşme ve yazışmaları sizden isteriz."],["İnceleme","Dosyadaki hak ve yükümlülükleri tek tek okuruz."],["Süreç","Olası hukuki yolları ve gerekli adımları anlatırız."],["Dosya","Karar verirseniz süreci yazılı olarak başlatırız."]],"k":"Dosyanız için ön görüşme alın."},"Vize danışmanlığı":{"s":"Randevu gününde evrağınız eksik çıkmasın diye listeyi baştan veririz.","o":"Gideceğiniz ülkeye göre evrak listesi çıkarır, Schengen başvuru takibi ve randevu desteği sunar, formları sizinle doldururuz.","u":[["Liste","Ülke ve vize türüne göre gereken evrakı yazarız."],["Form","Başvuru formunu pasaportunuzla aynı yazımda doldururuz."],["Randevu","Konsolosluk ya da merkez randevusunu sizinle seçeriz."],["Takip","Başvuru sonrası dosyanın durumunu sorgularız."]],"k":"Evrak listenizi isteyin."},"Güvenlik şirketi":{"s":"Görevli sayısını binayı gezdikten sonra belirleriz.","o":"Özel güvenlik görevlisi, etkinlik güvenliği, kamera izleme ve alarm takibini risk analizinden sonra yerinize göre kurarız.","u":[["Keşif","Giriş çıkışları ve kör noktaları yerinde gezeriz."],["Risk","Bulduğumuz açıkları yazılı analiz olarak veririz."],["Nöbet","Görevli sayısını ve vardiya düzenini yerleştiririz."],["İzleme","Kamera ve alarm kayıtlarını merkezden takip ederiz."]],"k":"Yerinizi birlikte gezelim."},"Bilgisayar servisi":{"s":"Verileriniz silinmeden önce yedeğini alıp sonra formata başlarız.","o":"Format ve kurulum, donanım değişimi, laptop ekran değişimi ve veri kurtarma işlerini arızayı bulduktan sonra onayınızla yaparız.","u":[["Tespit","Cihazı açar, arızalı parçayı testle buluruz."],["Yedek","Diskteki dosyalarınızı işlemden önce ayırırız."],["Onarım","Parçayı değiştirir ya da sistemi yeniden kurarız."],["Test","Isınma ve hız denemesi yapıp cihazı teslim ederiz."]],"k":"Cihazınızı teşhise bırakın."},"Telefon tamiri":{"s":"Telefonunuzu açmadan önce neyin bozulduğunu size gösteririz.","o":"Ekran değişimi, batarya değişimi ve şarj soketi işlerini yapar, sıvı teması kontrolünde kartı açıp kuruluk ve oksit durumuna bakarız.","u":[["Arıza","Telefonu çalıştırıp ekranı, dokunmatiği ve şarjı deneriz."],["Parça","Hangi parçanın gideceğini size gösteririz."],["Değişim","Cihazı açar, parçayı takar, contayı yenileriz."],["Deneme","Dokunmatik, kamera ve şarjı çalıştırıp teslim ederiz."]],"k":"Telefonunuzu tezgâha bırakın."},"Saat tamiri":{"s":"Saatiniz suya girmeden önce contasını basınçla sınarız.","o":"Pil ve kordon değişimi, bakım ve ayar işlerini tezgâhta yapar, su geçirmezlik testiyle contayı sınarız.","u":[["Kasa açma","Kapağı açar, mekanizmada nem ve tozu kontrol ederiz."],["Pil","Uygun pili takar, ibre ayarını yaparız."],["Conta","Kapak contasını yeniler, basınç cihazında sızdırmazlığa bakarız."],["Kordon","Kordonu bileğinize göre ayarlayıp saati teslim ederiz."]],"k":"Saatinizi tezgâhımıza getirin."},"Ayakkabı tamiri":{"s":"Eski ayakkabınızı atmadan önce bize gösterin.","o":"Pençe değişimi, topuk onarımı, fermuar değişimi ve boyama yapar, çanta onarımı için dikiş ve kopça işini üstleniriz.","u":[["Bakış","Tabanın, dikişin ve derinin durumuna bakarız."],["Sökme","Eski pençeyi ya da topuğu söker, yüzeyi hazırlarız."],["Yapıştırma","Yeni pençeyi yapıştırır, kenarını zımparayla alırız."],["Boya","Rengi tutturur, cila vurup teslim ederiz."]],"k":"Eski çiftinize bir şans verin."},"Terzi":{"s":"Paçayı keserken önce üstünüzde işaretler, sonra makasa dokunuruz.","o":"Paça kısaltma, bel daraltma, fermuar değişimi ve ceket kol ayarını prova ile yapar, özel dikim de alırız.","u":[["Prova","Giysiyi üstünüzde iğneyle işaretleriz."],["Kesim","Payı hesaplar, kumaşı ona göre keseriz."],["Dikiş","Orijinal dikiş izini koruyarak dikeriz."],["İkinci prova","Üstünüzde bir kez daha bakar, gerekirse düzeltiriz."]],"k":"Ölçünüzü alalım."},"Kuru temizleme":{"s":"Etiketini okumadan hiçbir kumaşı makineye sokmayız.","o":"Takım elbise, gömlek, abiye, mont ve perdeyi leke türüne ve kumaşa göre ayırıp temizler, ütüleyip askıda teslim ederiz.","u":[["Etiket","Yıkama simgelerine ve kumaş cinsine bakarız."],["Leke","Lekeyi türüne göre önceden ayrı işleme alırız."],["Temizlik","Kumaşa uygun programla temizleriz."],["Pres","Ütüsünü yapıp askıda, poşetli veririz."]],"k":"Giysilerinizi bize emanet edin."},"Halı yıkama":{"s":"El dokuma halınızın rengi akmasın diye önce boya testi yaparız.","o":"Makine halısı ve el dokuma halıyı ayrı yıkar, yerinde koltuk yıkama yapar, servisle alma ve teslim hizmeti sunarız.","u":[["Toz alma","Halının derinine işleyen tozu silkeleyerek çıkarırız."],["Boya testi","Islak bezle rengin akıp akmadığını deneriz."],["Yıkama","Cinsine göre makinede ya da elde yıkarız."],["Kurutma","Gerdirerek kurutur, sarıp evinize bırakırız."]],"k":"Halınızı almaya gelelim."},"Mobilya tamiri":{"s":"Sallanan sandalyeyi atmadan önce iskeletine bakarız.","o":"Koltuk tamiri, sandalye onarımı, döşeme değişimi ve ahşap vernik işlerini atölyede yapar, yerinde montaj da sunarız.","u":[["İskelet","Çatlak ve gevşek geçmeleri kontrol ederiz."],["Söküm","Eski kumaşı ve süngeri çıkarırız."],["Onarım","Geçmeleri tutkallar, yeni sünger ve kumaşı döşeriz."],["Montaj","Parçayı evinize götürür, yerine takarız."]],"k":"Mobilyanızı atölyeye getirin."},"Çamaşırhane":{"s":"Otel çarşafınız ile restoran önlüğünüz birbirine karışmaz.","o":"Yıkama ve kurutma, ütü ve servisle alma işini yapar, otel ve restoranlarla sözleşmeli düzenli teslim programı kurarız.","u":[["Sayım","Gelen çamaşırı adet ve türüne göre sayıp kaydederiz."],["Ayırma","Beyaz, renkli ve lekeliyi ayrı gruplarda yıkarız."],["Ütü","Kurutulan çarşafı ve masa örtüsünü ütüden geçiririz."],["Sevk","Sayımla eşleştirip belirlenen günde teslim ederiz."]],"k":"Düzenli yıkama programı kuralım."},"Ütü hizmeti":{"s":"Gömleklerinizi askıda, yakası dik, sabah giymeye hazır alırsınız.","o":"Gömlek ütüsü, perde ütüsü ve kilo ile ütü hizmetini evinizden alıp ütüleyerek servisle geri getiririz.","u":[["Teslim alma","Ütüsüz çamaşırı evinizden torbayla alırız."],["Ayırma","Kumaşa göre ısıyı ayarlarız."],["Ütü","Yaka, manşet ve pliseye ayrı özen gösteririz."],["Askı","Gömlekleri askıda, kalanı katlı teslim ederiz."]],"k":"Ütü yığınını bize bırakın."},"Sürücü kursu":{"s":"Direksiyon sınavına girmeden önce parkuru arabada birlikte tekrar ederiz.","o":"B ve A sınıfı ehliyet derslerini verir, ek direksiyon dersi ve direksiyon sınavı hazırlığıyla eksik kalan yeri tamamlarız.","u":[["Kayıt","Raporunuzla ve evrakınızla dosyanızı açarız."],["Teori","Trafik ve ilk yardım derslerini sınıfta işleriz."],["Direksiyon","Önce boş alanda, sonra trafikte araç kullandırırız."],["Parkur","Sınav parkurunu direksiyon başında tekrar ederiz."]],"k":"Direksiyon başına geçin."},"Özel ders":{"s":"Konuyu anlatmadan önce hangi yerde takıldığınıza bakarız.","o":"Matematik, fizik ve İngilizce derslerini seviye görüşmesine göre planlar, istenirse online ders olarak yürütürüz.","u":[["Seviye","Kısa bir soru setiyle eksik konuyu buluruz."],["Program","Ders günlerini okul takvimine göre yazarız."],["Soru çözümü","Anlatılan konuyu birlikte örnek sorularla pekiştiririz."],["Ödev","Haftanın ödevini verir, sonraki derste kontrol ederiz."]],"k":"Seviye görüşmesi için yazın."},"Dil kursu":{"s":"Seviyenize uymayan sınıfta oturup vakit kaybetmezsiniz.","o":"Seviye tespitiyle sınıfınızı belirler, genel İngilizce, Almanca, konuşma kulübü ve IELTS hazırlıkta dili kullandırarak öğretiriz.","u":[["Seviye","Yazılı ve sözlü kısa sınavla sınıfınızı belirleriz."],["Grup","Aynı düzeydeki katılımcılarla sınıf kurarız."],["Konuşma","Her derste sizi konuşturur, hataları o anda düzeltiriz."],["Deneme","Sınav hedefi varsa deneme sınavı yaparız."]],"k":"Sınıfınızı birlikte belirleyelim."},"Müzik kursu":{"s":"İlk derste enstrümana dokunur, notayı sonra öğrenirsiniz.","o":"Piyano, gitar, keman ve şan derslerinde tanışma dersiyle başlar, size uygun enstrümanı birlikte seçeriz.","u":[["Tanışma","Enstrümana dokunur, birkaç ses çıkarırsınız."],["Duruş","Parmak ve el pozisyonunu doğru oturturuz."],["Parça","Basit bir parçayı çalmaya erkenden başlarsınız."],["Sahne","Dönem sonunda dinleyici karşısında çalarsınız."]],"k":"Tanışma dersine gelin."},"Dans okulu":{"s":"Düğünde ilk dansı ayağınıza basmadan yapmanız için çalışırız.","o":"Salsa, bale, hip hop ve düğün dansı derslerini tanışma dersiyle başlatır, çiftlere ve çocuklara ayrı gruplar kurarız.","u":[["Tanışma","Bir derse katılıp temel adımları denersiniz."],["Isınma","Her derste kasları ısıtır, esnetme yaparız."],["Koreografi","Küçük figürleri birleştirip bir parça yaparız."],["Gösteri","Dönem sonunda ya da düğünde sahnede oynarsınız."]],"k":"İlk adımı birlikte atalım."},"Resim kursu":{"s":"Elinize ilk günden kalem verir, çizgiyi birlikte düzeltiriz.","o":"Çocuk resim, yetişkin resim, karakalem ve güzel sanatlar hazırlık derslerini küçük gruplarda, her öğrencinin düzeyine göre veririz.","u":[["Çizgi","Düz çizgi ve basit formlarla elinizi açarız."],["Gölge","Karakalemle ışığı ve gölgeyi çalışırız."],["Natürmort","Gerçek nesneye bakıp oranı yakalamayı öğretiriz."],["Dosya","Hazırlık öğrencileriyle çalışmaları dosyaya toplarız."]],"k":"Kalemi elinize alın."},"Kodlama kursu":{"s":"Çocuğunuz kendi yazdığı oyunu arkadaşlarına gösterir.","o":"Blok kodlama ile başlar, Python ve robotik set derslerine geçeriz, yaz kampında çocuklar kendi projelerini tamamlar.","u":[["Tanışma","Çocuk bir deneme dersinde ilk bloğunu sürükler."],["Blok","Sahne ve karakteri hareket ettiren blokları kurarız."],["Robot","Motor ve sensörü bağlar, robotu kodla çalıştırırız."],["Proje","Çocuk kendi oyununu ya da robotunu bitirip sunar."]],"k":"Deneme dersine katılın."},"Anaokulu":{"s":"Çocuğunuz kapıdan ağlamadan girsin diye önce tanışma ziyareti yaparız.","o":"Tanışma ziyaretiyle başlar, yarım gün ve tam gün programı ile beslenme menüsünü gösterir, servis güzergâhını sizinle paylaşırız.","u":[["Ziyaret","Çocukla birlikte sınıfı ve bahçeyi gezersiniz."],["Alışma","Çocuğu kısa süreli bırakarak sınıfa alıştırırız."],["Gün akışı","Yemek, oyun ve uyku saatlerini yazıyla paylaşırız."],["Veli notu","Gün sonunda öğretmen size günü anlatır."]],"k":"Tanışma ziyareti için gelin."},"Özel okul":{"s":"Kaydı yaptırmadan önce sınıfları ve öğretmenleri görmenizi isteriz.","o":"Kayıt görüşmesi ve okul gezisiyle başlar, burs bilgisi, yabancı dil programı ve servis ayrıntısını yazılı veririz.","u":[["Görüşme","Velinin beklentisini ve öğrencinin ilgisini dinleriz."],["Gezi","Sınıfı, laboratuvarı ve yemekhaneyi gezdiririz."],["Burs","Burs sınav şartlarını ve başvuru tarihini anlatırız."],["Kayıt","Evrakı alır, servis güzergâhını birlikte belirleriz."]],"k":"Okulu yerinde görmeye gelin."},"Yüzme kursu":{"s":"Çocuğunuz önce suyla barışır, sonra kulaç atar.","o":"Çocuk ve yetişkin grup dersleri ile özel ders verir, seviye tespitiyle sizi suya uygun grupta başlatırız.","u":[["Seviye","Suya girişinizi görüp grubunuzu belirleriz."],["Alışma","Yüzünüzü suya sokmayı, nefes vermeyi çalışırız."],["Kulaç","Şamandırayla sırt ve kurbağalama kulacını öğretiriz."],["Mesafe","Havuz boyunu tek seferde bitirmeye kadar götürürüz."]],"k":"Havuza ilk adımı atın."},"Satranç kulübü":{"s":"İlk oyununuzda taşların nasıl yürüdüğünü baştan gösteririz.","o":"Başlangıç grubu ve özel ders sunar, turnuva hazırlığında açılış çalışır, turnuva takvimini velilere önceden bildiririz.","u":[["Taşlar","Taşların yürüyüşünü ve şah mat kuralını anlatırız."],["Açılış","İlk hamle düzenlerini tahta başında çalıştırırız."],["Parti","Kulüp içi kısa partilerle rakip karşısında alıştırma yaparız."],["Notasyon","Hamle yazmayı ve satranç saati kullanmayı öğretiriz."]],"k":"Tahta başına oturun."},"Mesleki kurs":{"s":"Kurs sonunda hangi belgeyi alacağınızı kayıttan önce söyleriz.","o":"Belgeli meslek programı kapsamında muhasebe, aşçılık ve kuaförlük kurslarını verir, sertifika bilgisini kayıttan önce paylaşırız.","u":[["Belge","Kursun hangi belgeye hazırladığını açıklarız."],["Atölye","Uygulamayı mutfakta, defterde ya da koltukta yaptırırız."],["Pratik","Gerçek iş örnekleriyle sınav öncesi tekrar yaparız."],["Sınav","Belge sınavı için başvuru evrakını hazırlarız."]],"k":"Mesleğinizi öğrenmeye başlayın."},"Rehberlik merkezi":{"s":"Tercih listesini öğrencinin ilgisi ve puanı birlikte konuşarak çıkarırız.","o":"Rehberlik görüşmesi ve tercih danışmanlığı sunar, sınav kaygısı çalışması ile veli görüşmesinde öğrenciyi ve aileyi birlikte dinleriz.","u":[["Görüşme","Öğrencinin ilgisini ve derslerle ilişkisini dinleriz."],["Envanter","İlgi ve yetenek envanterini birlikte okuruz."],["Tercih","Bölüm ve okul seçeneklerini taban bilgisiyle anlatırız."],["Veli","Veliyle bulguları ve sıradaki adımı paylaşırız."]],"k":"Görüşme için randevu alın."},"Online eğitim":{"s":"Dersi kaçırdıysanız kaydını arşivden açar, kaldığınız yerden devam edersiniz.","o":"Canlı dersler ve kayıtlı ders arşivi sunar, deneme sınavı ve sertifika ile kurumsal eğitim için çalışanlara özel program kurarız.","u":[["Kayıt","Hesabınızı açar, ders programınıza ekleriz."],["Canlı ders","Eğitmenle ekranda ders işler, soru sorarsınız."],["Arşiv","Dersin kaydı arşive eklenir, istediğiniz zaman açarsınız."],["Deneme","Deneme sınavı çözer, sonuç raporunu görürsünüz."]],"k":"Derse bağlanın."},"Matematik kursu":{"s":"Yanlış sorunun hangi adımda yanlış gittiğini birlikte buluruz.","o":"LGS ve YKS matematik gruplarında seviye tespitiyle başlar, birebir derste eksik konuyu tek tek kapatırız.","u":[["Seviye","Konu bazlı sınavla eksik başlıkları çıkarırız."],["Konu","Eksik başlığı örnek sorularla yeniden anlatırız."],["Soru bankası","Zorluk derecesine göre soru çözdürürüz."],["Deneme","Süre tutup deneme çözer, yanlışları birlikte açarız."]],"k":"Seviye tespitine gelin."},"Oyun kafe":{"s":"Kuralları okumakla vakit kaybetmezsiniz, oyunu masada size anlatırız.","o":"Saatlik masa kiralar, masa oyunları kütüphanesinden seçim yapmanıza yardım eder, grup etkinliği ve atıştırmalıkları aynı masaya getiririz.","u":[["Masa","Kaç kişi geleceğinizi söyler, masanızı ayırırız."],["Oyun","Grubunuza göre rafta uygun oyunu seçeriz."],["Anlatım","Kuralları masada kısaca anlatır, ilk eli birlikte oynarız."],["İkram","Atıştırmalığı oyun bölünmeden masaya getiririz."]],"k":"Masanızı ayırtın."},"Kaçış oyunu":{"s":"Kilidi açmanız için ipucu veririz, çözümü söylemeyiz.","o":"Oyun seansı ve grup oyunu sunar, şirket etkinliği ile doğum günü paketinde oyun odasını ekibinize göre hazırlarız.","u":[["Brifing","Oyun yöneticisi hikâyeyi ve kuralları anlatır."],["Arama","Ekip odada ipuçlarını arar, bulmacaları çözer."],["İpucu","Takıldığınızda kameradan görüp yönlendiririz."],["Çıkış","Süre bitince ya da kapı açılınca fotoğraf çekeriz."]],"k":"Ekibinizle odaya girin."},"Oyun salonu":{"s":"Çocuğunuzun jetonu bitince oyunu da bitmesin diye saatlik kart sunarız.","o":"Oyun jetonu ve saatlik kart seçenekleri sunar, parti paketi ile çocuk alanında doğum günü ve grup oyununu düzenleriz.","u":[["Kart","Jeton ya da saatlik kartı kasadan yüklersiniz."],["Oyun","Çocuk makineleri kendi hızında dener."],["Çocuk alanı","Küçükleri ayrı bölümde oynatırız."],["Parti","Doğum günü grubuna masa ve pasta alanı ayırırız."]],"k":"Kartınızı yükleyin."},"Bowling":{"s":"Ayakkabınızı kiralayıp kulvara geçtiğinizde skor tabelası hazırdır.","o":"Tek oyun ve kulvar kiralama seçenekleri sunar, parti paketi ile şirket turnuvasında skoru ve ayakkabıyı biz hazırlarız.","u":[["Ayakkabı","Ayak numaranızı alır, bowling ayakkabısını veririz."],["Kulvar","Grubunuza kulvar ayırır, adlarınızı skor sistemine gireriz."],["Top","Elinize uygun ağırlıkta topu seçtirir, ilk atışı gösteririz."],["Skor","Maç sonu skor çıktısını masanıza bırakırız."]],"k":"Kulvarınızı ayırtın."},"Sinema":{"s":"Biletinizi alırken koltuğunuzu da seçersiniz.","o":"Gösterim saatlerini ve bileti sunar, salon kiralama ve sınıf gösterimiyle grupların özel seansını hazırlarız.","u":[["Seans","Film ve gösterim saatini seçersiniz."],["Koltuk","Salon planından koltuğunuzu işaretlersiniz."],["Giriş","Biletinizi kapıda okutur, salona geçersiniz."],["Özel gösterim","Salon kiralayanlarla filmi ve saati birlikte belirleriz."]],"k":"Seansınızı seçin."},"Lunapark":{"s":"Hangi oyuncağa kaç yaşından binileceğini kapıda net söyleriz.","o":"Tek biniş ve günlük bilet seçenekleri sunar, aile paketi ve doğum günü grupları için bilet düzenini kolaylaştırırız.","u":[["Bilet","Tek biniş ya da günlük bileti kasadan alırsınız."],["Boy ölçümü","Çocuğun boyunu ölçer, binebileceği oyuncakları söyleriz."],["Biniş","Görevli emniyet kemerini tek tek kontrol eder."],["Doğum günü","Grubunuza masa ayırır, biniş sırasını planlarız."]],"k":"Biletinizi kapıdan alın."},"Çocuk oyun alanı":{"s":"Çocuğunuz oynarken siz kafe alanında kahvenizi içersiniz.","o":"Saatlik giriş ve doğum günü paketi sunar, çocuğun yaşına göre ayrılmış oyun alanıyla kafe alanını yan yana kurarız.","u":[["Giriş","Çocuğun adını ve veli telefonunu deftere yazarız."],["Çorap","Çocuk çorapla girer, ayakkabılar rafta kalır."],["Oyun","Yaşına göre küçükler ve büyükler ayrı bölümde oynar."],["Doğum günü","Pasta masasını ve süslemeyi önceden hazırlarız."]],"k":"Oyun saatinizi ayırın."},"Site yönetimi":{"s":"Aidatın nereye harcandığını her ay kâğıt üzerinde görürsünüz.","o":"Aidat takibi, gelir gider raporu, personel yönetimi ve bakım planıyla siteyi yönetir, toplantı ve karar defterini tutarız.","u":[["Aidat","Daire bazında borç ve ödemeleri tablo halinde tutarız."],["Gider","Gelir gider raporunu ilan panosuna ve gruba göndeririz."],["Bakım","Asansör, jeneratör ve havuz bakım tarihlerini takvime yazarız."],["Kurul","Toplantı gündemini hazırlar, kararı deftere işleriz."]],"k":"Yönetimi bize devredin."},"Değerleme uzmanı":{"s":"Raporun neye göre yazıldığını dayanak emsallerle birlikte gösteririz.","o":"Taşınmaz değerleme raporunu kredi, miras ve dava için hazırlar, yatırım analizi için yerinde inceleme yaparız.","u":[["Tapu","Takbis kaydını ve imar durumunu inceleriz."],["Yerinde bakış","Taşınmazı gezer, ölçü ve fotoğraf alırız."],["Emsal","Çevredeki benzer satış ve kira örneklerini toplarız."],["Rapor","Dayanakları yazarak raporu kuruma uygun biçimde hazırlarız."]],"k":"Taşınmazınızı yerinde görelim."},"Konut projesi":{"s":"Kat planına bakıp dairenizi kafanızda yerleştirerek karar verirsiniz.","o":"Daire seçeneklerini ve kat planlarını gösterir, ödeme planını yazılı verir, örnek daire gezisinde teslim takvimini anlatırız.","u":[["Kat planı","Blok ve kat planında dairenizi birlikte işaretleriz."],["Örnek daire","Gezide cephe, metrekare ve malzemeyi gösteririz."],["Ödeme planı","Peşinat ve taksit düzenini yazıya döküp veririz."],["Teslim","Teslim takvimini ve tapu aşamasını açıklarız."]],"k":"Örnek daireyi gezin."},"Ofis kiralama":{"s":"Masanız, adresiniz ya da toplantı odanız, ihtiyacınız kadar kiralanır.","o":"Hazır ofis, sanal ofis, toplantı odası ve ortak çalışma alanı seçenekleriyle ekibinizin büyüklüğüne göre alan ayarlarız.","u":[["İhtiyaç","Kaç kişi çalışacağınızı ve adres gerekip gerekmediğini sorarız."],["Gezi","Hazır ofisi ve ortak alanı yerinde görürsünüz."],["Sözleşme","Kira şartlarını ve dahil hizmetleri yazılı veririz."],["Taşınma","Anahtarı alır, internet ve masa hazır halde başlarsınız."]],"k":"Ofisinizi yerinde görün."},"Depo kiralama":{"s":"Eşyanız nemden korunsun diye depoyu önce birlikte gezeriz.","o":"Küçük, orta boy ve büyük depo seçenekleri sunar, eşya taşıma ve kesintisiz giriş imkânıyla depoyu istediğiniz zaman kullandırırız.","u":[["Hacim","Eşyalarınızın hacmine göre deponun boyunu seçeriz."],["Gezi","Zemini, nemi ve kapı yüksekliğini yerinde gösteririz."],["Taşıma","Eşyanızı araca yükler, depoya yerleştiririz."],["Anahtar","Kilidi size verir, giriş saatlerini anlatırız."]],"k":"Deponuzu gezerek seçin."},"Arsa satışı":{"s":"Tapu ve imar durumuna bakmadan hiçbir arsayı size göstermeyiz.","o":"Konut imarlı arsa ve yatırımlık arazi sunar, tapu ve imar kontrolü ile parselasyon bilgisini verip arsayı yerinde gezdiririz.","u":[["Tapu","Tapu kaydında şerh ve ipotek var mı bakarız."],["İmar","İmar durumunu belediyeden teyit ederiz."],["Parsel","Parselasyonu ve yola cepheyi haritada gösteririz."],["Arazi","Sınır noktalarını yerinde birlikte gezeriz."]],"k":"Araziyi yerinde görün."},"E-ticaret":{"s":"Siparişiniz nerede diye sormanıza gerek kalmaz, kargo takibi açıktır.","o":"Yeni ürünleri sunar, kolay iade ve kapıda ödeme seçenekleri sağlar, çoklu kanal stokunu tek yerden yönetiriz.","u":[["Sepet","Ürünü seçer, kapıda ödeme ya da kartı belirlersiniz."],["Paket","Siparişi stoktan ayırır, kolileyip kargoya veririz."],["Takip","Kargo takip numarasını size iletiriz."],["İade","Ürün uymazsa iade kodunu açarız."]],"k":"Sepetinizi doldurun."},"El yapımı ürün":{"s":"Her parça elde yapılır, ikisi birbirinin aynısı olmaz.","o":"El yapımı koleksiyonu sunar, kişiye özel sipariş alır, hediye paketini hazırlayıp kargo takibiyle adresinize göndeririz.","u":[["Seçim","Koleksiyondan parçayı seçer ya da özel isteğinizi yazarsınız."],["Atölye","Parçayı elde yapar, rengi sizinle teyit ederiz."],["Paket","Hediye ise kâğıda sarar, not kartını koyarız."],["Kargo","Takip numarasını mesajla göndeririz."]],"k":"Siparişinizi atölyeye iletin."},"Takı tasarımı":{"s":"Kolyenizdeki ismin yazımını göndermeden önce size tekrar onaylatırız.","o":"Tasarım takı ve kişiye özel kolye sunar, hediye kutusu ve toptan sipariş seçenekleriyle kargo takibini birlikte yürütürüz.","u":[["Tasarım","Model, malzeme ve yazıyı sizinle netleştiririz."],["Çizim","Özel kolyenin çizimini onayınıza sunarız."],["Üretim","Onaydan sonra takıyı atölyede yaparız."],["Kutu","Kutulayıp kargo takip numarasıyla göndeririz."]],"k":"Takınızı birlikte tasarlayalım."},"Doğal kozmetik":{"s":"Sabunun içindeki her maddeyi etikete tek tek yazarız.","o":"Doğal sabun, cilt bakım yağları ve şampuan üretir, set ürünler hazırlar, kargo takibiyle size göndeririz.","u":[["Hammadde","Yağ ve bitki karışımını hazırlarız."],["Üretim","Sabunu kalıba döker, kesip kurumaya bırakırız."],["Etiket","İçindekiler listesini etikete yazarız."],["Koli","Seti koliye koymadan önce kapakları kontrol ederiz."]],"k":"Ürünlerimizi cildinizde deneyin."},"Organik ürün":{"s":"Ürünün hangi üreticiden geldiğini sayfasında yazarız.","o":"Organik bakliyat, zeytinyağı, bal ve kuru gıda sunar, sertifika bilgisini ürün sayfasında paylaşıp kargo takibiyle göndeririz.","u":[["Üretici","Ürünü getiren üreticiyi ve bölgeyi kaydederiz."],["Sertifika","Belge bilgisini ürün sayfasında paylaşırız."],["Paket","Yağı şişede, bakliyatı kese kâğıdında paketleriz."],["Kargo","Kolinin takip numarasını size iletiriz."]],"k":"Sofranıza ürün seçin."},"Kahve satışı":{"s":"Kahveniz kavrulduktan sonra tarihi yazılı pakette size gelir.","o":"Taze çekirdek, filtre kahve ve espresso harmanı sunar, öğütme inceliğini demleme yönteminize göre seçer, abonelik kurarız.","u":[["Demleme","Filtre, espresso ya da moka pot kullandığınızı söylersiniz."],["Kavurma","Çekirdeği siparişe yakın kavururuz."],["Öğütme","Yönteminize uygun incelikte öğütür ya da çekirdek bırakırız."],["Abonelik","Aralığı seçersiniz, kahveniz düzenli gelir."]],"k":"Çekirdeğinizi seçin."},"Yöresel ürün":{"s":"Peynirin hangi köyden geldiğini koliyi açmadan bilirsiniz.","o":"Yöresel peynir, pekmez ve reçel, kuru gıda sunar, sipariş kolisini ürünün cinsine göre paketleyip kargo takibiyle göndeririz.","u":[["Seçim","Peynir, pekmez ve reçelden kolinizi seçersiniz."],["Soğuk","Peyniri soğuk tutarak koliye yerleştiririz."],["Koli","Cam kavanozları kırılmasın diye sararız."],["Yol","Kargo takibini size mesajla iletiriz."]],"k":"Kolinizi hazırlayalım."},"Düğün salonu":{"s":"Tarihinizi ayırtmadan önce salonu ve masaları yerinde görürsünüz.","o":"Düğün, nişan ve kına gecesi paketlerini sunar, salon gezisi ve tarih sorgulamasını önceden yapar, masa düzenini sizinle kurarız.","u":[["Tarih","Gün ve saat için salonun müsait olup olmadığına bakarız."],["Gezi","Salonu, sahneyi ve girişi yerinde gezersiniz."],["Masa planı","Davetli sayısına göre masa düzenini çizeriz."],["Düğün günü","Servis, ses ve sahne akışını yönetiriz."]],"k":"Tarihinizi sorgulayın."},"Organizasyon firması":{"s":"Etkinlik gününün akışını önceden kâğıda döküp size veririz.","o":"Düğün, nişan ve söz, açılış ve şirket etkinliklerini kurar, süsleme ve tedarikçileri tek elden yönetiriz.","u":[["Konsept","Etkinliğin amacını, davetli sayısını ve mekânı dinleriz."],["Tedarik","Süsleme, ikram ve sahne için tedarikçiyi ayarlarız."],["Akış","Gün planını saat saat yazarız."],["Kurulum","Etkinlik günü mekânda her şeyi yerleştiririz."]],"k":"Etkinliğinizin akışını yazalım."},"Doğum günü organizasyonu":{"s":"Çocuklar oynarken siz misafirlerinizle ilgilenirsiniz.","o":"Temalı doğum günü kurar, animatör, pasta ve ikram işini yapar, isterseniz evde süsleme ile hazırlığı yerinde tamamlarız.","u":[["Tema","Çocuğun sevdiği karakter ya da rengi seçersiniz."],["Süs","Balon ve masa örtüsünü evde ya da salonda kurarız."],["Oyun","Animatör çocukları oyunla karşılar."],["Pasta","Mum, pasta ve ikram saatini birlikte kararlaştırırız."]],"k":"Temanızı birlikte seçelim."},"Nişan organizasyonu":{"s":"Söz tepsisini ve masa düzenini aileler gelmeden hazırlarız.","o":"Nişan süsleme, söz tepsisi, masa düzeni ve fotoğraf köşesini iki ailenin isteğine göre hazırlarız.","u":[["Aileler","Her iki tarafın misafir sayısını ve isteğini alırız."],["Tepsi","Söz tepsisini renk ve çiçeğe göre süsleriz."],["Masa","Büyüklerin oturacağı yeri ayrı planlarız."],["Köşe","Fotoğraf köşesini çiçek ve ışıkla kurarız."]],"k":"Nişan düzenini konuşalım."},"DJ":{"s":"Çalacağımız şarkıları önceden sizinle listeye yazarız.","o":"Düğün DJ performansı, şirket etkinliği ve doğum günü için ses sistemiyle gelir, salonun yaş grubuna göre çalarız.","u":[["Liste","İstediğiniz ve istemediğiniz şarkıları bir araya yazarız."],["Kurulum","Ses sistemini salonun boyuna göre yerleştiririz."],["Ses kontrolü","Etkinlik öncesi mikrofon ve hoparlörleri deneriz."],["Set","Misafir kitlesine göre parçaları sırayla geçeriz."]],"k":"Şarkı listenizi bize verin."},"Orkestra":{"s":"Hem halay çeken hem oturan masa için repertuvar kurarız.","o":"Düğün orkestrası, akustik ekip ve fasıl ekibi sunar, ses sistemini de getirip repertuvarı sizinle belirleriz.","u":[["Repertuvar","Ailenin sevdiği türküleri ve şarkıları listeleriz."],["Kadro","Düğün tarzına göre saz ve ses sayısını belirleriz."],["Sahne","Sahne ölçüsüne bakıp ses sistemini kurarız."],["Gece","Salonun hareketine göre parçaları sırayla çalarız."]],"k":"Repertuvarı birlikte yazalım."},"Ses ışık sistemi":{"s":"Salonun arka masası da konuşmayı duyar.","o":"Ses sistemi kiralama, ışık paketi ve LED ekran sunar, teknik ekibimizle kurulumu ve etkinlik boyunca kontrolü yaparız.","u":[["Mekân","Salonun boyunu ve tavan yüksekliğini ölçeriz."],["Dizilim","Hoparlör ve ışık yerlerini plana çizeriz."],["Kurulum","Kabloları, mikseri ve LED ekranı yerleştiririz."],["Kontrol","Etkinlik boyunca mikser başında kalırız."]],"k":"Salonunuzu ölçmeye gelelim."},"Çadır kiralama":{"s":"Çadırın zemini düz mü diye kurmadan önce alana bakarız.","o":"Çadır, masa ve sandalye kiralar, kurulum ve söküm işini yapar, şehir içi taşımayı üstleniriz.","u":[["Alan","Zemini ve çadırın sığacağı yeri yerinde ölçeriz."],["Sayım","Misafir sayısına göre masa ve sandalyeyi hesaplarız."],["Kurulum","Direkleri dikip çadırı gerer, masaları dizeriz."],["Söküm","Etkinlik bitince toplar, alanı temizleriz."]],"k":"Çadırınızı alana kuralım."},"Balon süsleme":{"s":"Balon takıyı yerinde şişirir, taşırken patlamasın diye orada kurarız.","o":"Balon takı, doğum günü seti ve açılış süslemesini hazırlar, yerinde kurulumla salonun ölçüsüne uyarlarız.","u":[["Renk","Mekânın rengine uygun balon paletini seçeriz."],["Şişirme","Balonları yerinde şişirir, takıya dizeriz."],["Kurulum","Takıyı duvara ve kapı girişine asarız."],["Sökme","Etkinlik sonrası atığı toplarız."]],"k":"Renklerinizi seçelim."},"Davetiye":{"s":"Basılmadan önce isimlerin yazımını sizden son kez isteriz.","o":"Baskılı davetiye, dijital davetiye ve nikâh şekeri tasarlar, metni sizinle yazar, baskıdan önce provayı gösteririz.","u":[["Metin","Aile adlarını, tarihi ve adresi yazarsınız."],["Tasarım","Renk ve yazı tipini düğün temasına uygun seçeriz."],["Prova","Baskıdan önce son hâlini isim kontrolüyle size göndeririz."],["Baskı","Kâğıdı keser, zarfa koyar ya da bağlantıyı iletiriz."]],"k":"Davetiyenizi tasarlayalım."},"Gelin arabası":{"s":"Süslemeyi aracın boyasına bakarak, çıkarılabilir bantla yaparız.","o":"Araç kiralama, süsleme ve şoförlü hizmet sunar, fotoğraf turunda gelin ve damadı durak durak götürürüz.","u":[["Araç","Düğün tarzınıza uygun aracı seçersiniz."],["Süsleme","Çiçek ve kurdeleyi sabah ya da bir gün önce takarız."],["Yol","Şoför gelin evinden salona rotayı bilir."],["Fotoğraf","Çekim duraklarında araç bekler."]],"k":"Aracınızı süsleyelim."},"Toplantı salonu":{"s":"Sunum başlarken projeksiyon, ses ve su masada hazır bekler.","o":"Saatlik salon kiralama ve tam gün paket sunarız; projeksiyon ve ses düzenini toplantıdan önce birlikte deneriz, kahve molasını programa bağlarız.","u":[["Yerleşim","Katılımcı sayısına göre masa düzenini kurarız."],["Cihaz","Projeksiyon ve mikrofonu siz gelmeden deneriz."],["Mola","Kahve ve çay arası program saatine bağlanır."],["Kapanış","Salon devralınır, masalar eski düzene döner."]],"k":"Salonu toplantı gününüze ayırın."},"Oto galeri":{"s":"Aracın ekspertiz raporu, anahtardan önce masanıza gelir.","o":"Satılık araçları ekspertiz raporuyla gösteririz; araç alımı, takas, kredi ön başvurusu ve noter işlemlerini aynı çatı altında yürütürüz.","u":[["Rapor","Ekspertiz raporunu araca bakmadan önce okursunuz."],["Sürüş","Aracı yolda sürer, sesleri ve frenini dinlersiniz."],["Takas","Eski aracınızın piyasa değeri yanınızda hesaplanır."],["Noter","Devir günü evrak ve kredi dosyası hazır olur."]],"k":"Aracı raporuyla birlikte görün."},"İkinci el araç":{"s":"Kilometre ve boya durumu pazarlıktan önce kâğıtta yazılıdır.","o":"Ekspertizli araçlar satar, değerinde araç alırız; takas, kredi seçenekleri ve noter desteği satış sürecinin içindedir.","u":[["Kayıt","Hasar kaydı ve kilometre bilgisi önünüze konur."],["Boya","Boyalı ve değişen parçalar ekspertizde tek tek geçilir."],["Değer","Aracınız satarken de ekspertizden geçirilip değerlenir."],["Devir","Noter günü belgeler hazırdır, yanınızda oluruz."]],"k":"Aracınızı ekspertizle seçin."},"Rent a car":{"s":"Teslim aldığınız aracın hasar kaydı anahtarla birlikte imzalanır.","o":"Ekonomik, orta sınıf ve SUV araçları günlük, uzun kullanım için aylık kiralarız; havalimanı teslim de yaparız.","u":[["Sınıf","Yolculuğunuza göre ekonomik, orta sınıf ya da SUV seçilir."],["Teslim","Araç havalimanında ya da ofiste elinize verilir."],["Hasar","Mevcut çizikler fotoğraflanıp forma işlenir."],["İade","Depo seviyesi ve kilometre iadede birlikte okunur."]],"k":"Aracınızı yolculuğunuza göre ayıralım."},"Motosiklet bayi":{"s":"Motoru almadan önce sürün, ayağınızın yere bastığını görün.","o":"Sıfır ve ikinci el motosikletleri test sürüşüyle tanıtır, taksitli satış ve tescil işlemlerini bayide tamamlarız.","u":[["Boy","Ayak basışınıza göre koltuk yüksekliği uygun motor ayrılır."],["Sürüş","Test sürüşünde viraj ve fren hissini denersiniz."],["Taksit","Taksit planı peşinatınıza göre yazılı çıkarılır."],["Tescil","Plaka ve ruhsat işlemi bayide yapılır."]],"k":"Motorunuzu sürerek seçin."},"Karavan kiralama":{"s":"İlk kez karavan çekecekler için kullanım eğitimi hazırdır.","o":"Çekme karavan ve motokaravan kiralarız; teslimde kullanım eğitimi verir, rotanıza uygun kamp noktası öneririz.","u":[["Tür","Çekme karavan mı motokaravan mı, aracınıza göre seçilir."],["Eğitim","Su, gaz ve elektrik bağlantısı teslimde gösterilir."],["Rota","Gideceğiniz bölgeye uygun kamp noktaları önerilir."],["İade","Tanklar boşaltılır, karavan iç ve dıştan kontrol edilir."]],"k":"Yola karavanla çıkın."},"Oto bayi":{"s":"Sıfır aracı kataloğa bakarak değil, direksiyonda seçin.","o":"Sıfır araçlarda test sürüşü ayarlar, kredi ve taksit planını çıkarır, eski aracınızı takas için değerlendirir, servis randevusunu da alırız.","u":[["Donanım","Donanım ve renk, stoktaki araçlar üzerinden seçilir."],["Sürüş","Test sürüşünde aracın size uyup uymadığına bakarsınız."],["Takas","Eski aracınızın değeri yazılı olarak bildirilir."],["Teslim","Tescil biter, ilk bakım randevusu takvime yazılır."]],"k":"Yeni aracınızı sürerek seçin."},"Fırın":{"s":"Sabah ekmeği fırından çıkar çıkmaz tezgâhta olur.","o":"Günlük ekmek, köy ekmeği, simit ve poğaçayı her sabah fırınlar; toplu sipariş ve servis için önceki akşam haber alırız.","u":[["Hamur","Hamur akşamdan yoğrulur, mayası dinlenmeye bırakılır."],["Fırın","Ekmekler sabaha doğru partiler halinde fırına girer."],["Tezgâh","Sıcak ekmek tezgâha ve servis araçlarına dağılır."],["Sipariş","Toplu sipariş önceki akşam deftere yazılır."]],"k":"Ekmeğiniz sabah sıcak çıksın."},"Simitçi":{"s":"Simit tepsisi sabah ilk servisten önce susamla dolar.","o":"Simit, poğaça ve açmayı sabah taze çıkarır; toplu sipariş ve sabah servisini işyeri ile okul saatlerine göre yürütürüz.","u":[["Susam","Simit pekmezli suya batırılıp susama yatırılır."],["Fırın","Simit tepsileri sırayla girer, poğaçalar arkadan gelir."],["Paket","Sipariş adedi sayılıp kasaya ya da kâğıda dizilir."],["Servis","Sabah servisi mesai ve ders başlamadan kapıya uğrar."]],"k":"Sabah simidiniz kapıya gelsin."},"Toptan gıda":{"s":"Liste fiyatı değişirse siz sipariş vermeden önce haber alırsınız.","o":"Temel gıda listesi ve koli fiyatlarını yazılı paylaşır, restoran ve otel tedariğini haftalık sevkiyat ile vadeli hesapla yürütürüz.","u":[["Liste","Mutfağın haftalık tüketimine göre ürün listesi çıkarılır."],["Koli","Koli içi adet ve birim fiyat yan yana yazılır."],["Sevkiyat","Mal haftalık gün ve saatte rampaya indirilir."],["Cari","Vadeli hesap cari kayıtla izlenir, ekstre düzenli gelir."]],"k":"Haftalık listenizi birlikte kuralım."},"Su bayi":{"s":"Damacana bitmeden yenisi kapıda olsun diye abonelik kuruyoruz.","o":"19 litrelik damacana ve küçük pet su kolisini eve teslim eder, abonelikle düzenli gönderir, sebil montajını da yaparız.","u":[["Tüketim","Evde ya da işyerinde damacananın ne kadar gittiği sorulur."],["Abonelik","Teslim günü ve adedi abonelik kaydına yazılır."],["Boşlar","Boş damacanalar teslimde geri alınır, kapıda yığılmaz."],["Sebil","Sebil gerekiyorsa yerine takılır, bağlantıları bakılır."]],"k":"Damacananız bitmeden kapınıza gelelim."},"Tüp bayi":{"s":"Tüpün mührü ve vanası kapınızda gözünüzün önünde gösterilir.","o":"12 kg mutfak tüpü ve küçük tüpü eve teslim eder, isteyene gaz dedektörü montajı yaparız.","u":[["Mühür","Dolu tüpün mührü ve vanası kapıda gösterilir."],["Bağlantı","Hortum ve regülatör takılırken sızıntıya köpükle bakılır."],["Takas","Boş tüp teslimde geri alınır."],["Dedektör","Gaz dedektörü mutfakta uygun noktaya monte edilir."]],"k":"Tüpünüzü kapıda kontrol edin."},"Süt ürünleri":{"s":"Peynirin tuzunu ve olgunluğunu tadarak seçin.","o":"Köy peyniri, tulum peyniri, süt, yoğurt ve tereyağını tezgâhta tattırır, isteyene eve teslim ederiz.","u":[["Tadım","Peynirden dilim kesilip tadına bakılır."],["Seçim","Tuzlu ya da az tuzlu, olgun ya da taze ayrılır."],["Tartı","Peynir istediğiniz miktarda kesilip tartılır."],["Soğuk","Süt ve yoğurt soğuk muhafazayla eve ulaşır."]],"k":"Peynirin tadına bakmaya gelin."},"Et ürünleri":{"s":"Kıymayı gözünüzün önünde, istediğiniz yağ oranında çekeriz.","o":"Bütün tavuk, tavuk göğsü, kıyma ve sucuk satar, toptan siparişte ürünü istenen boyda hazırlarız.","u":[["Parça","Tavuk bütün mü göğüs mü, kaç parça olacağı sorulur."],["Çekim","Kıyma yağ oranınıza göre sizin önünüzde çekilir."],["Paket","Porsiyonlar derin dondurucuya uygun ayrı poşetlenir."],["Toptan","Toptan siparişte parça boyu ve adet yazılır."]],"k":"Etinizi gözünüzün önünde hazırlayalım."},"Balıkçı":{"s":"Balığın gözüne ve solungacına bakın, sonra temizlensin.","o":"Günün balığını tezgâhta gösterir, levrek ve çipurayı istediğiniz gibi temizler ya da fileto yapar, meze çeşitlerini de sunarız.","u":[["Tezgâh","Balık buzda durur, göz ve solungaç kontrol edilir."],["Temizleme","Pul, iç ve solungaç alınır, baş ve kuyruk istenirse kalır."],["Fileto","İsteyene fileto kılçıktan ayrılıp paketlenir."],["Meze","Balığın yanına meze çeşitleri eklenir."]],"k":"Günün balığını tezgâhta görün."},"Yumurta satışı":{"s":"Yumurtanın hangi kümesten geldiği sorulursa cevabı bellidir.","o":"Gezen tavuk yumurtasını viyolle satar, düzenli alanlara abonelik, restoran ve bakkallara toptan sevkiyat yaparız.","u":[["Kümes","Yumurtanın toplandığı kümes ve tavuk beslenmesi anlatılır."],["Ayıklama","Çatlak ve kirli yumurta viyole girmeden ayrılır."],["Viyol","Yumurtalar viyollere kırılmayacak şekilde dizilir."],["Abonelik","Haftalık abonelik gününüz belirlenir, viyol kapıya gelir."]],"k":"Yumurtanızı kümesten tanıyın."},"Organik pazar":{"s":"Tezgâhta mevsimi gelen sebze durur, gelmeyen durmaz.","o":"Organik sebze ve meyveyi mevsiminde sunar, sertifikalı ürünleri etiketiyle gösterir, haftalık kutuyu eve teslim ederiz.","u":[["Mevsim","Haftanın tezgâhı mevsimi gelen ürünle kurulur."],["Etiket","Üretici ve belge bilgisi etiketten okunur."],["Kutu","Haftalık kutunun içeriği önceden bildirilir."],["Teslim","Kutu belirlenen günde kapıya bırakılır."]],"k":"Haftalık kutunuzu birlikte seçelim."},"Çiftlik":{"s":"Peynirin geldiği ahırı, yumurtanın toplandığı kümesi görebilirsiniz.","o":"Süt ve peynir, köy yumurtası ve mevsim ürünlerini haftalık kutuyla gönderir, çiftlik gezisine de davet ederiz.","u":[["Sağım","Süt sabah sağılır, peynire ya da yoğurda ayrılır."],["Toplama","Yumurta ve mevsim ürünleri sabah toplanır."],["Kutu","Haftalık kutu çiftlikte sizin için hazırlanır."],["Gezi","Çiftlik gezisinde hayvanları ve bahçeyi yerinde görürsünüz."]],"k":"Çiftliği yerinde görmeye gelin."},"Sera":{"s":"Domates dalında olgunlaşınca toplanır, kasaya o gün girer.","o":"Sezon domatesi, biber ve salatalığı kasa fiyatıyla toptan satar, fide de yetiştiririz.","u":[["Fide","Tohum fideliğe ekilir, dikime hazır hale gelir."],["Hasat","Meyve rengini alınca dal dal toplanır."],["Tasnif","Boy ve renge göre kasalara ayrılır."],["Kasa","Kasa fiyatı günün toptan haline göre bildirilir."]],"k":"Kasa fiyatını sormak için yazın."},"Fidancı":{"s":"Fidanın aşı yerini ve kök topunu dikmeden önce gösteririz.","o":"Meyve fidanı, süs bitkisi ve bahçe çiçeği satar, dikim hizmetiyle fidanı bahçenize yerinde teslim ederiz.","u":[["Toprak","Bahçenin toprağına ve güneşine göre tür seçilir."],["Fidan","Aşı yeri ve kök topu satın almadan önce bakılır."],["Dikim","Çukur açılır, fidan sulanır, destek kazığı çakılır."],["Bakım","Sulama ve budama için kısa bir not bırakılır."]],"k":"Bahçenize uygun fidanı seçelim."},"Tarım ilaçları":{"s":"İlacı ekine ve zararlıya göre seçer, dozunu yazılı veririz.","o":"Tohum, gübre, zirai ilaç ve hayvan yemi satar, reçeteli ürünlerde kullanım bilgisini verir, köye teslim ederiz.","u":[["Tarla","Ekinin türü ve görülen zararlı sorulur."],["Reçete","Reçeteli ürün için ziraat mühendisi yazısı istenir."],["Doz","Doz ve bekleme süresi ambalajdan birlikte okunur."],["Sevk","Yem ve gübre traktör yolunda köye teslim edilir."]],"k":"Tarlanızı anlatın, ürünü birlikte seçelim."},"Arıcı":{"s":"Balın hangi çiçekten ve hangi kovandan geldiği etikette yazar.","o":"Süzme bal, petek bal, polen ve arı sütünü kovandan alır, cam kavanozda kargoyla göndeririz.","u":[["Kovan","Petekler kovandan alınır, arılar dikkatle süpürülür."],["Süzme","Bal petekten süzülür, mum parçaları süzgeçle ayrılır."],["Kavanoz","Süzme bal cam kavanoza, petek bal kutuya doldurulur."],["Kargo","Kavanoz kırılmaya karşı sarılıp kargoya verilir."]],"k":"Balınızı kovandan kapınıza gönderelim."},"Zeytin işleme":{"s":"Zeytin sıkılırken nerede ve nasıl sıkıldığını gözünüzle görün.","o":"Zeytin sıkımı yapar, sızma zeytinyağı ve sofralık zeytin satar, toptan sipariş alır, isteyene tesisi gezdiririz.","u":[["Teslim","Zeytin tartılır, yaprağından ayrılarak teslim alınır."],["Yıkama","Zeytin yıkanır, ezmeye hazır hale gelir."],["Sıkım","Hamur sıkılır, yağ sudan ayrıştırılır."],["Dolum","Yağ ya da sofralık zeytin teneke ve kavanoza dolar."]],"k":"Zeytininizi tesisimizde sıkalım."},"Şarap evi":{"s":"Üzümün bağda, şarabın fıçıda olgunlaştığı yeri yürüyerek gezersiniz.","o":"Bağ gezisi ve tadım programı düzenler, bağ ürünlerini sunarız; yerinde satış bilgisini gezi sonunda veririz.","u":[["Bağ","Gezi asmaların arasında başlar, üzüm çeşitleri tanıtılır."],["Mahzen","Fıçıların durduğu serin mahzen birlikte gezilir."],["Tadım","Kadehler sırayla dolar, her biri anlatılarak tadılır."],["Satış","Beğendiğiniz ürünün satış bilgisi gezi sonunda verilir."]],"k":"Bağı gezmeye ve tatmaya gelin."},"Kurutulmuş meyve":{"s":"Hediye kutusunu açtığınızda lokumlar tek tek sıralı durur.","o":"Kuru meyve ve lokum satar, hediye kutusunu istediğiniz karışımla hazırlar, toptan sipariş alıp kargo yaparız.","u":[["Tadım","Kuru meyve ve lokumdan tadıp karışımı seçersiniz."],["Tartı","Seçilen ürünler ayrı ayrı gramla tartılır."],["Kutu","Hediye kutusu karışımınıza göre dizilir ve bantlanır."],["Kargo","Kutu ezilmeyecek şekilde sarılıp kargoya verilir."]],"k":"Hediye kutunuzu birlikte dolduralım."},"Nail art":{"s":"Tırnağınızın yapısı, hangi uygulamanın yapılacağını belirler.","o":"Manikür, pedikür, kalıcı oje ve protez tırnak yapar, nail art tasarımını elinizin şekline göre çizeriz.","u":[["Tırnak","Tırnak yapısı ve kütikül durumu birlikte incelenir."],["Hazırlık","Kütikül temizlenir, tırnak yüzeyi düzeltilir."],["Kürleme","Baz, renk ve üst kat sırayla lambada kürlenir."],["Tasarım","Taş ya da çizim deseni son kata eklenir."]],"k":"Tırnaklarınıza uygun tasarımı seçelim."},"Kalıcı makyaj":{"s":"Kaş çizimini siz onaylamadan cihaz çalıştırılmaz.","o":"Kaş kontür, dudak renklendirme ve eyeliner uygular; şekli ve rengi önce çizimle belirler, gerekirse rötuş yaparız.","u":[["Çizim","Kaş ya da dudak şekli yüzünüzde çizilir."],["Renk","Pigment tonu cilt altınıza bakılarak denenir."],["Uygulama","Onayladığınız çizgi üzerinden cihazla pigment verilir."],["Rötuş","Cilt toparlandıktan sonra renk kontrol edilip rötuş yapılır."]],"k":"Çizimi önce birlikte onaylayalım."},"Lazer epilasyon":{"s":"Cilt tipiniz ve tüy yapınız, cihaz ayarından önce konuşulur.","o":"Tüm vücut, bacak, koltuk altı ve yüz bölgelerinde lazer epilasyon uygular, seansları paket halinde planlarız.","u":[["Cilt","Cilt tipi ve kullanılan ilaçlar seanstan önce sorulur."],["Tıraş","Bölge tıraş edilir, cilt temizlenir."],["Seans","Cihaz ayarı cilt rengine göre yapılır, atışlar başlar."],["Aralık","Seanslar arası bekleme takvime yazılır."]],"k":"Seans planınızı birlikte çıkaralım."},"Cilt bakımı":{"s":"Cildinize ne sürüleceğine, önce analizi görerek karar veririz.","o":"Cilt analiziyle başlar; klasik cilt bakımı, hydrafacial ve kimyasal peeling seçeneklerinden cildinize uygun olanı birlikte belirleriz.","u":[["Analiz","Cihazla yağ ve nem dengesine bakılır."],["Temizlik","Makyaj ve yüzey kiri nazikçe temizlenir."],["Uygulama","Seçilen bakım ya da peeling adım adım uygulanır."],["Ev bakımı","Evde kullanılacak ürünler sırayla anlatılır."]],"k":"Cildinizin analizini yaptıralım."},"Masaj salonu":{"s":"Masaj sırasında basıncı değiştirmek isterseniz söylemeniz yeterli.","o":"Klasik, aromaterapi ve derin doku masajı ile çift masajı yapar; yağı ve basıncı sizinle konuşarak seçeriz.","u":[["Bölge","Hangi bölgenizin gergin olduğu önceden sorulur."],["Yağ","Aromaterapide koku ve yağ seçimi size bırakılır."],["Masaj","Basınç seans boyunca isteğinize göre ayarlanır."],["Dinlenme","Masaj sonrası odada su ile dinlenirsiniz."]],"k":"Masaj için bir saat ayırın."},"Spa":{"s":"Kese köpükle başlar, sauna ve buharla devam eder.","o":"Kese köpük, masaj, sauna ve buhar bölümlerini çift paketi ve günlük spa paketinde sırayla sunarız.","u":[["Giriş","Havlu, terlik ve dolap anahtarı girişte verilir."],["Isınma","Sauna ve buharda vücut ısınır."],["Kese","Kese köpük sıcak mermer üzerinde yapılır."],["Masaj","Masajla paket tamamlanır, çay ikram edilir."]],"k":"Spa gününüzü ayıralım."},"Kirpik uzatma":{"s":"Kirpik boyu ve kıvrımı yüz hatlarınıza bakılarak seçilir.","o":"İpek ve volume kirpik uygular, kirpik lifting yapar, bakım seansıyla dolgunluğu korumanıza destek oluruz.","u":[["Boy","Kirpik boyu ve kıvrımı göz yapınıza göre seçilir."],["Hazırlık","Alt kirpikler bantla kapatılır, gözleriniz kapalı kalır."],["Yapıştırma","Her uzatma teli tek bir öz kirpiğe yapıştırılır."],["Bakım","Su, yağ ve bakım seansı için not verilir."]],"k":"Kirpiğinizin boyunu birlikte seçelim."},"Kaş tasarımı":{"s":"Kaşınızın şekli, almadan önce yüz hatlarınıza göre çizilir.","o":"Kaş alma, laminasyon, boyama ve microblading uygular; şekli önce çizerek onayınıza sunarız.","u":[["Ölçü","Kaş başı, kavis ve ucu yüzünüze göre ölçülür."],["Çizim","Şekil kalemle çizilir, aynada onaylarsınız."],["Uygulama","Fazlalık alınır, boya ya da laminasyon sürülür."],["Bakım","Sonraki günlerde kaşa nasıl bakılacağı anlatılır."]],"k":"Kaşınızı çizerek birlikte tasarlayalım."},"Solaryum":{"s":"Seans süresi, kabine girmeden önce cilt tipinize göre belirlenir.","o":"Dakika paketi, yüz solaryumu ve seans paketi sunar, bronzlaştırıcı ürünleri cilt tipine göre öneririz.","u":[["Cilt","Cilt tipiniz ve önceki seanslarınız sorulur."],["Süre","Kabinde kalma süresi cilt tipine göre sınırlanır."],["Seans","Gözlük takılır, kabin temizlenir, cihaz çalıştırılır."],["Ürün","Bronzlaştırıcı ürün cildinize uygun olana göre seçilir."]],"k":"Seans planınızı birlikte yapalım."},"Gelin başı":{"s":"Gelin başını provada denemeden düğün sabahına bırakmayız.","o":"Gelin başı, nişan saçı ve refakatçi saçını prova ile hazırlar, düğün sabahı yerinde hazırlığa geliriz.","u":[["Model","Elbise yakası ve duvak saç modelini belirler."],["Prova","Seçilen model prova gününde saçınızda denenir."],["Sabah","Düğün sabahı hazırlık bulunduğunuz yerde başlar."],["Duvak","Taç ve duvak takılır, saç son olarak sabitlenir."]],"k":"Gelin başı için prova günü ayırın."},"Makyöz":{"s":"Gelin makyajı düğün ışığında nasıl duracak, provada görülür.","o":"Gelin makyajı ve özel gün makyajı yapar, prova ile tonu denemenizi sağlar, istenirse yerinde makyaja gideriz.","u":[["Cilt","Cilt tipi ve alerjiler makyajdan önce sorulur."],["Prova","Prova günü ton ve kalıcılık fotoğrafla denenir."],["Gün","Makyaj yerinde, elbise giyilmeden önce yapılır."],["Rötuş","Çantadaki ruj ve pudra için kısa not verilir."]],"k":"Makyaj provanızı ayırın."},"Dövme stüdyosu":{"s":"Çizimi onaylamadan makine ele alınmaz, iğne tek kullanımlıktır.","o":"Küçük ve orta boy dövme yapar, örtme dövmesi için eski izi inceler, kişiye özel çizim hazırlar, bakım önerisi veririz.","u":[["Fikir","Fikriniz ve dövmenin vücuttaki yeri konuşulur."],["Çizim","Çizim bölgeye yerleştirilir, siz onaylarsınız."],["Dövme","Şablon aktarılır, iğne önünüzde açılır."],["Bakım","Sürülecek krem ve kaçınılacaklar yazılı verilir."]],"k":"Dövme fikrinizi çizelim."},"Piercing":{"s":"Takı takılmadan önce delinecek nokta işaretlenir, aynada onaylanır.","o":"Kulak ve burun piercing yapar, takı değişimi ve bakım kontrolü sunarız; takıyı deliğe uygun seçeriz.","u":[["İşaret","Delinecek nokta kalemle işaretlenir, aynada kontrol edilir."],["Takı","İlk takı ve malzemesi cildinize göre seçilir."],["Delme","Steril iğneyle delinir, takı hemen yerine geçer."],["Kontrol","Bakım kontrolünde bölge ve takı yeniden bakılır."]],"k":"Piercing noktanızı birlikte işaretleyelim."},"Saç bakım merkezi":{"s":"Saç derisine bakmadan hangi bakımın uygun olduğu söylenmez.","o":"Saç analiziyle başlar; keratin bakım ve saç dökülmesi bakımını anlatır, PRP uygunluk görüşmesinde gerekirse hekime yönlendiririz.","u":[["Analiz","Saç teli ve saç derisi kamerayla incelenir."],["Görüşme","Dökülme öyküsü ve kullanılan ürünler dinlenir."],["Bakım","Uygun görülen bakım adım adım uygulanır."],["Yönlendirme","PRP gibi işlemler için hekim değerlendirmesi önerilir."]],"k":"Saç analizi için randevu alın."},"Zayıflama merkezi":{"s":"Ölçünüz kayda geçer, program bu kayda göre anlatılır.","o":"Ölçüm ve analizle başlar; bölgesel incelme ve selülit programını anlatır, beslenme yönlendirmesini diyetisyen önerisine bağlı olarak yaparız.","u":[["Ölçüm","Kilo, çevre ölçüsü ve vücut analizi kayda geçer."],["Görüşme","Alışkanlıklarınız ve sağlık durumunuz dinlenir."],["Program","Bölgesel uygulama programı seans düzeniyle anlatılır."],["Takip","Ölçüler seans aralarında yeniden alınır."]],"k":"Ölçümünüzü yaptırmaya gelin."},"Boya badana":{"s":"Eşyalar örtülür, boya tozu evin geri kalanına yayılmaz.","o":"İç ve dış cephe, tavan ve dekoratif boya yapar; boyadan önce alçı tamiriyle duvarı düzeltiriz.","u":[["Örtü","Eşya ve zemin boya damlasına karşı örtülür."],["Zemin","Çatlak alçıyla kapatılır, yüzey zımparalanır."],["Astar","Astar sürülür, kuruması beklenir."],["Boya","Boya katlar halinde sürülür, bantlar çekilir."]],"k":"Duvarlarınız için keşfe çağırın."},"Alçı ustası":{"s":"Duvar çekilmeden önce köşe çıtası ve çatlak yerleri kontrol edilir.","o":"Alçı sıva ve saten alçı çeker, alçıpan tavan ile kartonpiyer yapar, duvarı boyaya hazır bırakırız.","u":[["Çıta","Köşelere çıta takılır, sıva kalınlığı ayarlanır."],["Sıva","Alçı sıva duvara mala ile çekilir."],["Saten","Saten alçı ince çekilip zımparayla düzeltilir."],["Tavan","Alçıpan tavan ve kartonpiyer profillere bağlanır."]],"k":"Duvarlarınızı alçıya hazırlayalım."},"Fayans ustası":{"s":"Fayansı yapıştırmadan önce zeminin su eğimi kontrol edilir.","o":"Fayans ve yer seramiği döşer, banyo yenilemesi ve derz yenileme yaparız; eğimi giderden başlayarak kurarız.","u":[["Eğim","Zeminin gidere doğru eğimi su terazisiyle bakılır."],["Dizilim","Fayanslar yapıştırmadan önce yerde dizilip kesimi planlanır."],["Yapıştırma","Yapıştırıcı tarakla sürülür, plakalar aralık çıtasıyla oturur."],["Derz","Derz dolgusu doldurulur, fazlası silinir."]],"k":"Fayansınızı döşemeden önce ölçelim."},"Parke ustası":{"s":"Parkenin altına serilecek nem örtüsü ilk iş olarak yapılır.","o":"Laminat ve masif parke döşer, parke cilası ve süpürgelik takarız; zemin düzgünlüğünü önce ölçeriz.","u":[["Zemin","Şap düzgünlüğü ve nemi ölçülür."],["Şilte","Nem örtüsü ve ses şiltesi serilir."],["Döşeme","Parkeler duvardan genleşme payı bırakılarak döşenir."],["Süpürgelik","Süpürgelik takılır, masif parkede cila çekilir."]],"k":"Zemininiz için keşif isteyin."},"Mantolama":{"s":"Dış cephede ısı kaybı, iskele kurulmadan önce yerinde görülür.","o":"Dış cephe mantolama ve çatı yalıtımı yapar, iskele kurulumunu üstlenir; ısı kaybı keşfinde zayıf noktaları gösteririz.","u":[["Keşif","Cephede ısı kaybı olan noktalara yerinde bakılır."],["İskele","İskele kurulur, cephe yıkanır."],["Levha","Yalıtım levhaları yapıştırılır ve dübelle sabitlenir."],["Sıva","Levhalar file ve sıva ile kapatılır, boya sürülür."]],"k":"Cephenizin ısı kaybını gösterelim."},"Çatı ustası":{"s":"Sızan yeri bulmadan kiremit değiştirmeyiz.","o":"Çatı aktarma ve kiremit değişimi yapar, oluk ve dere onarır, çatı yalıtımını tamamlarız.","u":[["Sızıntı","Tavandaki lekeden çatıdaki sızma noktası aranır."],["Söküm","Kiremit ve altındaki çıta sökülür, ahşaba bakılır."],["Yalıtım","Membran ve yalıtım örtüsü serilir."],["Kapatma","Kiremit, oluk ve dere yerine takılır."]],"k":"Çatınızı çıkıp birlikte görelim."},"Su yalıtımı":{"s":"Rutubetin kaynağı bulunmadan yalıtım malzemesi sürülmez.","o":"Teras, bodrum ve banyo yalıtımı yapar, rutubet tespitiyle sızıntı kaynağını bulur, uygun yalıtım sistemini seçeriz.","u":[["Tespit","Nem ölçerle ve gözle sızıntı kaynağı aranır."],["Yüzey","Eski kaplama kazınır, çatlaklar onarılır."],["Membran","Yalıtım malzemesi katlar halinde sürülür ya da serilir."],["Su testi","Zemine su verilip sızma olup olmadığı izlenir."]],"k":"Rutubetin kaynağını birlikte bulalım."},"İç mimar":{"s":"Çizimdeki mekânı, mobilya yerleşmeden önce üç boyutlu görürsünüz.","o":"İç mekân projesi çizer, 3D görselleştirme hazırlar, malzeme seçimini ve uygulama takibini yürütür, ofis ve mağaza tasarımı da yaparız.","u":[["Ölçü","Mekânın ölçüsü alınır, kullanım düzeni konuşulur."],["Görsel","3D görselle mobilya yerleşimi ekranda gösterilir."],["Malzeme","Zemin, kaplama ve tekstil numuneleri elinize verilir."],["Şantiye","Uygulamada çizimle sahadaki iş karşılaştırılır."]],"k":"Mekânınızı çizimle görün."},"Mimarlık ofisi":{"s":"Ruhsat dosyası belediyeye gitmeden önce eksiksiz hazırlanır.","o":"Mimari proje ve ruhsat dosyasını hazırlar, tadilat projesi ve rölöve çizer, inşaat sürecinde uygulama takibi yaparız.","u":[["Rölöve","Mevcut yapı yerinde ölçülüp çizime aktarılır."],["Proje","Plan, kesit ve görünüşler çizilir."],["Ruhsat","Dosya imar durumuna göre belediyeye verilir."],["Şantiye","Uygulamanın projeye uyup uymadığına sahada bakılır."]],"k":"Projeye imar durumuyla başlayalım."},"Peyzaj":{"s":"Bitki seçilmeden önce bahçenin güneşi ve toprağı incelenir.","o":"Bahçe tasarımı yapar, çim ve otomatik sulama kurar, sert zemin kaplamayı döşeriz; sonrasında bitki bakımına devam ederiz.","u":[["Etüt","Bahçenin güneş alma durumu ve toprağı incelenir."],["Plan","Yürüme yolları, çim ve bitki alanları çizilir."],["Sulama","Damla ya da yağmurlama hatları toprağa döşenir."],["Ekim","Çim serilir, bitkiler dikilir, taşlar yerleştirilir."]],"k":"Bahçenizi yerinde görelim."},"Havuz yapımı":{"s":"Havuz kazılmadan önce zeminin taşıma gücüne bakılır.","o":"Betonarme ve prefabrik havuz yapar, havuz ekipmanı kurar, bakımını yürütürüz; keşif ve projeyle başlarız.","u":[["Keşif","Arazi, zemin ve eğim yerinde incelenir."],["Kazı","Havuz çukuru kazılır, demir ve kalıp hazırlanır."],["Tesisat","Pompa, filtre ve borular döşenir."],["Dolum","Su verilir, ekipman çalıştırılıp sızdırmazlığa bakılır."]],"k":"Havuzunuzun yerini birlikte seçelim."},"Prefabrik":{"s":"Prefabrik evin temeli, evden önce projede çizilir.","o":"Prefabrik ev, şantiye ofisi ve bahçe ofisi üretir, temel projesini hazırlar, nakliye ve montajı yaparız.","u":[["Temel","Temel projesi arazinize göre hazırlanır."],["İmalat","Paneller atölyede ölçüye göre üretilir."],["Nakliye","Parçalar sıra işaretlenir ve araçla taşınır."],["Montaj","Paneller temele oturtulur, bağlantılar kapatılır."]],"k":"Arazinizi birlikte görelim."},"Çelik konstrüksiyon":{"s":"Statik hesap yapılmadan tek bir kiriş kesilmez.","o":"Depo, hangar ve çatı konstrüksiyonu için çelik yapı projesi çizer, statik hesabı yapar, imalat ve montajı yürütürüz.","u":[["Statik","Yük ve açıklık hesabı yapılır, kesitler belirlenir."],["Detay","Bağlantı ve kaynak detayları atölye çizimine geçer."],["İmalat","Profiller kesilir, kaynaklanır ve boyanır."],["Montaj","Parçalar sahada bulonlanıp ayağa kaldırılır."]],"k":"Yapınızın statiğini çizerek başlayalım."},"Hazır beton":{"s":"Mikserin irsaliyesinde beton sınıfı yazar, siz de okursunuz.","o":"C25 ve C30 beton döker, pompa hizmeti verir, şantiyeye sevkiyat yapar, beton numune takibini yürütürüz.","u":[["Sınıf","Projedeki beton sınıfı sipariş formuna yazılır."],["Mikser","İrsaliye şantiyede sınıf ve saatle kontrol edilir."],["Pompa","Beton pompayla kalıba ya da döşemeye basılır."],["Numune","Numune alınıp kür havuzuna konur, sonuç raporlanır."]],"k":"Dökümünüz için sınıfı birlikte yazalım."},"Hafriyat":{"s":"Kazıdan çıkan toprağın nereye gideceği baştan bellidir.","o":"Kazı ve temel hafriyatı yapar, moloz taşır, iş makinesi kiralar, sahayı düzenleriz.","u":[["Saha","Arazi gezilir, kot ve toprak cinsine bakılır."],["Kazı","Ekskavatör kot çizgisine göre kazar."],["Nakliye","Kamyonlar toprağı ve molozu döküm alanına taşır."],["Düzeltme","Saha greyderle düzeltilir ve sıkıştırılır."]],"k":"Sahanızı yerinde görelim."},"Yapı denetim":{"s":"Beton dökümünden önce demir donatı yerinde kontrol edilir.","o":"Proje incelemesi ve şantiye denetimi yapar, numune takibi, hakediş raporu ve kurum yazışmalarını yürütürüz.","u":[["Proje","Uygulama projesi incelenir, eksik varsa bildirilir."],["Donatı","Donatı ve kalıp döküm öncesi şantiyede kontrol edilir."],["Numune","Beton numuneleri laboratuvara gönderilir, sonuç dosyalanır."],["Hakediş","Yapılan iş ölçülüp hakediş raporu hazırlanır."]],"k":"Şantiyenizin dosyasını düzenli tutalım."},"Mühendislik bürosu":{"s":"Statik proje, elektrik ve mekanik projeyle aynı masada çizilir.","o":"Statik, elektrik ve mekanik proje hazırlar, mevcut yapılar için güçlendirme raporu yazar, danışmanlık veririz.","u":[["Veri","Mimari proje ve zemin etüdü alınır."],["Hesap","Yük ve kesit hesapları yapılır."],["Çizim","Statik, elektrik ve mekanik paftalar birbirine uydurulur."],["Rapor","Güçlendirme gerekiyorsa mevcut yapı için rapor yazılır."]],"k":"Projenizin mühendislik dosyasını hazırlayalım."},"Mutfak dolabı":{"s":"Dolap yapılmadan önce duvarlar ölçülür, tesisat noktaları işaretlenir.","o":"Ölçü ve çizimden başlar; lake ve membran mutfak dolabı üretir, tezgâhı ve montajı da yaparız.","u":[["Ölçü","Duvar, tesisat ve elektrik noktaları yerinde ölçülür."],["Çizim","Dolap yerleşimi çizilir, kapak rengi seçilir."],["Üretim","Parçalar atölyede kesilir, lake ya da membran kaplanır."],["Montaj","Dolaplar duvara tutturulur, tezgâh yerine oturtulur."]],"k":"Mutfağınızı ölçüyle başlatalım."},"Banyo tadilatı":{"s":"Eski fayansı kırmadan önce boruların yeri çizilir.","o":"Komple banyo yenileme, fayans döşeme, vitrifiye değişimi, duşakabin montajı ve tesisat yenilemeyi tek elden yaparız.","u":[["Söküm","Eski fayans ve vitrifiye sökülür, moloz çıkarılır."],["Tesisat","Su ve pis su boruları yenilenir."],["Yalıtım","Zemine su yalıtımı yapılır, eğim verilir."],["Montaj","Fayans, klozet, lavabo ve duşakabin yerine takılır."]],"k":"Banyonuzu yerinde görmeye gelelim."},"Pastane":{"s":"Doğum günü pastasında yazı ve renk siparişte netleşir.","o":"Yaş pasta, kuru pasta ve börek çeşitleri yapar, doğum günü pastasını isteğinize göre süsler, toplu sipariş alırız.","u":[["Sipariş","Pasta tadı, kişi sayısı ve yazı not edilir."],["Hazırlık","Kek pişirilir, krema ve iç harcı hazırlanır."],["Süsleme","Pasta kremayla kaplanır, yazı ve süs eklenir."],["Teslim","Pasta kutuya konur, soğukta teslim edilir."]],"k":"Pastanızı siparişte birlikte tasarlayalım."},"Çay bahçesi":{"s":"Aile masası, hafta sonu kalabalığında sizi bekler.","o":"Çay, tost ve kahvaltı tabağı sunar, aile masası rezervasyonu alırız.","u":[["Masa","Gelecek kişi sayısına göre masa ayrılır."],["Çay","Çay taze demlenip masaya gelir."],["Tabak","Tost ve kahvaltı tabağı sıcak getirilir."],["Hesap","Aile masasında hesap tek kalemde kesilir."]],"k":"Aile masanızı ayırtın."},"Nargile kafe":{"s":"Nargile gelmeden önce tütün aromasını size sorarız.","o":"Nargile, Türk kahvesi ve soğuk içecek sunar, masa rezervasyonu alırız; kömürü masada tazeleriz.","u":[["Aroma","Tütün aroması ve sertliği sorulur."],["Hazırlık","Köz ve su hazırlanıp nargile masaya kurulur."],["Kahve","Türk kahvesi şekerine göre pişirilir."],["Köz","Köz soğudukça masada yenilenir."]],"k":"Masanızı nargile için ayırtın."},"Bar":{"s":"Kokteyl, damak tadınıza göre birlikte seçilir.","o":"Klasik ve imza kokteyller, yerli içki seçkisi ve aperatif tabağı sunar, masa rezervasyonu alırız.","u":[["Tat","Tatlı, ekşi ya da sert sevdiğiniz sorulur."],["Karışım","Kokteyl önünüzde şeykerle hazırlanır."],["Aperatif","İçkinin yanına aperatif tabağı eklenir."],["Masa","Masa saat ve kişi sayısına göre ayrılır."]],"k":"Masanızı barda ayırtın."},"Dondurmacı":{"s":"Dondurma külahta erimeden önce kaşıkta tadılır.","o":"Top dondurma ve kilo dondurma satar, sütlü tatlı ile soğuk içecek de sunarız.","u":[["Tat","Kaşıkla küçük bir tat denenir."],["Top","Toplar külaha ya da kaseye doldurulur."],["Kilo","Kilo dondurma kutuya ve soğuk poşete konur."],["Tatlı","Sütlü tatlı ve soğuk içecek yanında alınır."]],"k":"Dondurmanızı kaşıkta tadın."},"Waffle":{"s":"Waffle sipariş verince hamurdan pişer, tezgâhta beklemez.","o":"Klasik, meyveli ve çikolatalı waffle yapar, soğuk içecekle servis ederiz.","u":[["Hamur","Hamur siparişle waffle plakasına dökülür."],["Pişirme","Waffle plakada altın rengi alana kadar pişer."],["Üzeri","Meyve doğranır, çikolata eritilip sürülür."],["Servis","Waffle sıcakken soğuk içecekle masaya gider."]],"k":"Sıcak waffle için sipariş verin."},"Tatlıcı":{"s":"Baklavada şerbet fazla gelmesin diye tepside dinlendirilir.","o":"Fıstıklı baklava, künefe, sütlü ve şerbetli tatlılar yapar, kutu hediye hazırlarız.","u":[["Yufka","Baklava yufkası açılıp fıstıkla tepsiye dizilir."],["Şerbet","Sıcak şerbet soğumuş baklavaya dökülür ve dinlendirilir."],["Künefe","Künefe siparişle kızartılır, peyniri uzarken servis edilir."],["Kutu","Dilimler hediye kutusuna sıralanır."]],"k":"Hediye kutunuzu tatlıdan seçin."},"Bubble tea":{"s":"Topların yumuşaklığı bardağa konmadan önce kontrol edilir.","o":"Klasik sütlü çay ve meyveli çay yapar, istediğiniz ek topu ekler, paket servis veririz.","u":[["Çay","Çay demlenir, sütlü ya da meyveli seçilir."],["Top","Tapyoka topları pişirilip şekerli suda bekletilir."],["Ek","Ek top ve şeker miktarı sorulur."],["Kapak","Bardak kapatılır, kalın pipetle paket olarak verilir."]],"k":"Bardağınızı toplarla doldurun."},"Kitap kafe":{"s":"Kahveniz soğumadan sayfanın yarısına gelirsiniz, köşe sizin.","o":"Filtre kahve ve sandviç sunar, okuma köşesinde sessiz masa ayırır, etkinlik takvimini duyururuz.","u":[["Köşe","Okuma köşesinde sessiz bir masa seçilir."],["Kahve","Filtre kahve taze demlenir."],["Kitap","Rafta bulduğunuz kitap masaya alınır."],["Etkinlik","Takvimdeki söyleşi ve okuma saatleri duyurulur."]],"k":"Okuma köşenizi ayırtın."},"Ortodonti":{"s":"Tedavi planı muayeneden sonra diş hekimi tarafından anlatılır.","o":"Ortodontik muayeneyle başlar; telli tedavi, şeffaf plak ve çocuklarda erken değerlendirme seçeneklerini hekim görüşmesinde anlatırız.","u":[["Muayene","Ağız içi muayene ve diş yapısı değerlendirilir."],["Kayıt","Röntgen ve ölçü kayıtları alınır."],["Plan","Hekim uygun tedavi seçeneklerini anlatır."],["Kontrol","Tedavi sırasında düzenli kontrol ve pekiştirme takibi yapılır."]],"k":"Ortodontik muayene için randevu alın."},"Göz kliniği":{"s":"Göz muayenesi, şikâyetinizi dinleyerek ve gözünüze bakarak başlar.","o":"Göz muayenesi yapar; katarakt değerlendirmesi, glokom takibi ve çocuk göz muayenesinde süreci hekim açıklar.","u":[["Şikâyet","Gözünüzdeki şikâyet ve geçmiş hastalıklar sorulur."],["Muayene","Görme ve göz içi basıncı ölçülür."],["Tetkik","Gerekirse görüntüleme ve ek testler yapılır."],["Plan","Hekim bulguları ve izleme planını anlatır."]],"k":"Göz muayenesi için randevu alın."},"Estetik cerrahi":{"s":"Ön görüşme, karar vermeden önce sorularınızı sormak içindir.","o":"Ön görüşmede burun, yüz ve vücut estetiği değerlendirmelerini hekim anlatır; ameliyat sonrası kontrol sürecini önceden açıklarız.","u":[["Görüşme","Beklentiniz ve sağlık geçmişiniz hekimle konuşulur."],["Muayene","İlgili bölge muayene edilir, seçenekler anlatılır."],["Bilgi","Süreç, riskler ve bakım yazılı olarak açıklanır."],["Kontrol","Ameliyat sonrası kontrol randevuları önceden planlanır."]],"k":"Sorularınızı ön görüşmede sorabilirsiniz."},"Saç ekimi":{"s":"Ekim planı, saçınızın durumuna bakıldıktan sonra konuşulur.","o":"Saç analizi ile başlarız; FUE ya da DHI uygunluğuna hekim karar verir, ekim sonrası takip randevuları da planlanır.","u":[["Analiz","Saç çizgisi ve donör bölge incelenir."],["Yöntem","FUE ya da DHI uygunluğunu hekim değerlendirir."],["Ekim günü","İşlem öncesi bilgilendirme ve onay formu doldurulur."],["Takip","Yıkama ve kontrol randevuları size bildirilir."]],"k":"Saç analizi için randevu alın."},"Fizik tedavi":{"s":"Egzersizleriniz, günlük hayatınıza ve ağrı bölgenize göre yazılır.","o":"Fizyoterapi değerlendirmesiyle başlar, bel ve boyun programı ya da ameliyat sonrası rehabilitasyon için ev programı hazırlarız.","u":[["Öykü","Şikâyetin nerede ve ne zaman başladığı dinlenir."],["Muayene","Hareket açıklığı ve kas gücü ölçülür."],["Program","Seans planı ve ev egzersizleri yazılır."],["Kontrol","İlerleme kayıt altına alınıp program güncellenir."]],"k":"Değerlendirme randevusu için yazın."},"Diyetisyen":{"s":"Plan, mutfağınıza ve çalışma saatlerinize uyacak şekilde hazırlanır.","o":"İlk görüşmede alışkanlıklarınızı dinler, kişiye özel beslenme planı yazar, online takip ile ölçülerinizi birlikte izleriz.","u":[["Alışkanlık","Öğünleriniz, uykunuz ve tahlilleriniz gözden geçirilir."],["Ölçü","Vücut analizi yapılır, hedef birlikte belirlenir."],["Menü","Haftalık liste evinizdeki ürünlerle yazılır."],["Takip","Ölçüleriniz ve uyumunuz online görüşmelerle izlenir."]],"k":"İlk görüşme için gün seçin."},"Psikolog":{"s":"Ne anlatacağınıza siz karar verirsiniz, görüşme sizin hızınızda ilerler.","o":"İlk görüşmede ihtiyacınız konuşulur; bireysel terapi, çift terapisi ya da online seans çerçevesi birlikte belirlenir.","u":[["Tanışma","Başvuru nedeni ve beklentiniz dinlenir."],["Çerçeve","Seans sıklığı ve gizlilik ilkeleri açıklanır."],["Seanslar","Görüşmeler belirlenen gün ve saatte yürütülür."],["Gözden geçirme","Süreç belirli aralıklarla birlikte değerlendirilir."]],"k":"İlk görüşme için yazabilirsiniz."},"Psikiyatrist":{"s":"Kullandığınız ilaçlar ve geçmiş şikâyetleriniz görüşmenin başında kayda geçer.","o":"Psikiyatrik değerlendirme ile başlar, ilaç takibi ve kontrol randevusu hekimin planına göre sürdürülür.","u":[["Anamnez","Şikâyetler, aile öyküsü ve kullanılan ilaçlar kaydedilir."],["Değerlendirme","Hekim görüşme bulgularını sizinle paylaşır."],["Tedavi planı","Planın ilaç ve görüşme kısmı açıklanır."],["Kontrol","İlaca verilen yanıt ve yan etkiler sorulur."]],"k":"Randevu için bize ulaşın."},"Dermatoloji":{"s":"Cildinizdeki değişiklik, muayene edilmeden yorumlanmaz.","o":"Cilt muayenesi ve ben kontrolünde dermatoskopla bakılır; akne, saç ve tırnak şikâyetleri için hekim plan oluşturur.","u":[["Şikâyet","Lezyonun ne zaman çıktığı ve değiştiği sorulur."],["Muayene","Cilt, saç ya da tırnak ışık altında incelenir."],["Dermatoskop","Benler büyütülerek şekil ve renk yönünden bakılır."],["Plan","Hekim bakım ve kontrol aralığını anlatır."]],"k":"Muayene randevusu için yazın."},"Kadın doğum":{"s":"Muayene öncesi soracağınız her şey için zaman ayrılır.","o":"Jinekolojik muayene, yıllık kontrol ve ultrason ile gebelik takibi hekim eşliğinde, sakin bir randevu düzeniyle yürür.","u":[["Kayıt","Son adet tarihi ve geçmiş gebelikler not edilir."],["Muayene","Hekim muayeneyi adım adım anlatarak yapar."],["Ultrason","Gerekirse görüntüleme aynı randevuda yapılır."],["Takvim","Bir sonraki kontrol tarihi size verilir."]],"k":"Kontrol randevunuzu ayırtın."},"Çocuk doktoru":{"s":"Çocuğunuzun aşı ve gelişim defteri tek yerde tutulur.","o":"Çocuk muayenesi, aşı takibi ve büyüme gelişme kontrolünü yenidoğan döneminden itibaren düzenli kayıtla izleriz.","u":[["Öykü","Ateş, beslenme ve uyku bilgisi ebeveynden alınır."],["Ölçüm","Boy, kilo ve baş çevresi gelişim eğrisine işlenir."],["Muayene","Hekim çocuğu korkutmadan sakin biçimde muayene eder."],["Aşı takvimi","Bir sonraki aşı ve kontrol tarihi yazılır."]],"k":"Çocuğunuz için randevu alın."},"Muayenehane":{"s":"Tahlil kâğıdınızın ne dediğini randevuda birlikte okuruz.","o":"Muayene, tahlil yorumlama ve kontrol randevusuyla ilerler; tedavi planınızı hekim açıklar, sorularınızı yanıtlar.","u":[["Kayıt","Önceki tahlil ve raporlarınızı yanınızda getirirsiniz."],["Muayene","Hekim şikâyetinizi dinler ve muayene eder."],["Yorum","Tahlil sonuçları sade bir dille açıklanır."],["Kontrol","Tedavi planı ve kontrol tarihi yazılır."]],"k":"Muayene için sıra alın."},"Tıp merkezi":{"s":"Tahlil, görüntüleme ve muayene tek dosyada yönlendirilir.","o":"Dahiliye muayenesiyle başlayıp check-up programı, laboratuvar tetkikleri ve görüntüleme yönlendirmesini tek dosyada yürütürüz.","u":[["Kabul","Kimlik ve sigorta bilginizle dosyanız açılır."],["Muayene","Dahiliye hekimi gerekli tetkikleri belirler."],["Tetkik","Kan ve görüntüleme işlemleri sırayla yapılır."],["Sonuç","Sonuçlar hekimle birlikte okunur."]],"k":"Check-up için randevu alın."},"Evde bakım":{"s":"Bakım görevlisi, yakınınızın alışkanlıklarını öğrendikten sonra işe başlar.","o":"Yaşlı ve hasta bakımı, refakatçi ve gece bakımı için önce evde değerlendirme yapar, günlük bakım düzenini aileyle yazarız.","u":[["Evde görüşme","Yakınınızın ihtiyacı ve ev düzeni yerinde görülür."],["Bakım listesi","İlaç saatleri ve öğünler yazılır."],["Eşleştirme","Uygun görevli aileyle tanıştırılır."],["Günlük not","Her vardiyanın bakım notu aileye iletilir."]],"k":"Evde değerlendirme için arayın."},"Hemşirelik hizmeti":{"s":"Doktorunuzun yazdığı uygulama, evinizde talimata uygun yapılır.","o":"Evde serum takibi, enjeksiyon, pansuman ve sonda bakımını hekim talimatına göre yapar, tansiyon ve şeker ölçümlerini kaydederiz.","u":[["Reçete","Hekim talimatı ve ilaç bilgisi kontrol edilir."],["Hazırlık","Steril malzeme evinize hazır getirilir."],["Uygulama","Serum, iğne ya da pansuman yapılır."],["Kayıt","Tansiyon ve şeker değerleri deftere yazılır."]],"k":"Evde hemşire için bize yazın."},"Sağlık turizmi":{"s":"Gelmeden önce yolculuğun her adımı sizinle konuşulur.","o":"Tedavi planı danışmanlığı yapar, klinik yönlendirmesi, havalimanı karşılama, konaklama ve tercüman desteğini tek program halinde düzenleriz.","u":[["Dosya","Rapor ve görüntüleriniz klinik hekimine iletilir."],["Plan","Hekim görüşü gelince tarihler netleşir."],["Yolculuk","Karşılama, otel ve araç ayarlanır."],["Klinik günü","Tercüman yanınızda olur, belgeler tamamlanır."]],"k":"Dosyanızı iletin, planı konuşalım."},"Konuşma terapisti":{"s":"Terapi, çocuğunuzun oyun diliyle ve kendi hızında ilerler.","o":"Dil ve konuşma değerlendirmesi yapar; kekemelik, artikülasyon ve çocuk dil gelişimi için seans planını aileyle paylaşırız.","u":[["Değerlendirme","Dil, ses ve konuşma akıcılığı gözlemlenir."],["Hedef","Aileyle seans hedefleri birlikte yazılır."],["Seans","Alıştırmalar oyun ve konuşmayla yürütülür."],["Ev çalışması","Aileye evde yapılacak kısa alıştırmalar verilir."]],"k":"Değerlendirme için randevu alın."},"Ergoterapi":{"s":"Günlük yaşamda zorlandığınız hareket, seansın konusu olur.","o":"Ergoterapi değerlendirmesiyle duyu bütünleme ve günlük yaşam becerileri için çocuğa ya da yetişkine özel bir program kurarız.","u":[["Gözlem","Giyinme, yemek ve oyun becerileri izlenir."],["Duyu profili","Dokunma ve denge tepkileri değerlendirilir."],["Program","Seans etkinlikleri hedefe göre seçilir."],["Aile","Evde uygulanacak küçük düzenlemeler anlatılır."]],"k":"Değerlendirme için bize ulaşın."},"Akupunktur":{"s":"İğneler uygulanmadan önce geçmiş hastalıklarınız ve ilaçlarınız sorulur.","o":"Ön görüşmede şikâyetinizi dinler, akupunktur seansını ve ağrı programını hekim çerçevesinde planlar, kontrol görüşmesiyle gözden geçiririz.","u":[["Ön görüşme","Hastalık öyküsü ve kullandığınız ilaçlar alınır."],["Nokta seçimi","Uygulanacak noktalar size anlatılır."],["Seans","Tek kullanımlık steril iğneler uygulanır."],["Kontrol","Seans sonrası hissettikleriniz kayda geçer."]],"k":"Ön görüşme için randevu alın."},"Kulak burun boğaz":{"s":"Burnunuzun neden tıkandığı muayenede gözle görülerek anlatılır.","o":"KBB muayenesinde sinüzit, burun tıkanıklığı ve kulak şikâyetlerini endoskopla inceler, çocuklarda geniz eti takibini düzenli sürdürürüz.","u":[["Şikâyet","Akıntı, koku ve işitme sorunları sorulur."],["Endoskopi","Burun ve boğaz ince kamerayla incelenir."],["Kulak","Gerekirse kulak temizliği muayenede yapılır."],["Takip","Hekim kontrol tarihini ve bakım önerisini verir."]],"k":"KBB randevusu için yazın."},"Ortopedi":{"s":"Ağrıyan eklem, filminiz görülmeden yorumlanmaz.","o":"Ortopedi muayenesinde eklem, omurga ve spor yaralanmalarını inceler, kırık takibini filmlerle birlikte hekim eşliğinde sürdürürüz.","u":[["Öykü","Düşme, yük ve ağrının saati sorulur."],["Muayene","Eklem hareketi ve duyu kontrol edilir."],["Görüntüleme","Gerekirse röntgen ya da MR istenir."],["Plan","Hekim bulguları filmler üzerinde gösterir."]],"k":"Muayene için sıra alın."},"Kardiyoloji":{"s":"Kalp ritminiz kâğıda dökülür, hekim sizinle birlikte okur.","o":"Kardiyoloji muayenesinde EKG, efor testi ve ekokardiyografi ile kalbinizi inceler, tansiyon takibini düzenli kayda bağlarız.","u":[["Şikâyet","Çarpıntı, nefes darlığı ve göğüs ağrısı sorulur."],["EKG","Kalp ritmi kısa sürede kayda alınır."],["Efor","Gerekirse koşu bandında kalbin yanıtı izlenir."],["Eko","Kalp kapakları ultrasonla görüntülenir."]],"k":"Kalp kontrolü için randevu alın."},"Üroloji":{"s":"Mahrem bir muayene, sakin ve kapalı bir odada yapılır.","o":"Üroloji muayenesi, prostat değerlendirmesi ve taş hastalığı takibini ultrason eşliğinde yapar, kontrol randevusunu dosyanıza işleriz.","u":[["Görüşme","Şikâyetler baş başa ve rahat konuşulur."],["Tetkik","İdrar tahlili ve gerekirse PSA istenir."],["Ultrason","Böbrek ve mesane görüntülenir."],["Kontrol","Hekim bulguları anlatıp sonraki tarihi verir."]],"k":"Muayene için bize yazın."},"Diyaliz merkezi":{"s":"Seans günleriniz sabit kalır, makineniz ve yatağınız hazır bekler.","o":"Hemodiyaliz seansı planlama, diyet danışmanlığı ve misafir hasta kabulünü yapar, nakil bilgilerinizi merkezler arasında düzenli taşırız.","u":[["Kabul","Nefroloji raporu ve hepatit tetkikleri incelenir."],["Planlama","Seans günleri ve saatleri yazılır."],["Seans","Bağlantı öncesi tartı ve tansiyon ölçülür."],["Beslenme","Diyetisyen potasyum ve sıvı sınırını anlatır."]],"k":"Seans planı için arayın."},"Oto yedek parça":{"s":"Şasi numaranızı yazın, parça aracınıza uyuyorsa söyleriz.","o":"Şasi numarasıyla parça sorgular; fren, filtre, motor ve şanzıman grubundan doğru parçayı ayırıp aynı gün kargoya veririz.","u":[["Şasi","Ruhsattaki şasi numarası sisteme girilir."],["Katalog","Orijinal ve yan sanayi eşleşmesi çıkarılır."],["Stok","Parça rafta teyit edilip ayrılır."],["Kargo","Paket yola çıkar, takip numarası size yazılır."]],"k":"Şasi numaranızı gönderin."},"Oto aksesuar":{"s":"Ekran aracınızın göğsüne uyar mı, takmadan önce bakılır.","o":"Multimedya ekran, geri görüş kamerası, paspas ve cam filmi seçimini araç modelinize göre yapar, montajı dükkânda tamamlarız.","u":[["Model","Araç marka, model ve yılı not edilir."],["Uyum","Çerçeve ve soket uyumu kontrol edilir."],["Montaj","Kablolama panele zarar vermeden yapılır."],["Ayar","Kamera çizgileri ve ses ayarı birlikte denenir."]],"k":"Aracınızın modelini yazın."},"Bisiklet satışı":{"s":"Kadro boyu, boyunuza göre seçilmeden bisiklet verilmez.","o":"Şehir, dağ ve çocuk bisikletlerinde boy ve kullanıma göre seçim yapar, bakım ve ayarı satış sonrası da dükkânda sürdürürüz.","u":[["Boy","İç bacak ölçünüze göre kadro boyu seçilir."],["Kullanım","Yol, yokuş ve günlük mesafe konuşulur."],["Deneme","Sele ve gidon yüksekliği üstünüzde ayarlanır."],["Bakım","Vites ve fren ilk ayarı için tekrar uğrarsınız."]],"k":"Deneme sürüşüne bekleriz."},"Pet shop":{"s":"Mamayı değiştirirken eskisiyle karıştırma oranını da söyleriz.","o":"Kedi ve köpek maması, kum, tasma ve kemirgen ürünlerini hayvanın yaşına ve cinsine göre ayırır, eve teslim ederiz.","u":[["Tür","Hayvanın türü, yaşı ve kilosu sorulur."],["Mama","Hassasiyeti varsa içerik etiketi birlikte okunur."],["Ekipman","Tasma ve kafes ölçüsü boyuna göre seçilir."],["Teslim","Ağır kum ve mama kapınıza getirilir."]],"k":"Mama siparişi için yazın."},"Akvaryumcu":{"s":"Balıklar eve girmeden önce suyun döngüsü kurulur.","o":"Akvaryum kurulumu, filtre, canlı bitki ve süs balığı seçimini su hacmine göre yapar, periyodik bakımla suyu dengede tutarız.","u":[["Litre","Dolap ölçüsüne göre hacim ve filtre seçilir."],["Döngü","Su olgunlaşması için balıksız bekleme yapılır."],["Balık","Birlikte yaşayacak türler uyum yönünden seçilir."],["Bakım","Kısmi su değişimi ve cam temizliği yapılır."]],"k":"Akvaryum kurulumu için sorun."},"Evcil hayvan maması":{"s":"Kabın dibi görünmeden yeni mama kapınıza gelir.","o":"Kedi ve köpek maması için abonelik sipariş kurar, tüketim hızınıza göre eve teslim eder, mama danışmanlığında içerik okuruz.","u":[["Hayvan","Yaş, kilo ve hassasiyet bilgisi alınır."],["Mama seçimi","İçerik etiketi ve porsiyon birlikte belirlenir."],["Abonelik","Torba boyutu ve gönderim sıklığı yazılır."],["Değişim","Marka ya da cins değişirse sipariş güncellenir."]],"k":"Abonelik için bize yazın."},"Butik":{"s":"Beğendiğiniz parça, bedeniniz varsa sizin için ayrılır.","o":"Yeni sezon elbise, bluz ve ceketlerde beden sorgulama yapar, denemek istediklerinizi rezerve ederiz.","u":[["Beden","Aradığınız parçanın bedeni stokta aranır."],["Rezerve","Parça adınıza ayrılıp askıya alınır."],["Prova","Aynı kombinle farklı beden denenir."],["Paket","Ütülenip kılıfında teslim edilir."]],"k":"Bedeninizi sorun, ayıralım."},"Ayakkabıcı":{"s":"Numaranız rafta yoksa depodan getirtip ayırırız.","o":"Kadın, erkek ve spor ayakkabıda numara sorgular, bakmak istediğiniz çifti rezerve eder, uğradığınızda denetiriz.","u":[["Numara","Model ve numara stok kaydından bakılır."],["Ayırma","Çift kutusunda adınıza bekletilir."],["Deneme","Çorapla giyilip yürünerek taban denenir."],["Değişim","Dar ya da bol gelirse numara değiştirilir."]],"k":"Numaranızı yazın, bakalım."},"Çanta mağazası":{"s":"Valiz seçerken içine ne sığacağını birlikte hesaplarız.","o":"Kadın çanta, sırt çantası, valiz ve cüzdanı kullanım amacınıza göre gösterir, beğendiğinizi rezerve ederiz.","u":[["Kullanım","İş, okul ya da seyahat için olduğu sorulur."],["Hacim","Eşyalarınız çantaya konarak sığma durumuna bakılır."],["Ayrıntı","Fermuar, astar ve askı dikişi gösterilir."],["Rezerve","Seçtiğiniz renk adınıza ayrılır."]],"k":"Çantanızı ayırtmak için yazın."},"Kuyumcu":{"s":"Ayar ve gram, tartı sizin gözünüzün önünde yapılır.","o":"Altın alım satımda günlük kuru söyler, tek taş, pırlanta ve alyansı gösterir, takı onarımını atölyemizde yaparız.","u":[["Ayar","Ürünün ayarı test edilip damgası okunur."],["Tartı","Gram sizin önünüzde tartılır."],["Kur","Günlük alış ve satış kuru söylenir."],["Fatura","Ürün ve işçilik ayrı yazılı belge verilir."]],"k":"Günlük kur için arayın."},"Saatçi":{"s":"Saatinizin sorunu pil mi kordon mu, bakınca söyleriz.","o":"Kol saatlerinde marka sorgular, pil ve kordon değişimi ile bakım yapar, hediye için paketleriz.","u":[["Kasa","Saat açılmadan önce kasa ve cam kontrol edilir."],["Mekanizma","Pil, kurma ve su geçirmezlik denenir."],["Kordon","Bilek ölçünüze göre kordon ayarlanır."],["Teslim","Hediye kutusunda paketlenip verilir."]],"k":"Saatinizi getirin, bakalım."},"Çiçekçi":{"s":"Buket, gideceği yere uyan renk ve boyda hazırlanır.","o":"Mevsim buketi, saksı çiçeği, düğün ve nişan çiçeği ile çelengi hazırlar, aynı gün teslimat yaparız.","u":[["Vesile","Doğum günü, nişan ya da taziye olduğu sorulur."],["Çiçek seçimi","Mevsiminde olan çiçekten buket yapılır."],["Not kartı","Mesajınız kartın üzerine yazılır."],["Teslim","Adrese ulaştırılıp size haber verilir."]],"k":"Çiçek siparişi için yazın."},"Hediyelik eşya":{"s":"Kime alacağınızı söyleyin, uygun hediyeyi birlikte bulalım.","o":"Kişiye özel hediyeler, doğum günü seçkisi ve kurumsal hediye hazırlar, paketleyip şehir içinde adrese teslim ederiz.","u":[["Alıcı","Kime ve hangi vesileyle alındığı konuşulur."],["Seçki","Bütçenize uyan birkaç ürün gösterilir."],["Kişiselleştirme","İsim ya da not baskısı hazırlanır."],["Paket","Kutu ve kurdele seçilip teslim edilir."]],"k":"Hediyenizi birlikte seçelim."},"Kırtasiye":{"s":"Okul listesini getirin, kalem defter tek seferde toplansın.","o":"Okul listesi hazırlama, fotokopi ve çıktı, kitap kaplama ve ofis malzemelerini aynı tezgâhta yaparız.","u":[["Liste","Okulun verdiği malzeme listesi okunur."],["Toplama","Marka tercihinize göre ürünler ayrılır."],["Kaplama","Kitap ve defterler kaplanıp etiketlenir."],["Çıktı","Fotokopi ve baskılar isteğe göre hazırlanır."]],"k":"Listenizle uğrayın."},"Kitapçı":{"s":"Aradığınız kitap rafta yoksa sipariş verip haber veririz.","o":"Roman, çocuk kitapları ve sınav kitaplarında okul listesine göre seçim yapar, sipariş kitabı yayınevinden getirtiriz.","u":[["Kitap","Yazar, ad ya da yayınevi sorulur."],["Raf","Stokta yoksa sipariş kaydı açılır."],["Haber","Kitap gelince telefonla bilgi verilir."],["Öneri","Okuma yaşına göre benzer kitaplar gösterilir."]],"k":"Kitap adını bize söyleyin."},"Oyuncakçı":{"s":"Oyuncağın çocuğun yaşına uygunluğuna kutuyu açmadan bakılır.","o":"Yaşa göre oyuncak ve eğitici oyunları ayırır, peluş ve figür stoğunu sorgular, hediye paketini hazırlarız.","u":[["Yaş","Çocuğun yaşı ve ilgisi sorulur."],["Güvenlik","Küçük parça uyarısı ve yaş etiketi okunur."],["Stok","İstenen figür ya da oyun stokta aranır."],["Paket","Hediye kâğıdıyla paketlenir."]],"k":"Yaşı söyleyin, oyuncağı bulalım."},"Spor mağazası":{"s":"Ayakkabıyı koşacağınız zemine göre seçeriz.","o":"Spor ayakkabı, kıyafet ve fitness ekipmanında kullanımınıza göre öneri yapar, kulüp formalarında beden ve stok sorarız.","u":[["Branş","Koşu, salon ya da saha olduğu sorulur."],["Ayak","Taban yapısı ve numara birlikte bakılır."],["Stok","Forma ve ekipmanın bedeni sorgulanır."],["Deneme","Mağazada yürüyerek denenir."]],"k":"Branşınızı söyleyin, bakalım."},"Elektronik mağazası":{"s":"Taksit tablosunu telefonu elinize almadan önce görürsünüz.","o":"Telefon, bilgisayar, televizyon ve küçük ev aletlerinde ihtiyacınıza göre seçim yapar, taksit seçeneklerini yazılı gösteririz.","u":[["İhtiyaç","Cihazı ne için kullanacağınız sorulur."],["Karşılaştırma","Raftaki iki üç model yan yana konur."],["Taksit","Banka ve vade seçenekleri yazılı gösterilir."],["Kurulum","Cihaz kutudan çıkarılıp açılışı denenir."]],"k":"Taksit seçenekleri için uğrayın."},"Telefoncu":{"s":"İkinci el telefonun geçmişi, almadan önce kontrol edilir.","o":"Sıfır ve ikinci el telefon satar, aksesuar ve ekran koruyucu takar, hat işlemlerini mağazada yaparız.","u":[["IMEI","Telefonun IMEI kaydı sorgulanır."],["Kontrol","Ekran, batarya ve kamera denenir."],["Aksesuar","Modele uygun kılıf ve koruyucu seçilir."],["Hat","Numara taşıma ve hat tanımı yapılır."]],"k":"Telefonunuzu getirip bakalım."},"Beyaz eşya bayi":{"s":"Eski buzdolabınız çıkar, yenisi mutfağa yerleşir.","o":"Buzdolabı, çamaşır ve bulaşık makinesinde nişe göre seçim yapar, taksit, montaj ve eski ürün alımını tek seferde yaparız.","u":[["Ölçü","Nişin ve kapı genişliği not edilir."],["Model","Enerji sınıfı ve hacim birlikte seçilir."],["Taksit","Vade seçenekleri yazılı verilir."],["Montaj","Cihaz bağlanır, eski ürün alınır."]],"k":"Ölçünüzle gelin, seçelim."},"Mobilya mağazası":{"s":"Koltuk salona sığar mı, teslimattan önce ölçülür.","o":"Koltuk takımı, yatak odası ve yemek odasında ölçüye özel üretim yapar, teslimat ve montajı kendimiz üstleniriz.","u":[["Ölçü","Salon, kapı ve merdiven genişliği alınır."],["Kumaş","Döşeme ve renk numuneyle seçilir."],["Üretim","Ölçüye özel parça atölyede hazırlanır."],["Montaj","Teslimatta parçalar yerinde kurulur."]],"k":"Salonunuzun ölçüsünü getirin."},"Ev tekstili":{"s":"Perde, pencereniz ölçüldükten sonra dikilir.","o":"Perde, nevresim ve havluda yerinde ölçü alır, kumaşı dikime verir, takarak teslim ederiz.","u":[["Ölçü","Korniş ve pencere eni yerinde ölçülür."],["Kumaş","Pile oranına göre metraj hesaplanır."],["Dikim","Boy ve pile atölyede dikilir."],["Asma","Perde takılır, boyu yerinde kontrol edilir."]],"k":"Yerinde ölçü için çağırın."},"Halı mağazası":{"s":"Halıyı evinize götürüp zeminde denemenize izin veririz.","o":"Makine halısı, yolluk ve kilimde ölçüye özel kesim yapar, halıyı eve teslim ederiz.","u":[["Ölçü","Oda ve koridor boyu ölçülür."],["Desen","Mobilya rengine uyan desenler serilir."],["Kesim","Yolluk ya da halı istenen boyda kesilir."],["Serim","Halı serilip kenar overloğu kontrol edilir."]],"k":"Odanızın ölçüsüyle gelin."},"Züccaciye":{"s":"Çeyiz listesi, mutfağınızın düzenine göre çıkarılır.","o":"Tencere, tava, yemek takımı ve cam ürünlerde çeyiz paketi hazırlar, küçük ev aletlerini bir arada sunarız.","u":[["Liste","Kaç kişilik sofra kurulduğu sorulur."],["Ocak","Ocak türüne uygun tencere seçilir."],["Takım","Tabak ve bardak takımı sofrada eşlenir."],["Paket","Kırılacaklar sarılıp kutulanır."]],"k":"Çeyiz listesi için uğrayın."},"Hırdavat":{"s":"Elinizdeki eski vidayı getirin, aynısını bulalım.","o":"Vida, bağlantı, el aleti, elektrik ve tesisat malzemesini ihtiyacınıza göre ayırır, boya ve fırça önerisi yaparız.","u":[["Numune","Eski parça ya da fotoğrafı incelenir."],["Ölçü","Vida boyu, diş ve çapı ölçülür."],["Uyum","Priz, rakor ya da conta eşleştirilir."],["Adet","Gereken sayı kadar tek tek verilir."]],"k":"Parçayı getirin, eşleştirelim."},"Boya bayi":{"s":"Duvardaki rengi getirin, aynısını karıştırıp çıkaralım.","o":"İç ve dış cephe boyalarında renk karışımı yapar, duvar metrajına göre boya miktarını hesaplar, fırça ve rulo seçtiririz.","u":[["Metraj","Duvar eni, boyu ve kat sayısı alınır."],["Renk","Numuneden bilgisayarlı karışım hazırlanır."],["Deneme","Küçük kutuyla duvarda renk denenir."],["Malzeme","Rulo, fırça ve astar tamamlanır."]],"k":"Metrajınızı söyleyin, hesaplayalım."},"Market":{"s":"Defter yerine kaydınız düzenli tutulur, hesap karışmaz.","o":"Günlük ürün, temel gıda ve temizlik malzemesini eve teslim eder, veresiye defteri yerine düzenli kayıt tutarız.","u":[["Liste","Alışveriş listesi telefonla alınır."],["Toplama","Ürünler son kullanma tarihine bakılarak ayrılır."],["Kayıt","Tutar hesabınıza yazılır."],["Teslim","Poşetler kapıya bırakılır."]],"k":"Siparişinizi telefonla iletin."},"Kasap":{"s":"Kıyma, seçtiğiniz etten gözünüzün önünde çekilir.","o":"Dana kıyma, kuzu pirzola ve kuşbaşını isteğinize göre keser, sucuk ve pastırma sunar, kurban hizmeti veririz.","u":[["Parça","Karkastan istediğiniz kısım gösterilir."],["Kesim","Kemik ve yağ payı sizinle belirlenir."],["Çekim","Kıyma gözünüzün önünde çekilir."],["Paket","Porsiyonlanıp dondurmaya uygun paketlenir."]],"k":"Kesim için uğrayın."},"Manav":{"s":"Domates mevsimindeyse tezgâhta, değilse bunu da söyleriz.","o":"Mevsim sebze ve meyvesi ile yeşilliği sabah tezgâha dizer, eve teslim ve toptan sipariş alırız.","u":[["Tezgâh","Sebze ve meyve sabah toptancıdan gelir."],["Seçim","Olgunluk derecesine sizinle birlikte bakılır."],["Tartı","İstediğiniz miktar kasada tartılır."],["Sipariş","Toptan ya da eve teslim ayrı yazılır."]],"k":"Toptan sipariş için arayın."},"Şarküteri":{"s":"Peyniri tadına bakarak, istediğiniz dilimde alırsınız.","o":"Peynir ve zeytin çeşitlerini tattırır, şarküteri ürünlerini dilimler, hediye sepeti hazırlayıp eve teslim ederiz.","u":[["Tadım","Peynir ve zeytinden küçük parça tattırılır."],["Dilim","Kalınlık isteğinize göre kesilir."],["Sepet","Hediye sepeti bütçenize göre dizilir."],["Teslim","Soğuk zincir bozulmadan eve gider."]],"k":"Tadım için dükkâna uğrayın."},"Kuruyemişçi":{"s":"Kuruyemişi kilo ile alın, isterseniz yarım kilo tartarız.","o":"Kuruyemiş, baharat, bitki çayı ve kuru meyveyi kilo ile satar, çay karışımını ihtiyacınıza göre hazırlarız.","u":[["Çeşit","Çiğ ya da kavrulmuş ayrı gösterilir."],["Karışım","Baharat ve çay karışımı sizinle yapılır."],["Tartı","İstediğiniz miktar taze olarak tartılır."],["Paket","Hava almayan poşette verilir."]],"k":"Tartı için dükkâna uğrayın."},"Tekel bayi":{"s":"Gece geç saatte de soğuk içecek rafta hazırdır.","o":"Soğuk içecek ve atıştırmalıkta tezgâhı gece açık tutar, sigara ve tütün ürünlerini yasal sınırlar içinde satarız.","u":[["Açılış","Dükkân gece de açık tutulur."],["Soğutma","İçecekler dolapta soğutulur."],["Yaş","Alkol ve tütünde kimlik istenir."],["Kasa","Fiş verilip ürünler poşetlenir."]],"k":"Çalışma saatlerimize bakın."},"Zeytinyağı satışı":{"s":"Teneke açılmadan önce yağı tadıp kokusuna bakabilirsiniz.","o":"Natürel sızma zeytinyağını beş litrelik tenekede ve zeytin çeşitleriyle sunar, kargoyla evinize göndeririz.","u":[["Tadım","Yağ küçük bardakta tadılır."],["Kap","Teneke ya da cam şişe seçilir."],["Etiket","Hasat dönemi ve asit değeri okunur."],["Kargo","Teneke koliyle sarılıp gönderilir."]],"k":"Yağ siparişi için yazın."},"Bal satışı":{"s":"Petek balın hangi bölgeden geldiğini söyleriz.","o":"Süzme çiçek balı, petek bal ve çam balını bölgesiyle tanıtır, cam kavanozda kargoyla göndeririz.","u":[["Çeşit","Çiçek, çam ve petek bal ayrılır."],["Tadım","Bal kaşıkla tadılır, kıvamına bakılır."],["Kavanoz","Boyu ve kapağı seçilir."],["Kargo","Kırılmaya karşı sarılı koliyle gönderilir."]],"k":"Bal siparişi için yazın."},"Antikacı":{"s":"Her parçanın geçmişi, alırken dükkânda size anlatılır.","o":"Antika mobilya, eski saat ve eşya alım satımı yapar, koleksiyon sorgulamasında ekspertiz görüşmesi için zaman ayırırız.","u":[["Parça","Eşyanın fotoğrafı ve ölçüsü alınır."],["Ekspertiz","Dönemi ve özgünlüğü birlikte incelenir."],["Değer","Alış ve satış değeri gerekçesiyle konuşulur."],["Kayıt","Parça, geldiği yerle birlikte deftere işlenir."]],"k":"Eşyanızı göstermeye getirin."},"Müzik aleti":{"s":"Gitarın sesi, elinize alıp çalmadan anlaşılmaz.","o":"Gitar, yaylı, piyano ve bağlama satar, tel değişimi ve bakım yapar, ders için öğretmen yönlendiririz.","u":[["Çalma","Aleti dükkânda elinize alıp çalarsınız."],["Akort","Perde, tel ve sap eğriliği kontrol edilir."],["Aksesuar","Kılıf, mızrap ve tel seçilir."],["Ders","Seviyenize göre öğretmen yönlendirilir."]],"k":"Aleti elinize almaya gelin."},"Bisikletçi":{"s":"Lastik patladığında iç lastik rafta, usta tezgâhta.","o":"Şehir ve dağ bisikletlerinde bakım yapar, lastik, iç lastik ve yedek parçayı yerinde değiştiririz.","u":[["Kontrol","Bisiklet sehpaya alınıp tekerlekler çevrilir."],["Fren","Balata ve kablo gerginliği ayarlanır."],["Zincir","Zincir yağlanır, vites geçişi denenir."],["Lastik","Basınç ve iç lastik kontrol edilir."]],"k":"Bakım için bisikletinizi getirin."},"Av malzemeleri":{"s":"Hafta sonu kampına gitmeden çadırı dükkânda kurup bakarız.","o":"Çadır, uyku tulumu, ocak ve kamp giyiminde konfor sıcaklığını sorar, ruhsatlı ürünlerde mevzuat bilgisini veririz.","u":[["Plan","Kaç kişi ve hangi mevsim olduğu sorulur."],["Çadır","Çadır dükkânda kurulup bakılır."],["Uyku","Tulumun konfor sıcaklığı okunur."],["Mevzuat","Ruhsat gerektiren ürünlerde belge anlatılır."]],"k":"Kamp listeniz için uğrayın."},"Gelinlik":{"s":"Gelinliğin size nasıl oturduğu prova günü aynada görülür.","o":"Yeni koleksiyon, kiralama ve kişiye özel dikimde prova randevusu verir, abiye ve damatlık için ölçü alırız.","u":[["Model","Beğendiğiniz kesimler provaya hazırlanır."],["Prova","Randevuda aynada tek tek giyilir."],["Ölçü","Terzi pens ve boyu işaretler."],["Son prova","Düzeltmeler bitince elbise düğüne hazırlanır."]],"k":"Prova randevusu için yazın."},"Kozmetik mağazası":{"s":"Cilt tipinizi söyleyin, ürünü elinizde deneyin.","o":"Cilt bakımı, makyaj ve parfümde cilt tipine göre marka sorgular, tester ile denettirir, hediye paketi hazırlarız.","u":[["Cilt tipi","Kuru, yağlı ya da karma olduğu sorulur."],["Tester","Ürün el üstünde denenir."],["Marka","İstediğiniz markanın stoğu aranır."],["Paket","Hediye kutusu ve kart hazırlanır."]],"k":"Cilt tipinizle uğrayın."},"Tesettür giyim":{"s":"Tunik boyu ve kol uzunluğu, bedeninizle birlikte sorulur.","o":"Yeni sezon tunik, elbise, eşarp ve şalda beden sorgular, seçtiklerinizi rezerve eder, denemeniz için kabin ayırırız.","u":[["Beden","Boy, kol ve kalıp tercihiniz sorulur."],["Kumaş","Astar ve kumaş dokusu elde gösterilir."],["Kombin","Eşarp ile tunik renk uyumuna bakılır."],["Rezerve","Seçtikleriniz kabinde bekletilir."]],"k":"Yeni sezonu görmeye gelin."},"Çocuk giyim":{"s":"Çocuk büyür, kıyafetin büyüme payını birlikte düşünürüz.","o":"Yaşa göre kıyafet, bebek bakım ürünü ve hediye seti sunar, beden sorgulama ve rezerve ile yardımcı oluruz.","u":[["Yaş","Çocuğun yaşı ve boyu sorulur."],["Kumaş","Bebek cildine uygun pamuklu seçilir."],["Beden","Büyüme payı için bir beden büyüğe de bakılır."],["Hediye","Doğum seti hediye kutusuna dizilir."]],"k":"Çocuğunuzun bedenini söyleyin."},"İç giyim":{"s":"Beden ölçüsü alınmadan iç giyim önerilmez.","o":"İç giyim, pijama ve çorapta beden önerisi yapar, beğendiğinizi rezerve eder, kabinde rahatça denemenizi sağlarız.","u":[["Ölçü","Göğüs ve kalça ölçüsü sorulur."],["Kalıp","Kumaş ve kalıp rahatlığı anlatılır."],["Deneme","Kabinde sakin biçimde denenir."],["Rezerve","Seçtiğiniz beden ayrılır."]],"k":"Beden önerisi için uğrayın."},"Gümüşçü":{"s":"Kolye ucuna adınızı yazdırır, isim kolyeyi birlikte tasarlarız.","o":"Gümüş kolye, yüzük, bileklik ve set takıları sunar, kişiye özel isim kolye yapar, takı onarımını yaparız.","u":[["Tasarım","İsim ve yazı karakteri seçilir."],["Gümüş","Ayar damgası ve kaplama sorulur."],["Üretim","Kolye atölyede işlenir."],["Onarım","Kopan zincir ya da yüzük lehimlenir."]],"k":"İsim kolye için yazın."},"Kargo şubesi":{"s":"Paketiniz teslim alınır, takip numaranız hemen verilir.","o":"Gönderiyi şubede kabul eder, kargo takibini yapar, kurumsal gönderi ve şubeden teslim hizmeti veririz.","u":[["Tartı","Paketin ölçüsü ve desisi alınır."],["Adres","Alıcı bilgileri kontrol edilir."],["Takip","Takip numarası size yazılır."],["Teslim","Alıcı şubeden teslim alabilir."]],"k":"Gönderiniz için şubeye uğrayın."},"Nakliyat":{"s":"Asansör kullanılacak mı, kat ve kapı ölçüsünü önce sorarız.","o":"Evden eve nakliyat, asansörlü taşıma ve şehirler arası taşımada eşyayı paketler, ev büyüklüğüne göre araç ve ekip planlarız.","u":[["Keşif","Kat, asansör ve eşya miktarı görülür."],["Paketleme","Cam ve mobilya battaniyeye sarılıp kolilenir."],["Yükleme","Eşyalar araçta sabitlenir."],["Yerleştirme","Mobilya yeni evde odasına konur."]],"k":"Keşif için tarih belirleyin."},"Ofis taşıma":{"s":"Pazartesi sabahı masalarınız yerinde, bilgisayarlar açık olsun.","o":"Ofis taşımada bilişim ekipmanını numaralandırır, hafta sonu taşır, paketleme ve kurulum desteğiyle işi pazartesiye hazırlarız.","u":[["Plan","Masa ve dolap yerleşimi çizilir."],["Etiket","Bilgisayar ve kablolar numaralanır."],["Taşıma","İş yoğunluğunu bölmemek için hafta sonu yapılır."],["Kurulum","Masalar kurulup bilgisayarlar bağlanır."]],"k":"Ofis taşıması için görüşelim."},"Parça eşya taşıma":{"s":"Tek koltuk için koca kamyon çağırmazsınız.","o":"Tek parça eşya, beyaz eşya ve koli taşımayı şehir içinde aynı gün yapar, eşyayı sarıp bağlayarak götürürüz.","u":[["Eşya","Parçanın boyu ve bulunduğu kat not edilir."],["Sarma","Streç ve battaniyeyle sarılır."],["Yükleme","Küçük araçla adresten alınır."],["İndirme","Kapınıza kadar taşınıp bırakılır."]],"k":"Eşyanız için araç çağırın."},"Depolama":{"s":"Eşyanız depoda, kutusunun üstünde adınızla bekler.","o":"Eşya depolama, paketleme ve taşıma hizmetini sigorta bilgisi ve aylık raporlama ile sunarız.","u":[["Envanter","Eşyalar listelenip fotoğraflanır."],["Paketleme","Kolilenir, mobilya örtülür."],["Yerleşim","Kutular size ayrılan bölmeye dizilir."],["Rapor","Aylık durum raporu size gönderilir."]],"k":"Depo için bize ulaşın."},"Kurye":{"s":"Evrak elden ele gider, teslim anı size bildirilir.","o":"Moto kurye ile aynı gün teslim yapar, evrak gönderimini ve kurumsal abonelikleri teslim bildirimiyle sürdürürüz.","u":[["Çağrı","Adres ve paket bilgisi telefonla alınır."],["Alım","Kurye en yakın noktadan yola çıkar."],["Yol","Evrak çantada, ıslanmadan taşınır."],["İmza","Teslim alan imzalar, size haber gider."]],"k":"Kurye çağırmak için arayın."},"Lojistik":{"s":"Yükünüz hangi araçta, hangi noktada, her an sorabilirsiniz.","o":"Parsiyel yükten tam kamyona sevkiyat planlarız. Araç takibi ile yükün nerede olduğunu size bildiririz.","u":[["Yük bilgisi","Palet sayısı, ağırlık ve boşaltma adresini yazarız."],["Araç seçimi","Parsiyel mi tam kamyon mu, hacme göre belirleriz."],["Yükleme","Sevk irsaliyesi düzenlenir, yük araca sayılarak alınır."],["Takip","Aracın konumunu izler, teslimde imzalı irsaliyeyi göndeririz."]],"k":"Yükünüzü sevkiyata hazırlayalım."},"Asansörlü taşıma":{"s":"Eşyanız pencereden iner ya da çıkar, merdivene yük binmez.","o":"Dış cephe asansör ile ev eşyası taşıma yaparız. Kat yüksekliği keşfinde balkon ve cephe önünü yerinde ölçeriz.","u":[["Keşif","Kat yüksekliğini ve asansör kurulacak zemini yerinde görürüz."],["Kurulum","Asansör cepheye kurulur, yol ve kaldırım önlemi alınır."],["Yükleme","Eşyalar sarılır, sepete yerleştirilir ve pencereden indirilir."],["Yerleştirme","Karşı katta eşyalar odalarına bırakılır, asansör toplanır."]],"k":"Taşınacağınız kata keşfe gelelim."},"Vinç kiralama":{"s":"Yükün ağırlığı ve kaldırma yarıçapı belli olmadan vinç seçilmez.","o":"Operatörlü hizmet ile saatlik ya da günlük vinç kiralarız. Şantiye keşfinde zemini ve kaldırma noktasını önceden görürüz.","u":[["Yük bilgisi","Parçanın ağırlığını ve kaldırılacağı yüksekliği öğreniriz."],["Zemin","Vincin basacağı yeri ve kolun yolunu şantiyede kontrol ederiz."],["Kurulum","Ayaklar açılır, takozlanır, yük bağlama işlemi yapılır."],["Kaldırma","Operatör işaretçi eşliğinde yükü yerine indirir."]],"k":"Kaldıracağınız yükü bize bildirin."},"Soğuk zincir":{"s":"Ürün araca girerken ve inerken derecesi kayıt altındadır.","o":"Frigorifik araçla gıda ve ilaç sevkiyatı yaparız. Sıcaklık kaydı her teslimatta karşı tarafa raporlanır.","u":[["Ön soğutma","Araç yükleme öncesi istenen dereceye getirilir."],["Yükleme","Ürün sıcaklığı ölçülür, palet dizilimi hava akışına göre yapılır."],["Yolda kayıt","Sıcaklık kaydedici yol boyunca değerleri saklar."],["Teslim","Kayıt çıktısı irsaliye ile birlikte alıcıya verilir."]],"k":"Sevkiyatınızı sıcaklık kaydıyla planlayalım."},"Pansiyon":{"s":"Kapıdan girdiğinizde ev sahibiyle konuşur, odanızı görerek karar verirsiniz.","o":"Çift kişilik oda ve aile odası olan küçük bir pansiyonuz. Sabah kahvaltısı evde yapılır, aracınız için otopark vardır.","u":[["Rezervasyon","Tarih, kişi sayısı ve oda tipini not alırız."],["Karşılama","Anahtar teslim edilir, oda ve kahvaltı saati gösterilir."],["Konaklama","Kahvaltı sabah servis edilir, aracınız otoparka alınır."],["Çıkış","Oda kontrol edilir, anahtar teslim alınır."]],"k":"Odanızı tarihe göre ayırtın."},"Apart otel":{"s":"Mutfağı olan dairede kendi düzeninizle kalırsınız, otel odasında sıkışmazsınız.","o":"Stüdyo daire ve geniş dairelerle aylık konaklama veririz. Temizlik hizmeti kalış süresine göre planlanır.","u":[["Daire seçimi","Kişi sayısına göre stüdyo ya da geniş daire önerilir."],["Giriş","Envanter listesi birlikte okunur, anahtar teslim edilir."],["Konaklama","Mutfak eşyaları dairede hazırdır, temizlik takvime göre gelir."],["Çıkış","Envanter yeniden sayılır, sayaç değerleri not edilir."]],"k":"Kalacağınız tarihleri bize yazın."},"Villa kiralama":{"s":"Havuzu, bahçesi ve oda düzeniyle villayı eksiksiz anlatırız.","o":"Havuzlu villa ve muhafazakâr villa seçenekleriyle haftalık kiralama yaparız. Havalimanı transferi ve temizlik de ayarlanır.","u":[["Tercih","Havuz tipi, kişi sayısı ve mahremiyet isteğinizi öğreniriz."],["Rezervasyon","Haftalık tarih ayrılır, ödeme koşulları yazılı verilir."],["Karşılama","Havalimanında karşılanır, anahtar ve havuz kuralları anlatılır."],["Teslim","Çıkışta villa kontrol edilir, temizlik yapılır."]],"k":"Villanızın tarihini ayırtın."},"Bungalov":{"s":"Ağaçların arasında, şöminenin başında sabahı sessiz karşılarsınız.","o":"Çift kişilik ve şömineli bungalovlarda kalınır, kahvaltı verilir. İsterseniz çevredeki doğa yürüyüşü rotasını gösteririz.","u":[["Seçim","Şömineli ya da normal bungalovu tarihe göre ayırırız."],["Giriş","Odun, battaniye ve ısıtma kullanımı birlikte gösterilir."],["Doğa yürüyüşü","Çevredeki patikalar ve dönüş saatleri haritadan anlatılır."],["Sabah","Kahvaltı bungalov önüne ya da ortak alana gelir."]],"k":"Doğada bir gecelik yer ayırtın."},"Kamp alanı":{"s":"Çadırı ya da karavanı kuracağınız yer önceden belli olur.","o":"Çadır alanı ve karavan alanında duş ve elektrik bağlantısı veririz. Eksik kalan ekipmanı kiralayabilirsiniz.","u":[["Alan seçimi","Çadır mı karavan mı, parsel ona göre gösterilir."],["Bağlantı","Elektrik direği ve su noktası parselin yanında bulunur."],["Kurulum","Çadır kurulur, ekipman eksiği kiralık listeden tamamlanır."],["Ayrılış","Parsel çöpten arındırılır, elektrik bağlantısı kapatılır."]],"k":"Parselinizi şimdiden ayırtın."},"Hostel":{"s":"Yatağınız, dolabınız ve kilidiniz size ait, oda ortak olsa da.","o":"Karma oda ve kadın odasında yatak ayırır, özel oda da veririz. Ortak mutfakta kendi yemeğinizi yapabilirsiniz.","u":[["Yatak seçimi","Karma oda, kadın odası ya da özel oda ayrılır."],["Dolap","Valiz için kilitli dolap ve yatak numarası verilir."],["Ortak alan","Mutfak ve oturma alanı kuralları girişte anlatılır."],["Çıkış","Dolap boşaltılır, çarşaf toplanır, anahtar bırakılır."]],"k":"Yatağınızı geliş tarihine göre ayırın."},"Tatil köyü":{"s":"Çocuklar kulüpte oynarken anne baba da gerçekten dinlenir.","o":"Her şey dahil oda ve aile odası ile çocuk kulübü sunarız. Havalimanı transferi rezervasyonla birlikte ayarlanır.","u":[["Oda tipi","Aile kaç kişiyse ona göre oda ayrılır."],["Transfer","Uçuş saatinize göre havalimanı aracı ayarlanır."],["Bileklik","Girişte bileklik takılır, restoran ve bar saatleri verilir."],["Kulüp","Çocuklar yaş grubuna göre kulüp etkinliğine katılır."]],"k":"Aile tatilinizi tarihe bağlayalım."},"Oto elektrik":{"s":"Arızayı tahmin etmeyiz, ölçüm cihazıyla bulup size gösteririz.","o":"Elektrik arıza tespiti ile marş, şarj dinamosu ve akü kontrolü yaparız. Gerekirse kablo tesisatını onarırız.","u":[["Belirti","Hangi lamba yanıyor, ne zaman çalışmıyor, sizden dinleriz."],["Ölçüm","Akü gerilimi ve şarj değeri multimetre ile okunur."],["Hat takibi","Kısa devre ya da kopuk hat demet içinde aranır."],["Onarım","Parça değişir, ölçüm tekrarlanır, sökülen parça gösterilir."]],"k":"Arızalı aracı elektrik testine getirin."},"Oto kaporta boya":{"s":"Rengi aracın üzerinde denerek tutturur, yamayı belli etmeyiz.","o":"Lokal boya, tampon onarımı ve boyasız göçük düzeltme yaparız. Hasar büyükse kaporta düzeltmeden komple boyaya gideriz.","u":[["Hasar bakışı","Çizik, göçük ve eski boya kalınlığı kontrol edilir."],["Kaporta","Ezik doğrultulur, macun çekilir, yüzey zımparalanır."],["Renk kodu","Aracın boya kodundan ton hazırlanır, panelde denenir."],["Fırın","Boya sürülür, vernik atılır, panel parlatılarak teslim edilir."]],"k":"Hasarlı paneli yerinde görelim."},"Lastikçi":{"s":"Lastiğin diş derinliğini ve üretim tarihini size gösteririz.","o":"Lastik değişimi, balans ve rot ayarı aynı yerde yapılır. Mevsimlik lastik saklama için depo alanımız var.","u":[["Lastik kontrolü","Diş derinliği, yan duvar ve üretim tarihi bakılır."],["Söküm","Jant sökülür, yeni lastik makinede janta geçirilir."],["Balans","Jant balans makinesine bağlanır, kurşunlar yerleştirilir."],["Rot","Ön düzen ayarlanır, bijonlar tork ile sıkılır."]],"k":"Lastiklerinize bakmaya gelin."},"Oto yıkama":{"s":"Kapı pervazlarını ve koltuk altını da bezle sileriz.","o":"İç dış yıkama, motor temizliği ve koltuk yıkama yaparız. Detaylı iç temizlik ve pasta cila isteğe göre eklenir.","u":[["Araç kontrolü","Çizik, leke ve kirli bölgeler birlikte işaretlenir."],["Ön yıkama","Köpükle kir yumuşatılır, tazyikle çamur giderilir."],["İç temizlik","Süpürge, buhar ve fırça ile döşeme ve plastikler temizlenir."],["Kurulama","Mikrofiber bezle silinir, cam ve lastik parlatılır."]],"k":"Aracınızı yıkamaya bırakın."},"Oto ekspertiz":{"s":"Alacağınız aracın boyalı ve değişen parçalarını raporda tek tek görürsünüz.","o":"Tam ekspertiz raporunda kaporta boya, motor, mekanik ve yol testi bulgularını yazarız. Karar sizin, tespiti biz veririz.","u":[["Boya ölçümü","Her panelin boya kalınlığı cihazla ölçülür."],["Şasi","Direkler, podyum ve şasi uçları değişiklik izi için bakılır."],["Mekanik","Motor, şanzıman, fren ve alt takım kontrol edilir."],["Yol testi","Araç sürülür, sesler not edilir, rapor teslim edilir."]],"k":"Alacağınız aracı ekspertize getirin."},"Oto cam":{"s":"Taş izi küçükken bakılırsa cam değişmeden onarılabilir.","o":"Ön cam ve yan cam değişimi, taş izi tamiri ve cam filmi yaparız. Cam sökümü araca özel yapılır.","u":[["Hasar bakışı","Çatlağın boyu ve yeri onarılabilir mi diye bakılır."],["Söküm","Eski cam kesilir, çerçevedeki yapıştırıcı kalıntısı temizlenir."],["Yapıştırma","Yeni cama astar ve poliüretan yapıştırıcı sürülür."],["Kontrol","Cam yerine oturur, sensör ve silecek çalışması denenir."]],"k":"Camınızı bize gösterin."},"Oto döşeme":{"s":"Koltuğun süngerine ve dikişine bakmadan kumaş seçmeyiz.","o":"Koltuk döşeme, tavan kaplama ve direksiyon kaplama yaparız. Paspas ve taban kaplama için kalıp araçtan çıkarılır.","u":[["Söküm","Koltuk ya da tavan sökülür, eski kaplama açılır."],["Kalıp","Eski kumaştan kalıp alınır, yeni deri ya da kumaşa çizilir."],["Dikiş","Parçalar makinede dikilir, sünger gerekiyorsa yenilenir."],["Giydirme","Kaplama gerdirilip zımbalanır, parça araca geri takılır."]],"k":"Koltuğunuzun kumaşını elinizle seçin."},"Egzoz servisi":{"s":"Egzozdan gelen sesin nereden çıktığını altına bakarak buluruz.","o":"Egzoz tamiri ve susturucu değişimi yaparız, katalizör kontrolü ile emisyon hazırlığını da birlikte ele alırız.","u":[["Dinleme","Motor çalışırken boru hattında kaçak sesi dinlenir."],["Lift","Araç kaldırılır, askı lastikleri ve kaynak yerleri gözden geçirilir."],["Onarım","Çürük boru kesilir, susturucu ya da ek parça kaynaklanır."],["Emisyon","Katalizör ve gaz değeri ölçülür, muayene hazırlığı söylenir."]],"k":"Egzozunuzu liftte birlikte inceleyelim."},"Akü servisi":{"s":"Akü bitti derken sorun dinamoda olabilir, ikisini de ölçeriz.","o":"Akü testi ve değişimi yaparız, yerinde akü takviyesiyle yolda kalanın yanına gideriz. Şarj sistemi kontrolü de yapılır.","u":[["Test","Akü gerilimi ve ilk hareket gücü cihazla okunur."],["Şarj kontrolü","Motor çalışırken dinamonun verdiği gerilim ölçülür."],["Değişim","Kutup başları temizlenir, yeni akü kelepçelenip bağlanır."],["Eski akü","Boşalan akü geri alınır, saat ve kayıtlı ayarlar kontrol edilir."]],"k":"Aküsü bitenin yanına gelelim."},"Motosiklet servisi":{"s":"Motorunuzun zincirine, balatasına ve lastiğine tek tek bakılır.","o":"Periyodik bakım, zincir dişli seti, lastik değişimi ve fren bakımı yaparız. Motor arıza tespitini şikâyetinize göre yürütürüz.","u":[["Dinleme","Sürüşte hissettiğiniz titreşim ve sesi anlatırsınız."],["Zincir fren","Zincir gevşekliği, dişli aşınması ve balata kalınlığı bakılır."],["Yağ filtre","Yağ, yağ filtresi ve hava filtresi yenilenir."],["Deneme","Motor kısa sürüşle denenir, bakım kaydı deftere yazılır."]],"k":"Motorunuzu bakıma getirin."},"Oto klima":{"s":"Klima soğutmuyorsa gaz bitmiş olmayabilir, önce kaçağı ararız.","o":"Klima gazı dolumu ve klima bakımı yaparız. Polen filtresi değişimi ve kompresör onarımı gerekirse ayrıca konuşuruz.","u":[["Basınç","Gaz basıncı manometre ile iki taraftan okunur."],["Kaçak","Boru, kondenser ve bağlantılarda gaz kaçağı aranır."],["Vakum","Sistem boşaltılır, nem çekilir, gaz tartılarak doldurulur."],["Çıkış sıcaklığı","Izgaradan çıkan havanın derecesi termometreyle ölçülür."]],"k":"Kliması soğutmayan aracı getirin."},"Rot balans":{"s":"Direksiyon çekiyor ya da titriyorsa nedenini ölçerek buluruz.","o":"Rot ayarı ve balans ayarı yaparız, lastik değişimi gerekiyorsa aynı yerde halledilir. Alt takım kontrolü de yapılır.","u":[["Alt takım","Rotil, rot başı ve burç boşlukları kontrol edilir."],["Balans","Teker makineye bağlanır, titreşim noktası bulunur."],["Rot","Ön düzen değerleri cihazla üretici ölçüsüne getirilir."],["Yol denemesi","Direksiyonun düz giderken tutuşu kısa sürüşle denenir."]],"k":"Direksiyon çekiyorsa bize uğrayın."},"Oto kuaför":{"s":"Boya katmanını gözeterek pasta ve cila yaparız.","o":"Pasta cila, far parlatma ve boya koruma yaparız. İç detay temizliği ve koltuk temizliği ile iç mekânı da toparlarız.","u":[["Boya ölçümü","Boya kalınlığı bakılır, derin çizikler işaretlenir."],["Pasta","Kaba ve ince pasta ile çizikler yüzeyden alınır."],["Cila","Yüzey cilalanır, far ve plastikler parlatılır."],["Koruma","Boya koruma uygulanır, iç detay temizliği bitirilir."]],"k":"Aracınızın boyasını yerinde görelim."},"Seramik kaplama":{"s":"Seramik çizik üzerine sürülmez, önce boyayı düzeltiriz.","o":"Boya hazırlığı ve pasta sonrası seramik kaplama uygularız. Cam kaplama ve iç yüzey koruma da yapılır.","u":[["Boya yıkama","Kil ile yüzeydeki kir ve demir tozu alınır."],["Pasta","Çizikler düzeltilir, yüzey alkolle yağdan arındırılır."],["Kaplama","Seramik sıvı panel panel sürülür, hemen silinir."],["Kürlenme","Araç tozsuz ortamda bekletilir, yıkama için talimat verilir."]],"k":"Aracınızı kaplama öncesi gösterin."},"Araç kaplama":{"s":"Rengi seçmeden önce folyonun aracınızda nasıl durduğunu görürsünüz.","o":"Tam kaplama, tavan kaplama, krom karartma ve şeffaf koruma filmi uygularız. Her panel kenar kıvrımına kadar sarılır.","u":[["Renk örneği","Folyo numunesi araç üzerinde ışıkta denenir."],["Söküm","Kol, ayna ve çerçeve parçaları gerekirse çıkarılır."],["Sarma","Folyo ısıtılarak panele gerilir, kenarlar kıvrılır."],["Kesim","Fazlalık kesilir, parçalar yerine takılır, yüzey ısıyla sabitlenir."]],"k":"Folyo rengini araç üzerinde görün."},"Motor rektifiye":{"s":"Motor açılmadan arıza söylenmez, ölçü alındıktan sonra konuşuruz.","o":"Motor sökme takma, silindir kapak işleme, krank taşlama ve komple rektifiye yaparız. Ölçüler kayda yazılır.","u":[["Söküm","Motor çıkarılır, parçalar sırayla ve etiketle ayrılır."],["Ölçüm","Silindir çapı, krank muylusu ve kapak düzlüğü mikrometreyle ölçülür."],["İşleme","Silindir honlanır, kapak yüzeyi işlenir, krank taşlanır."],["Montaj","Contalar yenilenir, parçalar tork değerine göre monte edilir."]],"k":"Motoru ölçülmek üzere getirin."},"Şanzıman servisi":{"s":"Vites vururken sarsıntı varsa yağdan başlayıp tek tek ilerleriz.","o":"Şanzıman yağı değişimi, otomatik şanzıman arıza tespiti ve debriyaj seti değişimi yaparız. Onarım gerekirse şanzımanı açarız.","u":[["Sürüş notu","Hangi viteste sarsıldığını ve ne zaman kaydığını dinleriz."],["Yağ","Yağ rengi ve kokusu bakılır, metal tozu aranır."],["Tarama","Arıza kodları okunur, vites geçişleri canlı izlenir."],["Açma","Gerekirse şanzıman sökülür, aşınan parça size gösterilir."]],"k":"Vitesi sarsan aracı getirin."},"Oto anahtar":{"s":"Yedek anahtar kesilir, ardından aracın beynine tanıtılır.","o":"Yedek anahtar kopyalama ve immobilizer programlama yaparız. Kumanda değişimi ve araç kapısı açma işlerine de gideriz.","u":[["Kimlik","Ruhsat ve kişi bilgisi kontrol edilir, araç sahibi doğrulanır."],["Çip","Anahtarın çipi okunur ya da boş çip seçilir."],["Kesim","Anahtar araç koduna göre kesilir."],["Programlama","Cihaz araca bağlanır, anahtar immobilizere tanıtılır, çalıştırma denenir."]],"k":"Yedek anahtarı kaybetmeden yaptırın."},"LPG servisi":{"s":"Tank ve enjektörü motorun hacmine bakarak seçeriz.","o":"LPG montajı ve LPG bakımı yaparız. Enjektör ve regülatör değişimi ile periyodik muayene belgesi işlemlerini yürütürüz.","u":[["Araç uyumu","Motor tipi ve bagaj yerine göre tank seçilir."],["Montaj","Tank, boru ve enjektör hattı araca uygun döşenir."],["Kaçak testi","Bağlantılar köpükle ve cihazla kaçak için kontrol edilir."],["Muayene","Belge hazırlanır, araç muayeneye gitmeye hazır hale gelir."]],"k":"LPG için aracı getirin."},"Pet kuaför":{"s":"Tüyüne, derisine ve huyuna göre acele etmeden bakarız.","o":"Banyo ve kurutma, komple tıraş, tırnak kesimi ve kulak temizliği yaparız. Tüy bakımı cinsine göre seçilir.","u":[["Tüy bakışı","Tüydeki yumak, kene ya da cilt tahrişi kontrol edilir."],["Banyo","Cinsine uygun şampuanla yıkanır, durulanır."],["Kurutma","Fön ve tarakla kurutulur, düğümler dikkatle açılır."],["Tıraş","Tırnak ve kulak bakımı yapılır, istenen kesim uygulanır."]],"k":"Dostunuz için randevu ayırın."},"Köpek eğitimi":{"s":"Köpeğin öğrendiği komutu evdeki herkes aynı şekilde kullanır.","o":"Yavru eğitimi, temel itaat eğitimi ve davranış danışmanlığı veririz. İsterseniz eğitmen eve gelir.","u":[["Tanışma","Köpeğin yaşı, huyu ve sorun davranışı dinlenir."],["Temel komut","Otur, bekle ve gel komutları ödülle öğretilir."],["Tasma","Yürüyüşte tasma ve ses komutu birlikte çalışılır."],["Ev ödevi","Evdeki herkese komutları nasıl kullanacağı gösterilir."]],"k":"Köpeğinizle tanışmaya gelin."},"Hayvan oteli":{"s":"Siz yokken dostunuzun yediği mama ve gezdiği saat size yazılır.","o":"Günlük ve haftalık konaklama veririz, isterseniz servis ayarlarız. Mama takibi ve fotoğraflı günlük bilgi gün sonunda size ulaşır.","u":[["Kayıt","Aşı kartı, mama türü ve alışkanlıkları deftere yazılır."],["Teslim alma","Hayvan odasına alıştırılır, kendi battaniyesi yanına konur."],["Gün içi","Mama saati, gezinti ve oyun not edilir."],["Fotoğraf","Gün sonunda fotoğraf ve kısa bilgi size gönderilir."]],"k":"Tatilde dostunuz bizde kalsın."},"Kumpir":{"s":"Patates fırından çıkar çıkmaz açılır, içi sıcakken doldurulur.","o":"Klasik kumpir ve kaşarlı özel kumpir yaparız, ek malzemeyi siz seçersiniz. Paket servisimiz de var.","u":[["Patates","Büyük patatesler fırında kabuğu çıtır olana kadar pişer."],["Ezme","Patates ortadan açılır, tereyağı ve kaşarla ezilir."],["Malzeme","Mısır, turşu, zeytin gibi seçtiğiniz malzemeler eklenir."],["Paket","Siparişiniz paket servis kutusuna konup kapatılır."]],"k":"Kumpirinize malzemeyi siz seçin."},"Kebapçı":{"s":"Adana acılı, Urfa acısız, siparişte siz söylersiniz.","o":"Adana kebap, Urfa kebap, Beyti ve lahmacun ızgarada hazırlanır. Paket servis için sıcak kalacak şekilde sarılır.","u":[["Kıyma","Kıyma yağ oranına göre yoğrulur, şişe sarılır."],["Mangal","Şişler közde çevrilerek pişirilir."],["Yanlar","Lavaş, soğan ve közlenmiş biber yanına konur."],["Servis","Sıcak sofraya ya da paket kabına verilir."]],"k":"Şişinizi acı oranını söyleyerek isteyin."},"Pideci":{"s":"Pide siparişinizle birlikte açılır, fırından size sıcak gelir.","o":"Kıymalı, kuşbaşılı ve kaşarlı pide ile lahmacun yaparız. Paket servis kutusu pideyi ezmeyecek şekilde hazırlanır.","u":[["Hamur","Hamur sipariş geldikçe oklava ile ince açılır."],["Harç","Kıyma, kuşbaşı ya da kaşar kenarlara kadar yayılır."],["Fırın","Pide kayıkla fırına sürülür, kenarı kızarınca alınır."],["Kesim","Pide dilimlenir, tereyağı sürülür ve sıcak servis edilir."]],"k":"Pideniz fırından size gelsin."},"Pizzacı":{"s":"Hamuru dinlendirir, mevsim malzemesini siparişte üstüne dizeriz.","o":"Margarita, karışık pizza ve mevsim pizza yaparız, çocuklar için çocuk menüsü vardır. Paket servis kutusunda ısısını korur.","u":[["Hamur","Hamur önceden dinlendirilir, siparişte elle açılır."],["Sos","Domates sosu sürülür, peynir ve malzemeler dizilir."],["Fırın","Pizza yüksek ısıda fırınlanır, kenarı kabarınca çıkar."],["Dilim","Dilimlenir, sıcakken masaya ya da kutuya girer."]],"k":"Pizzanızı malzemesini seçerek söyleyin."},"Burger":{"s":"Köfteyi siparişte pişirir, ekmeği ızgarada kızartırız.","o":"Klasik burger, peynirli burger ve duble burgeri patatesle servis ederiz. Paket servis için ayrı kutuda gönderilir.","u":[["Köfte","Köfte topu siparişte ızgaraya ya da tavaya basılır."],["Ekmek","Burger ekmeği yağda kızartılarak hafif çıtırlaştırılır."],["Dizilim","Sos, peynir, marul ve turşu sırayla yerleştirilir."],["Patates","Patates ayrı kutuya konur, burger sarılıp servis edilir."]],"k":"Burgeriniz siparişte ızgaraya girsin."},"Balık restoranı":{"s":"Günün balığını tezgâhta görür, nasıl pişeceğine siz karar verirsiniz.","o":"Günün balığı, deniz mahsulleri ve meze tabağı sunarız. Masa rezervasyonu ve özel gün menüsü için önceden haber verin.","u":[["Tezgâh","Günün balığı tezgâhta gösterilir, gözü ve solungacı bakılır."],["Pişirme","Izgara, tava ya da buğulama seçilir."],["Meze","Balık pişerken soğuk mezeler masaya gelir."],["Kılçık","Balık masada ayrılır, kılçıklarından arındırılıp servis edilir."]],"k":"Masanızı balık gününe ayırtın."},"Meyhane":{"s":"Masa mezeyle kurulur, sohbet acele edilmeden ilerler.","o":"Meze çeşitleri, sıcak başlangıçlar ve balık sunarız. Fasıl gecesi için masa rezervasyonu önceden yapılır.","u":[["Meze tepsisi","Soğuk mezeler tepsiyle gösterilir, masaya siz seçersiniz."],["Sıcaklar","Sıcak başlangıçlar soğuk mezelerin ardından çıkar."],["Balık","Ana yemek olarak balık masa temposuna göre pişer."],["Fasıl","Fasıl ekibi gelince masalar arasında çalmaya başlar."]],"k":"Fasıl gecesi için masa ayırtın."},"Çiğ köfteci":{"s":"Çiğ köfte yoğrulurken acısını siz söylersiniz.","o":"Dürüm, porsiyon ve kilo çiğ köfte hazırlarız. Paket servis için marul, nar ekşisi ve limon ayrı gelir.","u":[["Yoğurma","Bulgur, isot ve salça elle uzun süre yoğrulur."],["Acı","Acı oranı sipariş sırasında sorulur."],["Sarma","Lavaşa marul ve nar ekşisiyle sıkıca sarılır."],["Paket","Porsiyon ve kilo siparişi marul, limon ile ayrı kapta gider."]],"k":"Acı oranını söyleyin, sararız."},"Dönerci":{"s":"Döner şişten kesilir kesilmez tabağınıza ve dürümünüze girer.","o":"Et döner ve tavuk döner porsiyon, dürüm ve İskender yaparız. Paket servis ayrı kutuda sosuyla birlikte gider.","u":[["Şiş","Dönerin dış yüzü ocak karşısında kızarır."],["Dilim","Usta dönerden ince ince keser, tabağa ya da lavaşa koyar."],["Yanlar","Pilav, domates ve biber porsiyonun yanına eklenir."],["İskender","İskender pide üstüne tereyağı ve domates sosuyla gelir."]],"k":"Döneri porsiyon ya da dürüm seçin."},"Kahvaltı salonu":{"s":"Serpme kahvaltıda masa boşaldıkça tabaklar yenilenir.","o":"Serpme kahvaltı, kahvaltı tabağı ve menemen sunarız. Kalabalık sofra için masa rezervasyonu almak daha rahat olur.","u":[["Masa","Kaç kişi geleceğiniz ve saatiniz için masa ayrılır."],["Çay","Demlik gelir, çay bardağı boşaldıkça tazelenir."],["Serpme","Peynir, zeytin, reçel ve yumurtalar küçük tabaklarla dizilir."],["Menemen","Menemen tavada pişince soğumadan masaya getirilir."]],"k":"Kahvaltı masanızı ayırtın."},"Ev yemekleri":{"s":"Günün menüsünü sabah yazarız, tencereden çıkan yemeği size veririz.","o":"Günün menüsünde tencere yemekleri ve sebze yemekleri bulunur. Haftalık abonelik ve paket servis ile eve ya da işyerine gönderilir.","u":[["Menü","Günün menüsü sabah duyurulur, çorba ve ana yemek bellidir."],["Tencere","Yemekler tencerede pişer, sebzeler ayrı hazırlanır."],["Porsiyon","Porsiyon kaplara bölünür, pilav ve salata eklenir."],["Abonelik","Haftalık abonelerin yemekleri günlük teslim edilir."]],"k":"Bu haftanın menüsüne abone olun."},"Catering":{"s":"Davetli sayısı ve mekân belli olunca menüyü kurarız.","o":"Toplantı ikramı, düğün yemeği, kokteyl menüsü ve şirket yemeği hazırlarız. Servis ekipmanı etkinlik yerine gelir.","u":[["Davetli","Kişi sayısı, mekân ve yemek saati netleştirilir."],["Menü","Etkinliğe göre menü kurulur, diyet isteyenler not edilir."],["Hazırlık","Yemekler mutfakta pişer, servis kapları ve ısıtıcılar yüklenir."],["Servis","Ekip yerinde sofrayı kurar, servis sonrası masaları toplar."]],"k":"Etkinliğiniz için menü kuralım."},"Mantı evi":{"s":"Mantının hamuru açılır, içi doldurulur, sarımsaklı yoğurdu yanında gelir.","o":"Kayseri mantısı ve fırın mantı yaparız, çiğ mantı da alabilirsiniz. Paket servis için yoğurt ve sos ayrı kapta gelir.","u":[["Hamur","Hamur ince açılır, küçük karelere kesilir."],["İç","Kıymalı harç her karenin ortasına konur."],["Kapatma","Kareler elle kapatılır, haşlanır ya da fırında kızartılır."],["Sos","Sarımsaklı yoğurt, tereyağlı salça ve nane eklenir."]],"k":"Mantınızı sıcak ya da çiğ alın."},"Köfteci":{"s":"Köfteyi ızgarada çevirir, piyazı yanına ayrı koyarız.","o":"Izgara köfte, köfte ekmek ve piyaz sunarız. Paket servis için köfte sıcak, piyaz ayrı kapta hazırlanır.","u":[["Köfte","Kıyma baharatla yoğrulur, elle şekil verilir."],["Izgara","Köfteler iki yüzü de eşit pişecek şekilde çevrilir."],["Piyaz","Fasulye, soğan ve yumurta limonlu sosla harmanlanır."],["Ekmek","Köfte ekmeğe doldurulur ya da piyazla tabağa alınır."]],"k":"Köfte ekmeğinizi ızgaradan alın."},"Sushi":{"s":"Pirinç ve balık tabağa gelmeden hemen önce hazırlanır.","o":"Maki seti, nigiri seti ve karma tabak hazırlarız. Paket servis soya sosu ve wasabi ile birlikte gönderilir.","u":[["Pirinç","Sushi pirinci pişer, sirke ile tatlandırılıp soğutulur."],["Balık","Balık soğuk hazırda tutulur ve ince dilimlenir."],["Sarma","Makiler bambu hasırla sarılır, nigiriler elde şekillenir."],["Tabak","Soya sosu, zencefil ve wasabi yanına konur."]],"k":"Sushi setinizi seçin."},"Vegan restoran":{"s":"Tabağın içinde ne olduğunu, sosuna kadar açık söyleriz.","o":"Günün vegan tabağı, vegan burger ve tatlı sunarız. Glutensiz seçeneklerde malzemeler ayrıca belirtilir.","u":[["İçerik","Her yemeğin malzeme listesi menüde yazılır."],["Seçim","Vegan ya da glutensiz isteğiniz siparişte not edilir."],["Hazırlık","Tabak yumurta ve süt ürünü katılmadan hazırlanır."],["Servis","Yemek tabağa konur, sos yanında sorulur."]],"k":"Vegan tabağınızı seçin."},"Paket servis":{"s":"Günün menüsü sabah yazılır, toplu siparişte porsiyon sayısı baştan konuşulur.","o":"Günün menüsü, öğrenci menüsü ve toplu sipariş hazırlarız. Şirketlere abonelik ile her gün aynı saatte yemek ulaştırılır.","u":[["Menü","Günün menüsü sabah paylaşılır, öğrenci menüsü ayrı yazılır."],["Sipariş","Toplu siparişte kişi sayısı ve teslim saati alınır."],["Paketleme","Yemekler ısıyı koruyan kaplara bölünür, etiketlenir."],["Teslim","Kurye adrese gider, abonelikte her gün aynı saatte uğrar."]],"k":"Ofisiniz için abonelik açalım."},"Kokoreççi":{"s":"Kokoreç ocakta kıvrılır, yarım mı çeyrek mi dilediğiniz kadar kesilir.","o":"Yarım kokoreç, çeyrek kokoreç ve midye hazırlarız. Paket servis için ekmek ve baharat ayrı konur.","u":[["Ocak","Kokoreç çevrilerek ateşin karşısında pişer."],["Doğrama","Usta kokoreci ince ince doğrar, domates ve biber ekler."],["Baharat","Kekik, pul biber ve tuz damak zevkine göre eklenir."],["Ekmek","Doğranan kokoreç ekmeğe doldurulur, istenirse tabağa alınır."]],"k":"Kokoreçte porsiyonu siz seçin."},"Lahmacun salonu":{"s":"Lahmacun ince açılır, limon ve maydanozla sarılıp yenir.","o":"Lahmacun ve fındık lahmacun yaparız, yanına ayran koyarız. Paket servis lahmacunları birbirine yapışmadan sarılır.","u":[["Hamur","Hamur ince ince açılır, tepsiye serilir."],["Harç","Kıymalı harç eşit şekilde sürülür."],["Fırın","Lahmacun fırında kenarı kızarınca çıkarılır."],["Sunum","Limon, maydanoz ve soğan yanında, ayran soğuk gelir."]],"k":"Lahmacunu limonlu sarıp yiyin."},"Steakhouse":{"s":"Etin cinsi ve pişme derecesi tabaktan önce size sorulur.","o":"Antrikot, dana bonfile ve burger sunarız. Masa rezervasyonu ve özel gün menüsü için önceden haber vermeniz yeterli.","u":[["Et seçimi","Antrikot ya da bonfile, gramaja göre gösterilir."],["Pişirme","Az pişmiş, orta ya da iyi pişmiş tercihiniz alınır."],["Dinlendirme","Et ızgaradan alınır, kesilmeden önce kısa süre dinlendirilir."],["Servis","Yanında patates ve sos servis edilir."]],"k":"Etinizin pişme derecesini seçin."},"Ocakbaşı":{"s":"Şişiniz ocakta, karşınızda çevrilir ve siz izlerken pişer.","o":"Karışık ızgara, kuzu şiş ve mezeler sunarız. Masa rezervasyonunda ocak başında oturmak istediğinizi söyleyebilirsiniz.","u":[["Masa","Ocak başı ya da salon masası tercih edilir."],["Meze","Mezeler ve közlenmiş sebzeler önden gelir."],["Şiş","Kuzu şiş ve karışık ızgara ocakta size bakarak pişer."],["Servis","Pide ve soğan salatası eşliğinde servis edilir."]],"k":"Ocak başında yerinizi ayırın."},"Laboratuvar":{"s":"Tahlil için hazırlanmanız gereken noktaları önceden size bildiririz.","o":"Kan tahlili, hormon testleri ve check-up paketleri için numune alırız. Evden numune alma ve sonuçlar için dijital rapor seçeneği vardır.","u":[["Hazırlık","Teste göre açlık gibi hazırlık bilgisi verilir."],["Numune","Kan ilgili tüpe alınır ve adınıza etiketlenir."],["Analiz","Numune cihazda çalışılır, sonuç kayıt altına geçer."],["Rapor","Sonuç dijital rapor olarak iletilir, yorum hekime aittir."]],"k":"Tahlil süreci için bize yazın."},"Görüntüleme merkezi":{"s":"Çekim öncesi hazırlığı ve çekim sırasını önceden anlatırız.","o":"MR, tomografi, ultrason ve röntgen çekimleri yapılır. Sonuçlar için dijital rapor hazırlanır.","u":[["İstem","Hekimin yazdığı tetkik istemi kayıt altına alınır."],["Hazırlık","Metal eşya çıkarılır, çekime uygun hazırlık anlatılır."],["Çekim","Teknisyen cihaz başında işlemi anlatır ve çekimi yapar."],["Rapor","Görüntüler radyolog tarafından raporlanır, dijital olarak iletilir."]],"k":"Çekim hazırlığı için bize danışın."},"Eczane":{"s":"Reçetenizdeki ilacı, kullanım şekliyle birlikte anlatarak veririz.","o":"Reçeteli ilaçlar, dermokozmetik ürünler ve vitamin takviyeleri bulunur. Tansiyon ölçümü yapılır, nöbet bilgisi paylaşılır.","u":[["Reçete","Reçeteniz kontrol edilir, ilaçlar tek tek ayrılır."],["Kullanım","Eczacı ilacın kullanım şeklini ve saatini anlatır."],["Ölçüm","İsterseniz tansiyon ölçümü yapılır, değer size söylenir."],["Nöbet","Nöbetçi eczane bilgisi sorulunca paylaşılır."]],"k":"Reçetenizle birlikte uğrayın."},"Optik":{"s":"Numara reçeteden, çerçeve yüzünüzün ölçüsünden gelir.","o":"Numaralı gözlük, güneş gözlüğü, lens ve çocuk gözlükleri bulunur. Çerçeve ayarı ve onarım için uğrayabilirsiniz.","u":[["Reçete","Göz muayenesinden gelen numara kayıt altına alınır."],["Çerçeve","Yüz ölçünüze ve kullanım alışkanlığınıza göre çerçeve denenir."],["Cam","Cam numaraya ve çerçeveye göre kesilip yerleştirilir."],["Ayar","Gözlük burun ve kulak üstünde rahat oturana kadar ayarlanır."]],"k":"Gözlüğünüzü ayarlatmaya gelin."},"İşitme cihazı":{"s":"Cihaz, test sonucuna göre ve kulakta denenerek seçilir.","o":"Duyma testi, cihaz denemesi ve kulak içi cihaz seçenekleri sunarız. Pil ve bakım ile ayar kontrolü de yapılır.","u":[["Duyma testi","Odyometri odasında testle duyma düzeyi ölçülür."],["Cihaz seçimi","Test sonucuna ve kulak yapısına göre cihaz önerilir."],["Deneme","Cihaz kulakta denenir, sesler ve rahatlık sorulur."],["Ayar","Kullanım sonrası ayar kontrolü yapılır, pil ve bakım anlatılır."]],"k":"Duyma testi için randevu isteyin."},"Yoga eğitimi":{"s":"Nefesinize ve bedeninize uygun seviyede başlarsınız.","o":"Grup yoga ve özel ders veririz. Hamile yogası ile eğitmenlik programı için ayrı gruplar açılır.","u":[["Tanışma","Sağlık durumunuz ve yoga deneyiminiz ders öncesi sorulur."],["Nefes","Dersin başında nefes ve ısınma çalışılır."],["Duruş","Asanalar mat üzerinde tek tek anlatılır, gerekirse blokla desteklenir."],["Gevşeme","Ders yatarak gevşeme ile kapanır."]],"k":"Matınızı alın, ilk derse gelin."},"Pilates stüdyosu":{"s":"Aleti kullanmadan önce duruşunuz ve nefesiniz üzerinde çalışırız.","o":"Mat pilates ve aletli pilates dersleri veririz. Özel ders ve hamile pilatesi için eğitmen programı ayrı kurar.","u":[["Duruş","Omurga ve omuz duruşunuz ders öncesi izlenir."],["Mat","Mat üzerinde nefes ve merkez kasları çalışılır."],["Aletler","Reformer ve yay dirençleri ayarlanarak kullanılır."],["Esneme","Ders yavaş esneme hareketleriyle kapanır."]],"k":"İlk dersinizi birlikte planlayalım."},"Crossfit":{"s":"Ağırlığı kendi seviyenize göre ölçeklendirir, başlangıçta zorlamayız.","o":"Başlangıç programı, aylık üyelik ve kişisel koçluk sunarız. Yarışma hazırlığı için ayrı program kurulur.","u":[["Başlangıç","Hareketler boş çubukla öğretilir, ağırlık sonra gelir."],["Isınma","Ders ısınma ve hareket tekniği ile açılır."],["WOD","Günün antrenmanı koç eşliğinde seviyenize ölçeklenir."],["Soğuma","Esneme yapılır, dereceler tahtaya yazılır."]],"k":"Salona ilk dersiniz için gelin."},"Kişisel antrenör":{"s":"Program hedefinize, geçmiş yaralanmalarınıza ve boş saatinize göre yazılır.","o":"Ön değerlendirme ile başlar, birebir antrenman ve online program ile sürer. Beslenme yönlendirmesi genel bilgi düzeyinde verilir.","u":[["Ölçüm","Boy, kilo, esneklik ve hareket kalıbınız değerlendirilir."],["Hedef","Hedefiniz ve haftalık boş günleriniz not edilir."],["Program","Hareket ve set planı kâğıda ya da uygulamaya yazılır."],["Takip","Her antrenmanda ağırlık ve tekrar kaydedilir, program güncellenir."]],"k":"Hedefinizi yazın, programı kuralım."},"Dövüş sanatları":{"s":"Çocuklara önce saygıyı ve düşmeyi, sonra vuruşu öğretiriz.","o":"Çocuk grubu ve yetişkin grubu dersleri yapılır, özel ders de alınabilir. Kuşak sınavı dönem sonunda yapılır.","u":[["Selam","Dersler selamla başlar, kurallar ve saygı anlatılır."],["Temel","Duruş, düşme ve tekme çalışılır."],["Eşli çalışma","Eşle kontrollü teknik tekrarlanır."],["Kuşak","Hazır olanlar kuşak sınavına alınır."]],"k":"Çocuğunuzu deneme dersine getirin."},"Boks salonu":{"s":"İlk derslerde yumruktan önce ayak oyunu ve duruş öğretilir.","o":"Grup boks ve özel ders veririz, kondisyon programı ile ekipmanı salonda bulursunuz.","u":[["Bandaj","Eller bandajlanır, eldiven boyuna göre seçilir."],["Duruş","Ayak yerleşimi ve guard pozisyonu çalışılır."],["Torba","Yumruk kombinasyonları torba üzerinde tekrarlanır."],["Kondisyon","Ders ip atlama ve karın hareketleriyle kapanır."]],"k":"İlk dersiniz için salona uğrayın."},"Tenis kulübü":{"s":"Kort saatinizi önceden ayırırsınız, sırada beklemezsiniz.","o":"Kort kiralama ve üyelik sunarız, çocuk tenis okulu ile özel ders de vardır.","u":[["Kort","Saat ve kort yüzeyi seçilir, rezervasyon yazılır."],["Isınma","Raket ve top ile oyun öncesi ısınma yapılır."],["Ders","Eğitmen vuruş tekniğini tek tek düzeltir."],["Maç","Kalan sürede maç oynanır, çıkışta kort süpürülür."]],"k":"Kort saatinizi ayırtın."},"Halı saha":{"s":"Saatiniz ayrılınca kaleler, ışık ve soyunma odası hazır olur.","o":"Saat kiralama, hafta sonu kiralama, abonelik ve lig organizasyonu yaparız. Takım kaptanı tek aramayla yer ayırır.","u":[["Takım","Kaç kişilik takım geleceği ve saat bildirilir."],["Saha","Zemin, kale ve ışık maçtan önce kontrol edilir."],["Maç","Maç oynanır, yelekler ve toplar sahada hazırdır."],["Hesap","Çıkışta saat ücreti takım arasında bölüşülür."]],"k":"Takımınızla saat ayırtın."},"Yüzme havuzu":{"s":"Çocuk kursunda su derinliğini çocuğun boyuna göre seçeriz.","o":"Tek giriş ve aylık üyelik sunarız, çocuk kursu ile özel ders de verilir.","u":[["Giriş","Duş alınır, bone takılır, kulvar kuralları anlatılır."],["Kulvar","Hızınıza göre yavaş ya da tempolu kulvar seçilir."],["Ders","Eğitmen nefes, kulaç ve bacak çalışmasını suda gösterir."],["Çıkış","Duş alınır, havuz sonrası saç kurutma alanına geçilir."]],"k":"Havuza ilk girişinizi planlayın."},"Binicilik":{"s":"Ata binmeden önce atı tanımayı ve yaklaşmayı öğrenirsiniz.","o":"Başlangıç dersi ve çocuk binicilik veririz, at bakım programı ile doğa binişi de yapılır.","u":[["At tanışma","Ata yaklaşma, dokunma ve yem verme anlatılır."],["Bakım","At fırçalanır, toynak temizlenir, eyer ve gem takılır."],["Biniş","Eğitmen yedekte tutarak ilk adımları öğretir."],["Dönüş","At soğutulur, suyu verilir ve ahıra bırakılır."]],"k":"Ata ilk kez bineceğinizi söyleyin."},"Golf":{"s":"İlk dersinizde sahaya çıkmaz, önce vuruşu pratik sahasında öğrenirsiniz.","o":"Başlangıç dersi, saha kullanımı ve üyelik sunarız. Ekipman kiralama ile sopa almadan başlayabilirsiniz.","u":[["Tutuş","Sopanın tutuşu ve duruş ayna karşısında gösterilir."],["Vuruş","Pratik sahasında top vuruşları tekrarlanır."],["Saha","Hazır olunca sahaya çıkılır, etiket kuralları anlatılır."],["Skor","Delikler kayıt tutularak oynanır."]],"k":"Sopayı kiralayıp ilk vuruşa başlayın."},"Dans stüdyosu":{"s":"Düğün dansı için adımlar müziğe göre tek tek kurulur.","o":"Salsa, bale, düğün dansı ve özel ders sunarız. Çiftler için düğün dansı koreografisi birlikte kurulur.","u":[["Ritim","Müziğin ritmi önce el çırparak çalışılır."],["Temel adım","Temel adımlar aynada yavaşça tekrarlanır."],["Eşli figür","Salsada eş değiştirerek figürler çalışılır."],["Koreografi","Küçük bir koreografi bütünlenir, ders kapanır."]],"k":"Düğün dansınızı çalışmaya başlayın."},"Basketbol okulu":{"s":"Çocuğunuz topla tanışsın, yaşına uygun grupta ilerlesin.","o":"Yaş grubuna göre antrenman yapar, kamp programı kurarız. Deneme antrenmanında çocuk salonu ve hocayı görür, sonra karar verirsiniz.","u":[["Deneme","İlk antrenmana gelir, topla ve salonla tanışır."],["Seviye","Hoca boy, yaş ve top kontrolüne bakıp grup belirler."],["Grup","Yaşıtlarıyla haftalık antrenman programına başlar."],["Kamp","Yaz ve ara tatilde kamp programına katılabilir."]],"k":"Çocuğunuz bir antrenmanı deneyebilir."},"Temizlik şirketi":{"s":"Hangi gün kimin geleceğini önceden bilirsiniz.","o":"Ofis, ev ve inşaat sonrası temizliği yaparız. Aylık sözleşmede temizlik günleri ve kapsam baştan yazılı olur.","u":[["Keşif","Metrekareyi ve temizlenecek alanları yerinde görürüz."],["Kapsam","Hangi oda, hangi gün, yazılı listeye geçer."],["Malzeme","Yüzeye göre ürün ve ekipman seçilir."],["Kontrol","Bitişte alanı sizinle birlikte gezeriz."]],"k":"Temizlik günlerinizi birlikte belirleyelim."},"Ev temizliği":{"s":"Aynı kişiler aynı evi tanır, her hafta yeniden anlatmazsınız.","o":"İki artı bir ve üç artı bir dairelerde, boş evde ve haftalık planla temizlik yaparız. İsterseniz koltuk yıkama eklenir.","u":[["Oda sayısı","Dairenin büyüklüğünü ve oda sayısını sorarız."],["Öncelik","Mutfak, banyo, cam gibi sizin için önemli yerleri alırız."],["Temizlik","Üstten alta, kuru işten ıslak işe sırayla çalışırız."],["Haftalık","Gün ve saat sabitlenir, plan tekrar eder."]],"k":"Evinizin haftalık gününü belirleyelim."},"Ofis temizliği":{"s":"Siz sabah gelmeden masalar, halılar ve camlar hazır olur.","o":"Günlük ofis temizliği, haftalık plan, halı yıkama ve cam silme yaparız. Aylık sözleşmede mesai dışı saatler yazılır.","u":[["Mesai","Çalışma saatinizi öğrenir, temizliği mesai dışına yerleştiririz."],["Alanlar","Masa, mutfak, tuvalet ve ortak alanlar listelenir."],["Anahtar","Girişi ve alarmı nasıl yöneteceğimizi yazarız."],["Rapor","Haftalık plan ve yapılan işler not edilir."]],"k":"Ofisiniz için temizlik planı çıkaralım."},"Koltuk yıkama":{"s":"Koltuğunuz yerinde yıkanır, kumaşına göre ürün seçilir.","o":"Üçlü, ikili, tekli takım, köşe koltuk, yatak ve araç koltuğu yıkarız. Önce kumaşı deneriz, sonra yıkamaya geçeriz.","u":[["Kumaş","Etiketine ve rengine bakıp küçük bir yerde deneriz."],["Leke","İnatçı lekeleri ayrı ürünle önceden işleriz."],["Yıkama","Köpük verip çekme makinesiyle suyu alırız."],["Kuruma","Kuruma süresini ve ne zaman oturacağınızı söyleriz."]],"k":"Koltuğunuzun kumaşını birlikte inceleyelim."},"Cam silme":{"s":"Camı silerken çerçeveye ve silikona da dikkat ederiz.","o":"Daire camlarını, dış cephe camını ve mağaza vitrinini siler, aylık plan kurarız. Yüksekte iş güvenliği önlemiyle çalışırız.","u":[["Yükseklik","Katı ve erişim yolunu görüp ekipmanı seçeriz."],["Ön yıkama","Toz ve kuş pisliğini önce çözeriz."],["Silme","Cam, çerçeve ve silikonu sırayla temizleriz."],["Vitrin","Mağazada açılış saatinden önce bitiririz."]],"k":"Camlarınız için bir gün seçelim."},"İnşaat sonrası temizlik":{"s":"Boya, silikon ve harç lekesi cama zarar vermeden alınır.","o":"Daire için kaba ve ince temizlik yapar, moloz alımını üstleniriz. Cam ve fayanstaki boya ile harç lekelerini çıkarırız.","u":[["Moloz","Kalan atığı ve ambalajı daireden çıkarırız."],["Kaba temizlik","Toz, harç ve boya artığını sıyırıp süpürürüz."],["İnce temizlik","Cam, fayans, dolap içi ve armatür parlatılır."],["Teslim","Anahtar teslimi öncesi daireyi birlikte geziriz."]],"k":"Daireniz taşınmaya hazır hale gelsin."},"Dezenfeksiyon":{"s":"Kullandığımız ürün ve uygulama alanı size yazılı bildirilir.","o":"Ev ve iş yeri dezenfeksiyonu ile klima hattı temizliği yaparız. Belgeli uygulamada kullanılan ürün ve alan kayda geçer.","u":[["Alan","Mekânı, kullanım amacını ve yüzeyleri görürüz."],["Ürün","Mekâna uygun ürünü seçer, adını size söyleriz."],["Uygulama","Havalandırma ve bekleme süresine göre uygularız."],["Belge","Yapılan uygulamayı kayıt ve belgeyle teslim ederiz."]],"k":"Mekânınız için uygulama planı isteyin."},"Bahçe bakımı":{"s":"Çim boyu mevsime, budama ağaç türüne göre yapılır.","o":"Çim biçme, ağaç budama ve sulama bakımı yaparız. Aylık bahçe planında hangi ay hangi işin yapılacağı baştan bellidir.","u":[["Bahçe turu","Bitkileri, çimi ve sulama hattını gezeriz."],["Takvim","Mevsime göre biçme ve budama aylarını yazarız."],["Budama","Ağacın türüne göre dal alırız."],["Sulama","Hattı ve zamanlayıcıyı kontrol ederiz."]],"k":"Bahçenizin aylık planını çıkaralım."},"Havuz bakımı":{"s":"Kimyasalı tahminle değil, su analizine bakarak veririz.","o":"Aylık havuz bakımında su analizi, kimyasal dengeleme ve filtre temizliği yaparız. Ölçüm değerlerini size not ederiz.","u":[["Su analizi","pH ve klor değerini test setiyle ölçeriz."],["Dengeleme","Değer sapmışsa kimyasalı ölçüye göre ekleriz."],["Filtre","Kum ya da kartuş filtreyi yıkarız."],["Dip","Dibi süpürür, skimmer sepetini boşaltırız."]],"k":"Havuzunuzun su değerlerini ölçelim."},"Yat temizliği":{"s":"Tik güverte ayrı, kabin kumaşı ayrı ürünle temizlenir.","o":"Yat iç temizliği, güverte yıkama ve sezon açılış temizliği yaparız. Marina içinde, yatınız bağlıyken çalışırız.","u":[["Marina","Yatın bağlı olduğu yeri ve giriş iznini alırız."],["Kabin","İç mekânı, banyoyu ve yatak odasını temizleriz."],["Güverte","Tuz izini tatlı suyla, tiki uygun ürünle yıkarız."],["Sezon","İlk çıkıştan önce tüm yatı baştan geçeriz."]],"k":"Sezon öncesi yatınızı hazırlayalım."},"Tekne kiralama":{"s":"Tekneyi, kaptanı ve gün planını önceden netleştiririz.","o":"Günlük, saatlik ve kaptanlı tekne kiralarız. Doğum günü gibi özel gün organizasyonlarında yemek ve süsleme ihtiyacını da planlarız.","u":[["Kişi sayısı","Kaç kişi olacağınızı teknenin kapasitesiyle eşleştiririz."],["Rota","Koy ve duruş yerlerini hava durumuna göre seçeriz."],["Kaptan","Güvenlik anlatımını yapar, can yeleklerini gösteririz."],["Dönüş","Limana dönüş saatini baştan konuşuruz."]],"k":"Tekne gününüzü birlikte planlayalım."},"Tur şirketi":{"s":"Programdaki her durak, yemek ve saat önceden yazılıdır.","o":"Günübirlik tur, hafta sonu turu, yurt dışı tur ve kurumsal gezi düzenleriz. Programda dahil olanlar ve olmayanlar yazılı verilir.","u":[["Program","Güzergâhı, durakları ve dönüş saatini paylaşırız."],["Dahil","Ulaşım, yemek ve giriş ücretlerinin neyi kapsadığını yazarız."],["Kayıt","Yolcu isimleri ve iletişim bilgileri alınır."],["Rehber","Gün boyu yanınızda bir rehber bulunur."]],"k":"Turunuz için yerinizi ayırtın."},"Seyahat acentesi":{"s":"Bilet, otel ve vize tek masada, tek tek kontrol edilir.","o":"Uçak bileti, otel rezervasyonu, vize desteği ve paket tur ayarlarız. Kurumsal seyahatte toplantı saatine göre uçuş seçeriz.","u":[["Tarih","Gidiş dönüş tarihlerini ve esnekliğinizi sorarız."],["Vize","Gerekli belgeleri listeler, başvuruyu takip ederiz."],["Rezervasyon","Uçuş ve otel kaydını pasaporttaki isimle gireriz."],["Yolculuk","Biletleri ve otel belgelerini çıkıştan önce göndeririz."]],"k":"Seyahatiniz için tarihleri paylaşın."},"Turist rehberi":{"s":"Tarihi anlatırım, kalabalıkta da grubu kaybetmeden gezdiririm.","o":"Şehir turu, ören yeri gezisi ve yürüyüş turlarında çok dilli rehberlik yaparız. Anlatı grubun ilgisine ve yürüme temposuna göre ayarlanır.","u":[["Dil","Grubun dilini ve yaş aralığını öğrenirim."],["Rota","Ören yeri girişlerini ve gölgeli durakları planlarım."],["Anlatım","Taşların arkasındaki hikâyeyi sahada anlatırım."],["Mola","Su, tuvalet ve fotoğraf molalarını yerleştiririm."]],"k":"Gezinizin rotasını birlikte çizelim."},"Yat turu":{"s":"Yemek, müzik ve yüzme molası gün boyu akışa göre yapılır.","o":"Günlük yat turu, özel yat kiralama ve gün batımı turu düzenleriz. Öğle yemeği dahil seçeneğinde menüyü önceden söyleriz.","u":[["Biniş","Marinadaki yeri ve biniş saatini bildiririz."],["Koy","İlk yüzme molası için sakin bir koy seçeriz."],["Yemek","Öğle yemeği teknede servis edilir."],["Gün batımı","Dönüşte güneşi denizden izlersiniz."]],"k":"Yat turu için yerinizi ayırın."},"Dalış okulu":{"s":"İlk nefesinizi sığ suda, yanınızda eğitmenle alırsınız.","o":"Tanışma dalışı, Open Water eğitimi ve rehberli dalış yapıyoruz. Ekipman kiralama da var, ilk dalıştan önce kısa bilgilendirme veriyoruz.","u":[["Brifing","Kuralları ve el işaretlerini karada öğretiriz."],["Ekipman","Maske, palet ve tüpü ölçünüze göre veririz."],["Sığ su","Nefes ve denge alıştırmasını sığ suda yaparız."],["Dalış","Eğitmenle birlikte planlı derinliğe ineriz."]],"k":"Tanışma dalışına yer ayırtın."},"Yamaç paraşütü":{"s":"Uçuşu pilot yönetir, siz yalnızca manzaraya bakarsınız.","o":"Tandem uçuş yaparız. Video ve fotoğraf, otelden alma ve grup uçuşu seçeneklerini rüzgâr durumuna göre planlarız.","u":[["Rüzgâr","Pilot o günün rüzgârına bakıp uçuşa karar verir."],["Servis","Sizi otelden alıp kalkış tepesine çıkarırız."],["Donanım","Kask, emniyet kemeri ve paraşütü pilot kontrol eder."],["Kalkış","Birkaç adım koşar, havalanırsınız."]],"k":"Uçuş günü için yerinizi ayırın."},"Rafting":{"s":"Kürek komutlarını dereye girmeden karada öğretiriz.","o":"Günlük rafting, öğle yemekli rafting ve grup programı yaparız. Otelden alıp dönüşte otele bırakırız.","u":[["Yelek","Kask ve can yeleğini beden ölçünüze göre veririz."],["Eğitim","Kürek komutlarını ve suya düşme halini karada anlatırız."],["Nehir","Botta sizinle birlikte bir rehber ilerler."],["Yemek","Dönüşte nehir kenarında öğle yemeği yersiniz."]],"k":"Rafting günü için yerinizi ayırtın."},"Günübirlik tur":{"s":"Sabah çıkar, akşam otelinize dönersiniz, aradakiler yazılıdır.","o":"Tekne turu, jeep safari ve antik kent gezisini otelden alarak düzenleriz. Hangi durağın ne kadar sürdüğünü önceden söyleriz.","u":[["Alış","Sizi otelinizden belirlenen saatte alırız."],["Durak","Antik kent, koy ve yemek molasını sırayla gezeriz."],["Safari","Jeepte toz yolda köy ve vadi durakları vardır."],["Dönüş","Akşam yine otelinizin önünde bırakırız."]],"k":"Günübirlik turunuzu seçin."},"Araç transfer":{"s":"Uçağınız rötar yapsa da şoför uçuşu izleyip sizi bekler.","o":"Havalimanı karşılama, şehir içi transfer, saatlik VIP araç ve şehirler arası transfer yaparız. Uçuş numaranızı alıp inişi izleriz.","u":[["Uçuş no","Uçuş numaranızı alır, iniş saatini takip ederiz."],["Karşılama","Şoför çıkışta adınız yazılı tabelayla bekler."],["Bagaj","Valizleri araca biz yerleştiririz."],["Varış","Sizi adrese bırakır, dönüş transferini ayarlarız."]],"k":"Transfer için uçuş bilginizi gönderin."},"Taksi durağı":{"s":"Durağı arayın, en yakın araç adresinize yönlensin.","o":"Durak çağrısı, havalimanı yolculuğu ve şehir dışı yolculuk yaparız. Düzenli müşterilere ay sonu hesap açabiliriz.","u":[["Çağrı","Adresinizi söyler, en yakın aracı yönlendiririz."],["Taksimetre","Yolculuk taksimetreyle başlar, tutar ekranda görünür."],["Şehir dışı","Gidilecek yer için ücret önceden konuşulur."],["Hesap","Düzenli müşteriye ay sonunda toplu hesap çıkarırız."]],"k":"Durağımızı arayın, araç yola çıksın."},"Atölye":{"s":"Önce numune yapar, beğendiğiniz ölçüde seri üretiriz.","o":"Numune, küçük seri üretim, özel sipariş ve ölçüye göre imalat yapıyoruz. Üretime geçmeden elinizde çalışan bir örnek olur.","u":[["Ölçü","Çizim ya da ölçüyü alıp malzemeyi seçeriz."],["Numune","Tek parça deneme üretip size gösteririz."],["Düzeltme","Gördüğünüz farkı kalıba ya da çizime işleriz."],["Seri","Onaylı numuneye bakarak küçük seri çıkarırız."]],"k":"Numune için ölçünüzü gönderin."},"Üretim tesisi":{"s":"Fason işi tesiste yerinde görür, sevkiyat gününü bilirsiniz.","o":"Seri üretim ve fason üretim yaparız. Kontrol adımları ve sevkiyat planı yazılı olur, isterseniz tesisi gezebilirsiniz.","u":[["Teknik föy","Ürün ölçüsü ve ambalaj şartı yazılır."],["Numune","Hattan çıkan ilk parçayı onayınıza sunarız."],["Hat","Seri üretimde ara kontrol noktalarında örnek alırız."],["Sevkiyat","Paletleme ve yükleme gününü önceden bildiririz."]],"k":"Tesisi gezmek için randevu alın."},"Tekstil atölyesi":{"s":"Kumaş kesilmeden önce numune dikilip size gösterilir.","o":"Kesim ve dikim, numune, fason üretim, baskı ve nakış yapar, ürünleri paketleriz. Beden tablonuza göre çalışırız.","u":[["Kalıp","Beden tablosuna göre kalıbı hazırlarız."],["Numune","Kumaşı kesmeden önce örnek dikip gösteririz."],["Kesim","Pastal dizip fireyi azaltarak keseriz."],["Dikim","Baskı ya da nakıştan sonra ütü ve paket gelir."]],"k":"Numune dikimi için kalıbınızı getirin."},"Mobilya üretimi":{"s":"Ölçü sizin odanızdan alınır, mobilya o ölçüye üretilir.","o":"Ölçüye özel üretim, ofis mobilyası, mutfak ve dolap yaparız. Otel projelerinde adetli üretir, montajı da kendimiz yaparız.","u":[["Ölçü","Duvar, tesisat ve kapı hizalarını yerinde alırız."],["Çizim","Kesimden önce çizimi ve malzeme rengini onaylatırız."],["Üretim","Paneller atölyede kesilir, kenar bandı yapılır."],["Montaj","Parçaları yerinde birleştirir, kapak ayarını yaparız."]],"k":"Odanıza ölçü almaya uğrayalım."},"Metal işleme":{"s":"Çiziminizi getirin, toleransını birlikte konuşalım.","o":"CNC torna, CNC freze, lazer kesim, kaynak ve yüzey işlem yaparız. Parça çiziminden ölçü toleransını okuyup üretiriz.","u":[["Çizim","Teknik resmi ve tolerans değerlerini inceleriz."],["Malzeme","Sac, mil ya da profil cinsini belirleriz."],["Tezgâh","Torna, freze ya da lazerde parçayı işleriz."],["Yüzey","Ölçü kontrolünden sonra boya veya kaplama yapılır."]],"k":"Parça çiziminizi bize gönderin."},"3D baskı":{"s":"Modelinizi önce küçük bir deneme baskısında görürsünüz.","o":"Prototip baskı, küçük seri, reçine baskı ve son işlem yaparız. Modeliniz yoksa tasarım desteği veririz.","u":[["Model","STL dosyanızı açar, duvar kalınlığına bakarız."],["Malzeme","Filament ya da reçineyi kullanım yerine göre seçeriz."],["Baskı","Parçayı katman katman basarız."],["Son işlem","Destekleri alır, zımpara ve boya yaparız."]],"k":"Dosyanızı gönderin, baskıya hazırlayalım."},"Plastik enjeksiyon":{"s":"Kalıp çıkmadan önce parçanın çekmesini hesaplarız.","o":"Kalıp tasarımı, seri üretim, renk ayarı ve paketleme yaparız. Seriye geçmeden numune parçayı size veririz.","u":[["Kalıp","Parça çiziminden çekme payıyla kalıp tasarlanır."],["Deneme","Kalıptan çıkan ilk parçayı ölçeriz."],["Renk","Masterbatch ile istenen tonu tuttururuz."],["Seri","Makine ayarı sabitlenir, paketleme yapılır."]],"k":"Parçanız için kalıbı konuşalım."},"Ambalaj":{"s":"Ürün kutuya uymuyorsa bunu üretimden önce biz söyleriz.","o":"Karton kutu, oluklu koli, etiket ve baskılı poşet üretir, toptan sipariş alırız. Ürünü getirirseniz kutuyu ona göre keseriz.","u":[["Ölçü","Ürünü ya da boyutlarını alıp kutu ölçüsünü çıkarırız."],["Dizilim","Baskı yerleşimini ve renk dosyasını hazırlarız."],["Baskı","Dijital örnek çıkar, onaydan sonra basılır."],["Kesim","Kalıpla kesip yapıştırır, koliler halinde sevk ederiz."]],"k":"Ürününüze uygun kutuyu ölçelim."},"Gıda üretimi":{"s":"Ürün sizin, tarif sizin, biz hattı ve takibi yürütürüz.","o":"Fason gıda üretimi, özel etiket, numune ve toptan sevkiyat yapıyoruz. Üretim partilerinin analiz takibini kayda alırız.","u":[["Tarif","Reçeteyi ve hammadde şartını yazılı alırız."],["Numune","Küçük partide tadı ve görünüşü birlikte onaylarız."],["Parti","Üretimde parti numarası verip analizi takip ederiz."],["Sevkiyat","Paketli ürünü etiketiyle toptan göndeririz."]],"k":"Tarifinizle üretim için görüşelim."},"Kozmetik üretimi":{"s":"Formülü, ambalajı ve etiketi tek yerden yürütürüz.","o":"Fason kozmetik, formül geliştirme, ambalaj, etiket ve ürün dosyası takibi yapıyoruz. Önce numune hazırlar, sonra seriye geçeriz.","u":[["Formül","İstediğiniz doku ve koku üzerinden formülü geliştiririz."],["Numune","Küçük partide krem ya da losyonu deneyip size veririz."],["Ambalaj","Şişe, tüp ve etiketi ürüne göre seçeriz."],["Dosya","Ürün dosyasını hazırlar, evrak takibini yaparız."]],"k":"Ürün fikrinizi numuneye çevirelim."},"Kalıpçı":{"s":"Kalıbı açmadan önce parçanın nasıl çıkacağını çizimde gösteririz.","o":"Plastik kalıp, sac kalıp, kalıp tamiri ve teknik çizim yaparız. Kalıp bitince numune baskı alıp ölçüsünü size gösteririz.","u":[["Çizim","Parça modelinden kalıp bölme çizgisini belirleriz."],["Çelik","Kalıp çeliğini kullanım adedine göre seçeriz."],["İşleme","Kalıp boşluğunu freze ve erozyonla açarız."],["Numune baskı","Deneme baskıyla ölçüyü kontrol eder, rötuş yaparız."]],"k":"Kalıp çiziminizi bize gösterin."},"Lazer kesim":{"s":"Dosyanız nasıl çizildiyse o ölçüyle kesilir.","o":"Sac, ahşap ve pleksi lazer kesim yapar, teknik çizimi dosyaya çeviririz. Toplu siparişte parçaları sıralı paketleriz.","u":[["Dosya","DXF ya da çiziminizi açar, ölçüleri kontrol ederiz."],["Malzeme","Sac, ahşap ya da pleksinin kalınlığını belirleriz."],["Dizilim","Parçaları plakaya fire az olacak şekilde dizeriz."],["Kesim","Kesilen parçaların kenarını temizleyip sayarak veririz."]],"k":"Çiziminizi gönderin, kesime alalım."},"Tabela üretimi":{"s":"Tabelayı üretmeden önce cepheyi yerinde ölçeriz.","o":"Işıklı tabela, kutu harf, araç giydirme ve vinil kesim yaparız. Cephede ölçü alır, montajı da kendimiz bitiririz.","u":[["Cephe","Duvar ya da vitrinin ölçüsünü yerinde alırız."],["Tasarım","Logoyu cephe fotoğrafına yerleştirip size göstereriz."],["Üretim","Harfler kesilir, ışık ve trafo bağlanır."],["Montaj","Tabelayı asar, elektrik bağlantısını yaparız."]],"k":"Cephenizin ölçüsünü almaya gelelim."},"Promosyon ürünleri":{"s":"Logonuz kalemde de termosta da net çıksın diye örnek basarız.","o":"Baskılı kalem, kupa, termos, tişört ve ajanda hazırlar, toplu teslim ederiz. Sipariş öncesi logo baskı örneği gösteririz.","u":[["Ürün","Dağıtım yerine ve bütçenize uygun ürünü seçeriz."],["Logo","Dosyayı ürünün baskı alanına yerleştiririz."],["Örnek","Tek adet baskı alıp onayınıza sunarız."],["Toplu teslim","Hepsini sayıp paketler, adresinize getiririz."]],"k":"Logonuzu üründe önce görün."},"Cam işleme":{"s":"Temperli cam fırından çıkınca kesilemez, ölçüyü yerinde alırız.","o":"Isıcam üretimi, temperli cam, kumlama ve ölçüye kesim yaparız. Ölçüyü cam fırına girmeden baştan netleştiririz.","u":[["Ölçü","Boşluğu yerinde ölçüp milimetre payını yazarız."],["Kesim","Camı tezgâhta ölçüye göre keseriz."],["Temper","Güvenlik camı gereken yerde camı fırına veririz."],["Kenar","Kenarı işler, kumlama ya da ısıcam birleştirmesi yaparız."]],"k":"Cam ölçünüzü yerinde alalım."},"Mermer işleme":{"s":"Tezgâh şablonla ölçülür, duvarınız eğri olsa da oturur.","o":"Mutfak tezgâhı, basamak ve banyo mermeri yaparız. Yerinde ölçü alır, kesimden sonra montajı da kendimiz yaparız.","u":[["Şablon","Tezgâh yerinde ölçülüp şablon çıkarılır."],["Plaka","Damar yönünü görüp plakayı siz seçersiniz."],["Kesim","Evye ve ocak boşluğu kesilip kenar işlenir."],["Montaj","Yerine oturtur, birleşim yerini dolgu ile kapatırız."]],"k":"Tezgâhınız için şablon çıkaralım."},"Seramik atölyesi":{"s":"Çamur elinizde şekil alır, fırında seramiğe döner.","o":"El yapımı seramik üretir, tornada seramik dersi veririz. Kişiye özel ve toplu hediye siparişi alırız.","u":[["Çamur","Çamuru yoğurup avucunuzda şekillendirirsiniz."],["Torna","Çarkta ilk kabınızı hocayla birlikte çekersiniz."],["Kuruma","Kabın kurumasını bekler, bisküvi fırınına veririz."],["Sır","Sırlanmış kabı ikinci fırından alırsınız."]],"k":"Çamurla tanışmak için atölyeye gelin."},"Deri atölyesi":{"s":"Dikiş elle atılır, deri size göre kesilir.","o":"El yapımı çanta, cüzdan ve kemer üretir, kişiye özel sipariş alırız. Deri onarımı da yaparız.","u":[["Deri","Rengini ve dokusunu elinizle dokunarak seçersiniz."],["Kalıp","Parçalar kartondan kalıpla deriden kesilir."],["Dikiş","Kenarlar yakılıp sıvanır, dikiş elle atılır."],["Cila","Kenar boyanır, ürüne son cila verilir."]],"k":"Derinizi seçmek için atölyeye uğrayın."},"Çekici hizmeti":{"s":"Aracı yüklemeden önce vites ve el frenini kontrol ederiz.","o":"Şehir içi ve şehirler arası çekme, yol yardımı ve kaza yerinden kurtarma yaparız. Hasara göre yükleme yöntemi seçeriz.","u":[["Konum","Yerinizi telefonla paylaşırsınız, biz yola çıkarız."],["Durum","Aracın çalışıp çalışmadığını, hasarı ve vitesi sorarız."],["Yükleme","Aracı kayar kasaya yavaşça çekip bağlarız."],["Teslim","Servise ya da istediğiniz adrese bırakırız."]],"k":"Yolda kaldıysanız konumunuzu gönderin."},"Tesisatçı":{"s":"Duvarı kırmadan önce suyun nereden kaçtığını cihazla buluruz.","o":"Su kaçağı tespiti, tıkanıklık açma, musluk ve batarya değişimi, pis su ve kalorifer tesisatı yaparız.","u":[["Ana vana","Suyu keser, arızanın hangi hatta olduğuna bakarız."],["Tespit","Cihazla kaçağı dinleyip yerini işaretleriz."],["Onarım","Boruyu ve contayı yenileriz, gerekirse duvarı açarız."],["Basınç","Hattı basınç altında deneyip kapatırız."]],"k":"Su kaçağınız için bizi arayın."},"Elektrikçi":{"s":"Sigorta atıyorsa nedenini bulur, sigortayı büyütmeyiz.","o":"Arıza tespiti, priz ve anahtar, sigorta panosu, aydınlatma montajı ve tesisat yenileme yaparız.","u":[["Pano","Sigorta panosuna bakıp hangi hattın attığını buluruz."],["Ölçüm","Hattı avometreyle ölçer, kaçağı ararız."],["Onarım","Kablo, priz ya da sigortayı yenileriz."],["Deneme","Yük verip hattın ısınmadığını kontrol ederiz."]],"k":"Arızalı hattı bize gösterin."},"Kombi servisi":{"s":"Kombiniz kış gelmeden bakımdan geçer.","o":"Yıllık kombi bakımı, arıza tespiti, petek temizliği, kombi ve parça değişimi yaparız. Parçanın neden değiştiğini gösteririz.","u":[["Basınç","Kombi basıncını ve hata kodunu okuruz."],["Bakım","Eşanjör, fan ve brülör çevresini temizleriz."],["Petek","Sirkülasyonu görüp gerekirse petek temizliği öneririz."],["Parça","Değişen parçayı eskisiyle birlikte size gösteririz."]],"k":"Kombi bakımınız için gün seçin."},"Klima servisi":{"s":"Gaz eksik mi, filtre mi tıkalı, ölçüp söyleriz.","o":"Klima bakımı, gaz dolumu, montaj, sökme taşıma ve arıza tespiti yaparız.","u":[["Filtre","İç ünitenin filtresini ve kanalını açıp bakarız."],["Gaz","Manometreyle basıncı ölçer, eksik varsa tamamlarız."],["Dış ünite","Fan ve petekteki tozu yıkarız."],["Deneme","Soğutmayı çalıştırıp çıkış havasını kontrol ederiz."]],"k":"Klimanız için bakım günü belirleyelim."},"Beyaz eşya servisi":{"s":"Makineyi açmadan önce hata kodunu ve sesi dinleriz.","o":"Çamaşır makinesi, bulaşık makinesi, buzdolabı ve fırın tamiri ile arıza tespiti yaparız.","u":[["Belirti","Ne zaman nasıl bozulduğunu ve hata kodunu dinleriz."],["Söküm","Makineyi açıp pompa, rezistans ya da kartı kontrol ederiz."],["Parça","Arızalı parçayı eskisiyle gösterir, onayınızı alırız."],["Deneme","Takıp tam program çalıştırarak sızıntıya bakarız."]],"k":"Arızalı cihazınızı bize anlatın."},"Çilingir":{"s":"Kapıyı mümkünse kırmadan, kilide zarar vermeden açarız.","o":"Kapı açma, çelik kapı açma, kilit değişimi, kasa açma ve araç kapısı açma yaparız. Önce kapının size ait olduğunu doğrularız.","u":[["Doğrulama","Kapının size ait olduğunu kimlikle teyit ederiz."],["Kilit","Silindirin türüne bakıp en az hasarlı yolu seçeriz."],["Açma","Kapıyı özel takımla açarız."],["Yenileme","Gerekirse silindiri ya da kilidi değiştiririz."]],"k":"Kapıda kaldıysanız bizi arayın."},"Marangoz":{"s":"Dolap ölçüsü duvara göre çıkar, raf eğri duvara uydurulur.","o":"Ölçüye özel dolap, kapı tamiri, mobilya onarımı, raf ve kitaplık, ahşap kaplama yaparız.","u":[["Ölçü","Duvar ve tavan eğimini yerinde alırız."],["Malzeme","Ahşap ya da MDF kaplamayı numunesiyle seçersiniz."],["Atölye","Parçalar kesilir, zımparalanır, vernik ya da boya yapılır."],["Montaj","Yerinde birleştirir, kapak ve çekmece ayarını yaparız."]],"k":"Dolabınız için ölçüye gelelim."},"Camcı":{"s":"Kırık camı çıkarırken çerçeveyi koruyup yenisini ölçüsüne keseriz.","o":"Cam kesimi, ısıcam değişimi, duşakabin, vitrin camı ve ayna montajı yaparız.","u":[["Ölçü","Kırık camın kalınlığını ve çerçeve boşluğunu ölçeriz."],["Söküm","Eski camı ve macunu temizleriz."],["Kesim","Yeni camı tezgâhta ölçüye göre keseriz."],["Montaj","Camı yerleştirir, silikonla sabitleriz."]],"k":"Cam boşluğunu ölçmeye gelelim."},"PVC pencere":{"s":"Eski pencere sökülürken duvar ve boyanın zarar görmemesine bakarız.","o":"PVC pencere, sineklik, panjur, eski pencere sökümü ve ısıcam değişimi yaparız.","u":[["Ölçü","Pencere boşluğunu ve doğrama payını ölçeriz."],["Profil","Cam rengini ve açılım şeklini siz seçersiniz."],["Söküm","Eski pencereyi duvara zarar vermeden çıkarırız."],["Montaj","Yeni pencereyi terazide sabitler, köpük ve silikon yaparız."]],"k":"Pencereleriniz için ölçüye gelelim."},"Alüminyum doğrama":{"s":"Cephe ve kış bahçesi ölçüsü keşifte netleşir.","o":"Alüminyum doğrama, kış bahçesi, cephe giydirme ve giyotin cam yaparız. Keşif ve ölçüyü yerinde alırız.","u":[["Keşif","Cephenin yapısını ve rüzgâr yükünü yerinde görürüz."],["Profil","Isı yalıtımlı profil ve cam türünü seçeriz."],["Üretim","Profiller kesilir, köşeler birleştirilir."],["Montaj","Doğramayı yerleştirir, su yalıtımını kontrol ederiz."]],"k":"Keşif için bizi arayın."},"Demirci":{"s":"Korkuluğun yüksekliğini ve aralığını çizerken konuşuruz.","o":"Korkuluk, bahçe kapısı, ferforje, çelik merdiven ve kaynaklı onarım yaparız.","u":[["Ölçü","Kapı ya da merdiven açıklığını yerinde alırız."],["Model","Desenin çizimini yapıp onayınıza sunarız."],["Kaynak","Profilleri keser, kaynaklar, taşlarız."],["Boya","Pasa karşı astar ve boya vururuz."]],"k":"Kapınızın ya da korkuluğun ölçüsüne gelelim."},"Kaynakçı":{"s":"Kırık parçayı atmadan önce kaynakla kurtarıp kurtaramayacağımıza bakarız.","o":"Yerinde kaynak, argon kaynak, demir doğrama, kaynaklı onarım ve şantiye işleri yaparız.","u":[["Malzeme","Parçanın demir, paslanmaz ya da alüminyum olduğuna bakarız."],["Hazırlık","Kırık yeri açıp yağ ve pastan temizleriz."],["Kaynak","Malzemeye göre elektrot ya da argon kullanırız."],["Taşlama","Kaynak izini taşlar, gerekirse boyarız."]],"k":"Kırık parçanızı bize gösterin."},"Asansör servisi":{"s":"Arıza çağrısında kabinde mahsur kalan varsa önce onu çıkarırız.","o":"Aylık bakım sözleşmesi, arıza çağrısı, yıllık muayene hazırlığı, revizyon, kapı ve panel değişimi yaparız.","u":[["Çağrı","Kabinde kalan olup olmadığını ilk sorarız."],["Bakım","Halat, fren ve kat kapılarını aylık kontrol ederiz."],["Muayene","Yıllık muayene öncesi eksikleri listeleyip gideririz."],["Revizyon","Eski panoyu ya da kapıyı yenileriz."]],"k":"Asansörünüz için bakım sözleşmesi yapalım."},"Güvenlik kamerası":{"s":"Kamera nereye bakacak, önce sizinle yerinde belirleriz.","o":"Kamera seti kurulumu, kayıt cihazı, telefondan izleme, bakım ve alarm sistemi yaparız.","u":[["Açı","Hangi kapı ve köşenin görüntüleneceğini yerinde belirleriz."],["Kablo","Kabloyu gizler, kayıt cihazına bağlarız."],["Telefon","Görüntüyü telefonunuza kurar, nasıl bakacağınızı gösteririz."],["Kayıt","Disk kapasitesine göre kaç gün saklanacağını söyleriz."]],"k":"Kamera noktalarını birlikte seçelim."},"Uydu anten":{"s":"Çanağı sinyal ölçerek ayarlar, kanallar gelmeden kalkmayız.","o":"Çanak anten montajı, merkezi sistem, çoklu daire kurulumu ve sinyal ayarı yaparız.","u":[["Yön","Güney yönünü ve önündeki engeli kontrol ederiz."],["Montaj","Çanağı sağlam bir yere sabitleriz."],["Sinyal","Cihazla sinyal gücünü en uygun noktaya getiririz."],["Kablo","Dairelere kabloyu çeker, her prizde kanalı deneriz."]],"k":"Çanak anteniniz için bizi arayın."},"Jeneratör":{"s":"Elektrik kesilince jeneratör kendiliğinden devreye girecek şekilde kurulur.","o":"Jeneratör satışı, yıllık bakım, arıza servisi, kiralama ve otomatik transfer panosu yaparız.","u":[["Güç","Bağlanacak cihazların toplam gücünü hesaplarız."],["Yerleşim","Egzoz, yakıt ve havalandırma yerini belirleriz."],["Pano","Otomatik transfer panosunu şebekeye bağlarız."],["Deneme","Elektriği keser, jeneratörün devreye girişini izleriz."]],"k":"Jeneratör için gücünüzü hesaplayalım."},"Güneş enerjisi":{"s":"Çatınızın güneşi nasıl aldığına panelden önce bakarız.","o":"Çatı GES keşfi, bağ evi sistemi, akü ve invertör, panel temizliği, kurulum ve izin sürecini yürütürüz.","u":[["Çatı","Yönü, eğimi ve gölgeyi yerinde ölçeriz."],["Tüketim","Faturanızdan ne kadar enerji harcadığınızı okuruz."],["Sistem","Panel, invertör ve gerekiyorsa aküyü belirleriz."],["İzin","Dağıtım şirketine verilecek evrakı hazırlarız."]],"k":"Çatınızın güneş durumuna bakalım."},"Doğalgaz tesisatı":{"s":"Gaz açılmadan önce hat sızdırmazlık testinden geçer.","o":"Doğalgaz projesi, daire tesisatı, kombi bağlantısı, sızdırmazlık testi ve abonelik işlemlerini yaparız.","u":[["Proje","Binadaki yerleşime göre boru güzergâhını çizeriz."],["Tesisat","Boruyu döşer, sayaç ve kombi noktasını hazırlarız."],["Test","Hattı basınç altında bekletip sızdırmazlığı denetleriz."],["Abonelik","Gaz açma başvurusunu sizinle birlikte takip ederiz."]],"k":"Doğalgaz projeniz için bizi arayın."},"Su arıtma":{"s":"Musluğunuzdaki suyu görüp cihazı ona göre seçeriz.","o":"Arıtma cihazı montajı, filtre değişimi, yıllık bakım ve sebil kiralama yaparız.","u":[["Su","Suyun sertliğine ve kullanım miktarına bakarız."],["Cihaz","Mutfak altına sığan modeli seçeriz."],["Montaj","Giriş vanasını bağlar, kaçak olup olmadığına bakarız."],["Filtre","Değişim zamanını size not eder, hatırlatırız."]],"k":"Arıtma için suyunuzu inceleyelim."},"Böcek ilaçlama":{"s":"Böceğin yuvasını bulmadan ilaç sıkmanın anlamı yoktur.","o":"Ev ve iş yeri ilaçlama, hamam böceği uygulaması, haşere kontrol sözleşmesi ve bahçe ilaçlama yaparız.","u":[["Tespit","Böceğin girdiği ve yuvalandığı yeri ararız."],["İlaç","Kullanılacak ilacı ve bekleme süresini söyleriz."],["Uygulama","Çatlak, süpürgelik ve gider çevresine uygularız."],["Kontrol","Sözleşmeli işyerinde düzenli kontrol ziyareti yaparız."]],"k":"Böcek sorununuzu bize anlatın."},"Perde montajı":{"s":"Perdeyi dikmeden önce korniş ve tavanı yerinde ölçeriz.","o":"Perde montajı, stor perde ölçüsü, korniş takma ve yerinde ölçü alma yaparız.","u":[["Ölçü","Pencere genişliğini ve tavandan zemine boyu ölçeriz."],["Korniş","Tavana ya da duvara uygun kornişi seçeriz."],["Takma","Kornişi terazide sabitler, perdeyi asarız."],["Pile","Perde boyunu ve pile düzenini yerinde ayarlarız."]],"k":"Perde ölçüsü için yerinize gelelim."},"Dijital ürün":{"s":"Ödemeden sonra ürününüz ve lisans anahtarınız e-postanıza gelir.","o":"Dijital ürün mağazası kurar, otomatik teslim, lisans anahtarı, fatura ve abonelik takibi ile destek veririz.","u":[["Sepet","Ürünü seçer, ödemenizi yaparsınız."],["Teslim","İndirme bağlantısı ve lisans anahtarı e-postanıza otomatik düşer."],["Fatura","Faturanız ve abonelik bilginiz hesabınızda durur."],["Destek","Anahtar çalışmazsa destek formundan yazarsınız."]],"k":"Dijital ürününüzü satışa açalım."},"Reklam ajansı":{"s":"Hangi reklamın satış getirdiğini aylık raporda görürsünüz.","o":"Marka stratejisi, sosyal medya yönetimi, reklam yönetimi ve tasarım işlerini yürütür, aylık rapor veririz.","u":[["Marka","Kime neyi hangi sesle anlatacağınızı yazıya döküyoruz."],["Takvim","Aylık paylaşım planını ve reklam bütçesini çıkarırız."],["Yayın","Paylaşımlar ve reklamlar yayına girer, yorumlara bakılır."],["Rapor","Her ay hangi içeriğin işe yaradığını gösteririz."]],"k":"Markanız için aylık plan çıkaralım."},"Matbaa":{"s":"Baskıya girmeden önce renk ve kesim ölçüsünü prova ile onaylarsınız.","o":"Kartvizit, broşür, afiş, ambalaj baskı ve kurumsal evrak basarız.","u":[["Dosya","PDF dosyanızı taşma payı ve çözünürlük için kontrol ederiz."],["Prova","Renk provasını size göstermeden basmayız."],["Baskı","Kâğıt cinsine göre baskıyı alırız."],["Kesim","Kesim, kıvırma ve ciltleme yapılıp paketlenir."]],"k":"Baskı dosyanızı bize gönderin."},"Fotoğrafçı":{"s":"Düğünde bir anı kaçırmamak için çekim akışını önceden konuşuruz.","o":"Düğün çekimi, ürün çekimi, vesikalık, aile çekimi ve kurumsal çekim yaparız.","u":[["Plan","Mekânı ve çekilecek kareleri önceden konuşuruz."],["Çekim","Işığa göre yerleşir, doğal pozlar yakalarız."],["Seçki","Kareleri ayıklar, siz beğendiklerinizi seçersiniz."],["Rötuş","Seçilen fotoğraflara renk ve rötuş yaparız."]],"k":"Çekim günü için tarihinizi söyleyin."},"Video prodüksiyon":{"s":"Senaryoyu kameradan önce yazar, ona göre çekim yaparız.","o":"Tanıtım filmi, reels paketi, drone çekimi, kurgu ve renk ile etkinlik çekimi yaparız.","u":[["Senaryo","Anlatılacak mesajı ve sahneleri yazıya dökeriz."],["Çekim","Işık, ses ve kadrajı ayarlayıp sahneleri alırız."],["Kurgu","Çekimi keser, müzik ve altyazı ekleriz."],["Renk","Renk ayarı yapar, dikey ve yatay versiyon çıkarırız."]],"k":"Videonuzun senaryosunu yazalım."},"Grafik tasarım":{"s":"Logonuz kartvizitte de tabelada da aynı durmalı.","o":"Logo tasarımı, kurumsal kimlik, sosyal medya şablonu, ambalaj ve sunum tasarımı yaparız.","u":[["Brif","Markanızı, rakipleri ve sevdiğiniz renkleri dinleriz."],["Taslak","Birkaç logo yönü çizip size sunarız."],["Revize","Seçtiğiniz yönü sizinle birlikte düzeltiriz."],["Kullanım","Logoyu her boyuta uygun dosyalarla teslim ederiz."]],"k":"Logonuzu birlikte çizelim."},"Yazılım firması":{"s":"Kodu yazmadan önce işinizin nasıl yürüdüğünü sizden dinleriz.","o":"Web uygulaması, mobil uygulama, otomasyon ve entegrasyon yapar, sonrasında bakım ve destek veririz.","u":[["Analiz","İşinizin adımlarını ve tıkandığı yeri dinleriz."],["Prototip","Ekranları çizip tıklanabilir örnek gösteririz."],["Geliştirme","Parçaları sırayla yazıp her aşamada size gösteririz."],["Canlı","Sistemi yayına alır, hata takibini sürdürürüz."]],"k":"İşinizi anlatın, ekranını çizelim."},"Bilişim":{"s":"Yedeğiniz düzenli alınır ve geri yüklenip denenir.","o":"Ağ kurulumu, sunucu ve yedekleme, siber güvenlik kontrolü, aylık bakım ve yerinde destek veririz.","u":[["Envanter","Bilgisayar, yazıcı ve ağ cihazlarını listeleriz."],["Ağ","Modem, anahtar ve Wi-Fi noktalarını yerleştiririz."],["Yedek","Dosyaların yedeğini alıp geri dönüşünü deneriz."],["Bakım","Aylık güncelleme ve güvenlik taraması yaparız."]],"k":"Ofis ağınızı birlikte gözden geçirelim."},"Fotoğraf stüdyosu":{"s":"Işık, fon ve kıyafet stüdyoda hazır, siz gelmeniz yeter.","o":"Vesikalık, aile çekimi, ürün çekimi ve stüdyo kiralama yaparız.","u":[["Fon","Çekim için fon rengini ve ışık düzenini seçersiniz."],["Poz","Fotoğrafçı sizi yönlendirir, rahat pozlar çekilir."],["Seçim","Ekranda kareleri birlikte izleyip seçersiniz."],["Baskı","Seçilenleri vesikalık ya da büyük boy basarız."]],"k":"Stüdyoda bir çekim ayarlayalım."}};
